  .card h4 { margin:0 0 8px; font-size:.9rem; }
  .note { font-size:.75rem; color:var(--muted); line-height:1.45; margin-top:8px; }
  .btn { display:inline-block; background:var(--cyan); color:#fff; border:none; border-radius:10px;
