  .viewbtn.on { border-color:var(--soon); color:var(--soon); background:rgba(90,209,255,.12); }
  .kv b { color:var(--text); }
  .pmrow { display:flex; align-items:center; gap:10px; padding:7px 8px; border:1px solid var(--border);
