    -h|--help) printf "usage: bash 39-install-all.commute-termux-v39.sh [--online] [--offline]\n"; exit 0 ;;
  esac
done

if [ -t 1 ]; then
  A="\033[1;36m"; OK="\033[1;32m"; BAD="\033[1;31m"; WARN="\033[1;33m"
  KEY="\033[1;37m"; DIM="\033[0;90m"; OFF="\033[0m"
else
