printf "\n"
printf "  ${A}|${OFF} "; type_line "$(printf '%bALL.COMMUTE%b  stars %s' "$KEY" "$OFF" "$ALLC_UI_VERSION")"
printf "  ${A}|${OFF} ${DIM}Water | show me where I am, and tell me how well you know${OFF}\n\n"

