  else printf "${WARN}missing${OFF}"; [ -n "$note" ] && printf " ${DIM}%s${OFF}" "$note"; printf "\n"; fi
}

printf "  ${KEY}dependencies${OFF}\n"
[ -n "${PREFIX:-}" ] && [ -d "$BIN" ] && T=1 || T=0
row "Termux"                "$T" "run this inside Termux"
command -v python >/dev/null 2>&1 && P=1 || P=0
