fi

if [ -z "$MODE" ]; then
  printf "  install mode:\n"
  printf "    ${KEY}Enter${OFF}  ${DIM}interface only, nothing downloaded (fast)${OFF}\n"
  printf "    ${KEY}y${OFF}      ${DIM}also refresh the station cache from ZET${OFF}\n"
