#!/usr/bin/env python3
"""
update_all.py — builds the whole-network station index for all.commute.

Downloads the ZET static GTFS zip once a day (ETag / Last-Modified aware),
keeps only the trips that actually run today, and writes a small SQLite file:

    stops(stop_id, name, lat, lon, bearing)   bearing = where its vehicles go
    dep(stop_id, t, trip_id, route, head)      t = seconds after midnight

Only stops that actually see a departure today survive, which quietly throws
out the parent stations that carry a name and a pin but never a tram.
The bearing is the mean heading of everything leaving that stop, so the app can
tell the eastbound platform from the westbound one across the street.

That is everything the app needs to answer "what is coming to the stop I am
standing at". The live GTFS-realtime feed is fetched separately, always fresh.
"""
import os
import io
import csv
import json
import time
import zipfile
import sqlite3
import hashlib
import math
import datetime
import urllib.request
import urllib.error

APPDIR = os.environ.get("ALLC_DIR", os.path.expanduser("~/.all.commute"))
DB_PATH = os.path.join(APPDIR, "network.db")
CACHE_ZIP = os.path.join(APPDIR, "zet_gtfs.zip")
STATIONS_PATH = os.path.join(APPDIR, "stations.json")
META_PATH = CACHE_ZIP + ".meta.json"
GTFS_URLS = [
    "https://www.zet.hr/gtfs-scheduled/latest",
    "https://zet.hr/gtfs-scheduled/latest",
]


def log(m):
    print("[all.commute] " + m, flush=True)


def _load_meta():
    try:
        with open(META_PATH, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _save_meta(m):
    try:
        with open(META_PATH, "w", encoding="utf-8") as f:
            json.dump(m, f)
    except Exception:
        pass


def load_stations():
    """The permanent stations: {stop_id: [name, lat, lon, bearing]}."""
    try:
        with open(STATIONS_PATH, encoding="utf-8") as f:
            d = json.load(f)
        st = d.get("stops") if isinstance(d, dict) else None
        return st if isinstance(st, dict) else {}
    except Exception:
        return {}


def save_stations(st):
    """Whole file or nothing: written beside it and renamed over it."""
    tmp = STATIONS_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"updated": int(time.time()), "count": len(st), "stops": st},
                  f, ensure_ascii=False, separators=(",", ":"))
    os.replace(tmp, STATIONS_PATH)


def db_fresh_for(ymd):
    try:
        con = sqlite3.connect(DB_PATH)
        row = con.execute("select v from meta where k='service_date'").fetchone()
        n = con.execute("select count(*) from dep").fetchone()[0]
        con.close()
        return bool(row) and row[0] == ymd and n > 0
    except Exception:
        return False


def get_gtfs(force=False):
    meta = _load_meta()
    cached = None
    if os.path.isfile(CACHE_ZIP):
        try:
            with open(CACHE_ZIP, "rb") as f:
                cached = f.read()
        except Exception:
            cached = None
    headers = {"User-Agent": "Mozilla/5.0 (Android; all-commute)"}
    if cached is not None and not force:
        if meta.get("etag"):
            headers["If-None-Match"] = meta["etag"]
        if meta.get("last_modified"):
            headers["If-Modified-Since"] = meta["last_modified"]
    last = None
    for url in GTFS_URLS:
        try:
            log("checking " + url)
            req = urllib.request.Request(url, headers=headers)
            try:
                with urllib.request.urlopen(req, timeout=180) as r:
                    data = r.read()
                    rh = r.headers
            except urllib.error.HTTPError as he:
                if he.code == 304 and cached is not None:
                    log("  unchanged on the server, using the local zip")
                    return cached
                raise
            if data[:2] != b"PK":
                log("  not a zip, trying the next mirror")
                continue
            log("  got zip, %d bytes" % len(data))
            try:
                with open(CACHE_ZIP, "wb") as f:
                    f.write(data)
                _save_meta({"etag": rh.get("ETag") or "",
                            "last_modified": rh.get("Last-Modified") or "",
                            "sha256": hashlib.sha256(data).hexdigest()})
            except Exception:
                pass
            return data
        except Exception as e:
            last = e
            log("  failed: " + repr(e))
    if cached is not None:
        log("network unavailable, using the local GTFS copy")
        return cached
    raise RuntimeError("could not download GTFS zip: %r" % (last,))


def _member(zf, name):
    for n in zf.namelist():
        if n == name or n.endswith("/" + name):
            return n
    raise KeyError(name)


def rows(zf, name):
    with zf.open(_member(zf, name)) as fh:
        txt = io.TextIOWrapper(fh, encoding="utf-8-sig", errors="replace")
        for row in csv.DictReader(txt):
            yield row


def secs(t):
    p = (t or "").strip().split(":")
    if len(p) < 3:
        return None
    try:
        return int(p[0]) * 3600 + int(p[1]) * 60 + int(p[2])
    except ValueError:
        return None


def bearing(a_lat, a_lon, b_lat, b_lon):
    """Compass heading from one stop to the next, 0 is north."""
    p = math.pi / 180
    dl = (b_lon - a_lon) * p
    y = math.sin(dl) * math.cos(b_lat * p)
    x = (math.cos(a_lat * p) * math.sin(b_lat * p) -
         math.sin(a_lat * p) * math.cos(b_lat * p) * math.cos(dl))
    return (math.degrees(math.atan2(y, x)) + 360.0) % 360.0


def todays_services(zf, today):
    wd = ["monday", "tuesday", "wednesday", "thursday",
          "friday", "saturday", "sunday"][today.weekday()]
    ymd = today.strftime("%Y%m%d")
    active = set()
    try:
        for r in rows(zf, "calendar.txt"):
            if r.get(wd) == "1" and r.get("start_date", "0") <= ymd <= r.get("end_date", "9"):
                active.add(r["service_id"])
    except KeyError:
        pass
    try:
        for r in rows(zf, "calendar_dates.txt"):
            if r.get("date") == ymd:
                if r.get("exception_type") == "1":
                    active.add(r["service_id"])
                elif r.get("exception_type") == "2":
                    active.discard(r["service_id"])
    except KeyError:
        pass
    return active


def main():
    os.makedirs(APPDIR, exist_ok=True)
    today = datetime.date.today()
    ymd = today.strftime("%Y%m%d")
    force = os.environ.get("ALLC_FORCE") == "1"
    if not force and db_fresh_for(ymd):
        log("station index already holds today, nothing to rebuild")
        return

    data = get_gtfs(force)
    zf = zipfile.ZipFile(io.BytesIO(data))

    name = {}
    route_name = {}
    for r in rows(zf, "routes.txt"):
        route_name[r["route_id"]] = (r.get("route_short_name")
                                     or r.get("route_long_name") or "?").strip()

    services = todays_services(zf, today)
    log("%d service ids run today" % len(services))

    trip_info = {}
    for r in rows(zf, "trips.txt"):
        if r.get("service_id") in services:
            trip_info[r["trip_id"]] = (
                route_name.get(r.get("route_id"), "?"),
                (r.get("trip_headsign") or "").strip())
    log("%d trips run today" % len(trip_info))

    tmp = DB_PATH + ".tmp"
    if os.path.exists(tmp):
        os.remove(tmp)
    con = sqlite3.connect(tmp)
    con.execute("pragma journal_mode=off")
    con.execute("pragma synchronous=off")
    con.execute("create table meta(k text primary key, v text)")
    con.execute("create table stops(stop_id text primary key, name text,"
                " lat real, lon real, bearing real)")
    con.execute("create table dep(stop_id text, t int, trip_id text,"
                " route text, head text)")
    con.execute("create table routes(route_id text primary key, short text)")
    con.executemany("insert or replace into routes values(?,?)",
                    list(route_name.items()))

    coord = {}
    not_platform = set()
    for r in rows(zf, "stops.txt"):
        if (r.get("location_type") or "0").strip() != "0":
            not_platform.add(r.get("stop_id"))
        try:
            _la, _lo = float(r["stop_lat"]), float(r["stop_lon"])
            if not (45.3 < _la < 46.3 and 15.3 < _lo < 16.7):
                raise ValueError("outside the Zagreb area")
            coord[r["stop_id"]] = (_la, _lo)
        except (KeyError, ValueError):
            continue
        name[r["stop_id"]] = (r.get("stop_name") or "").strip()
    log("%d stops in the feed" % len(coord))

    # Every stop collects the headings of the vehicles that leave it, so a
    # platform knows whether it sends you east or west.
    sin_sum = {}
    cos_sum = {}
    ndep = 0
    batch = []
    trips_meta = []

    def flush_trip(cur_trip, seq_rows):
        nonlocal ndep
        if not cur_trip or not seq_rows:
            return
        ti = trip_info[cur_trip]
        seq_rows.sort(key=lambda x: x[0])
        first_id, last_id = seq_rows[0][1], seq_rows[-1][1]
        trips_meta.append((cur_trip, ti[0], ti[1],
                           name.get(first_id, ""), name.get(last_id, ""),
                           seq_rows[0][2], seq_rows[-1][2]))
        for i, (sq, sid, t) in enumerate(seq_rows):
            batch.append((sid, t, cur_trip, ti[0], ti[1]))
            here = coord.get(sid)
            nxt = coord.get(seq_rows[i + 1][1]) if i + 1 < len(seq_rows) else None
            if here and nxt:
                b = bearing(here[0], here[1], nxt[0], nxt[1])
                rad = math.radians(b)
                sin_sum[sid] = sin_sum.get(sid, 0.0) + math.sin(rad)
                cos_sum[sid] = cos_sum.get(sid, 0.0) + math.cos(rad)
        ndep += len(seq_rows)

    cur, buf = None, []
    for r in rows(zf, "stop_times.txt"):
        tid = r.get("trip_id")
        if tid != cur:
            flush_trip(cur, buf)
            cur, buf = tid, []
            if len(batch) >= 5000:
                con.executemany("insert into dep values(?,?,?,?,?)", batch)
                batch.clear()
        if tid not in trip_info:
            continue
        t = secs(r.get("departure_time") or r.get("arrival_time"))
        if t is None or r["stop_id"] not in coord:
            continue
        try:
            sq = int(r.get("stop_sequence") or 0)
        except ValueError:
            sq = 0
        buf.append((sq, r["stop_id"], t))
    flush_trip(cur, buf)
    if batch:
        con.executemany("insert into dep values(?,?,?,?,?)", batch)
        batch.clear()
    log("%d departures today" % ndep)

    served = {r[0] for r in con.execute("select distinct stop_id from dep")}
    log("%d stops actually see a departure today" % len(served))
    # v21: stations are permanent. What the feed knows is merged into the
    # file and nothing is ever taken out of it; the schedule is rebuilt
    # around it. A stop with nothing leaving it today is still a station.
    perm = load_stations()
    if not perm:
        # the first rebuild after the update: keep what the old index knew
        try:
            old = sqlite3.connect(DB_PATH)
            for sid, nm, la, lo, br in old.execute(
                    "select stop_id, name, lat, lon, bearing from stops"):
                perm[str(sid)] = [nm, la, lo, br]
            old.close()
        except Exception:
            pass
    for sid, (la, lo) in coord.items():
        if sid in not_platform and sid not in served:
            continue                # a parent station is not somewhere you stand
        s_, c_ = sin_sum.get(sid), cos_sum.get(sid)
        brg = None
        if s_ is not None and (abs(s_) > 1e-9 or abs(c_) > 1e-9):
            brg = (math.degrees(math.atan2(s_, c_)) + 360.0) % 360.0
        prev = perm.get(sid)
        if brg is None and prev:
            brg = prev[3]          # keep the way it faced on the last day it could be told
        nm = name.get(sid, "") or (prev[0] if prev else "")
        perm[sid] = [nm, la, lo, brg]
    srows = [(sid, v[0], v[1], v[2], v[3]) for sid, v in perm.items()]
    try:
        save_stations(perm)
    except Exception as e:
        log("could not write stations.json: %r" % (e,))
    con.executemany("insert or replace into stops values(?,?,?,?,?)", srows)
    nstops = len(srows)
    log("%d stations kept for good, %d with a departure today" % (nstops, len(served)))

    con.execute("create table trips(trip_id text primary key, route text, head text,"
                " origin text, dest text, start_t int, end_t int)")
    con.executemany("insert or replace into trips values(?,?,?,?,?,?,?)", trips_meta)
    log("%d trips indexed" % len(trips_meta))
    con.execute("create index dep_stop_t on dep(stop_id, t)")
    con.execute("create index dep_trip on dep(trip_id, t)")
    con.execute("create index stops_ll on stops(lat, lon)")
    con.execute("create index trips_route on trips(route)")
    con.execute("insert or replace into meta values('service_date', ?)", (ymd,))
    con.execute("insert or replace into meta values('built', ?)", (str(int(time.time())),))
    con.execute("insert or replace into meta values('stops', ?)", (str(nstops),))
    con.execute("insert or replace into meta values('deps', ?)", (str(ndep),))
    con.commit()
    con.close()
    os.replace(tmp, DB_PATH)
    log("station index written to " + DB_PATH)


if __name__ == "__main__":
    main()
ALLC_UPDATE_PY
done_

step "installing the star interface"
cat > "$APPDIR/all.html" << 'ALLC_STAR_HTML'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>all.commute</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<style>
  :root{
    --bg:#0d1117; --card:#141a22; --border:#2a323d; --text:#e6edf3;
    --muted:#8b949e; --cyan:#39d0d8; --gold:#d4a017; --green:#3fb950; --red:#f85149;
  }
  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
  html,body{margin:0;height:100%;background:var(--bg);color:var(--text);
    font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
    overscroll-behavior:none;}
  #map,#gmap{position:absolute;inset:0;background:var(--bg);}
  #gmap{display:none;}
  body.gengine #map{display:none;} body.gengine #gmap{display:block;}

  /* ---- the status line. it never lies about what the app is doing ---- */
  #hud{position:absolute;top:calc(58px + env(safe-area-inset-top));left:14px;right:14px;
    z-index:600;font-size:.86rem;font-weight:600;line-height:1.35;color:#fff;
    pointer-events:none;text-shadow:0 0 5px #000,0 1px 2px #000,0 0 12px rgba(0,0,0,.85);}
  #hud b{color:var(--cyan);}
  #hud .spin{color:var(--cyan);animation:pulse .9s infinite;}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.25}}

  #tools{position:absolute;top:calc(10px + env(safe-area-inset-top));right:12px;z-index:601;
    display:flex;gap:8px;}
  .tool{width:42px;height:42px;border-radius:12px;background:rgba(13,17,23,.35);
    border:1px solid var(--border);color:var(--text);font-size:1.1rem;cursor:pointer;
    display:flex;align-items:center;justify-content:center;}
  .tool.on{border-color:var(--cyan);color:var(--cyan);}
  /* one or the other: our stars, or Google's own transit icons */
  .viewseg{display:flex;border:1px solid var(--border);border-radius:12px;overflow:hidden;
    background:rgba(13,17,23,.35);}
  .viewseg button{width:44px;height:42px;border:0;background:transparent;cursor:pointer;
    display:flex;align-items:center;justify-content:center;color:var(--muted);padding:0;}
  .viewseg button+button{border-left:1px solid var(--border);}
  .viewseg button.on{background:rgba(57,208,216,.16);color:var(--cyan);}
  .viewseg svg{width:21px;height:21px;display:block;}

  /* the live fix readout, always on screen under the status line */
  #gpsChip{position:absolute;left:14px;z-index:600;
    top:calc(104px + env(safe-area-inset-top));display:flex;align-items:center;gap:7px;
    padding:6px 10px;border-radius:999px;cursor:pointer;
    background:rgba(13,17,23,.62);border:1px solid var(--border);
    font:700 .72rem/1 system-ui,sans-serif;color:var(--text);}
  #gpsChip .gdot{width:8px;height:8px;border-radius:50%;background:var(--muted);flex:none;}
  #gpsChip.good .gdot{background:var(--green);box-shadow:0 0 7px var(--green);}
  #gpsChip.ok   .gdot{background:var(--cyan);box-shadow:0 0 7px var(--cyan);}
  #gpsChip.weak .gdot{background:var(--gold);box-shadow:0 0 7px var(--gold);}
  #gpsChip.live .gdot{animation:pulse .9s infinite;}
  #gpsChip b{font-weight:800;}
  #gpsChip span{color:var(--muted);font-weight:700;}
  .tool.locate.busy{border-color:var(--cyan);color:var(--cyan);}

  /* where you are: a ring, not a blob. Fixed pixel size so it stays the same
     next to Google's own station icons at every zoom, and hollow so the map
     underneath it stays readable. */
  .medot{position:relative;width:22px;height:22px;}
  .medot i{position:absolute;inset:0;border-radius:50%;border:2.5px solid #39d0d8;
    box-shadow:0 0 0 1.5px rgba(0,0,0,.65),0 0 9px rgba(57,208,216,.75),
      inset 0 0 0 1.5px rgba(0,0,0,.5);}
  .medot b{position:absolute;left:50%;top:50%;width:4px;height:4px;margin:-2px 0 0 -2px;
    border-radius:50%;background:#39d0d8;box-shadow:0 0 4px #000;}
  .medot.weak i{border-color:#d4a017;box-shadow:0 0 0 1.5px rgba(0,0,0,.65),
      0 0 9px rgba(212,160,23,.7),inset 0 0 0 1.5px rgba(0,0,0,.5);}
  .medot.weak b{background:#d4a017;}
  .medot.pin i{border-style:dashed;border-color:#fff;}
  .medot.pin b{background:#fff;}

  /* the ring that says: this one. Hollow, so Google's icon shows through it. */
  .selring{position:relative;width:46px;height:46px;pointer-events:none;}
  .selring i{position:absolute;inset:0;border-radius:50%;border:2px solid var(--c);
    opacity:.95;}
  .selring i.w1{animation:wave 1.8s ease-out infinite;}
  .selring i.w2{animation:wave 1.8s ease-out infinite .6s;}
  .selring i.w3{animation:wave 1.8s ease-out infinite 1.2s;}
  .selring i.core{border-width:2.5px;box-shadow:0 0 14px var(--c),inset 0 0 12px var(--c);
    opacity:.55;animation:none;}
  @keyframes wave{0%{transform:scale(.55);opacity:.85}100%{transform:scale(1.6);opacity:0}}

  /* v20: what the station window kept, now inside the station's dashboard */
  .popsec{padding:10px 13px 4px;font:800 .66rem/1 system-ui,sans-serif;letter-spacing:.09em;
    color:var(--muted);text-transform:uppercase;}
  .arow.gone{opacity:.5;}
  .arow.gone .tm b{color:var(--muted);}

  /* ---- the stars ---- */
  .starwrap{background:none;border:0;}
  /* The armed outline. White, because every other colour on this map means
     a line or a station, and this one has to mean "you touched this" and
     nothing else. */
  .pin.armed .pinid span{box-shadow:0 0 0 2px #fff,0 0 10px rgba(255,255,255,.55);}
  /* v20: the label is centred on the station and is itself the tap target,
     with a margin of extra reach around it for a thumb */
  .pin{position:absolute;left:50%;top:50%;
    transform:translate(calc(-50% + var(--dx,0px)),calc(-50% + var(--dy,0px)));
    cursor:pointer;touch-action:manipulation;}
  .pin::before{content:"";position:absolute;inset:-12px -10px;}
  .pinchip{position:absolute;left:37px;top:50%;transform:translateY(-50%);
    pointer-events:none;}
  .pinid{position:relative;display:block;pointer-events:auto;z-index:1;}
  .pinlead{position:absolute;left:50%;top:50%;height:2px;margin-top:-1px;opacity:.85;
    transform-origin:0 50%;pointer-events:none;z-index:0;}
  .pinlead::after{content:"";position:absolute;right:-4px;top:50%;width:8px;height:8px;
    margin-top:-4px;border-radius:50%;background:currentColor;
    box-shadow:0 0 0 1.5px rgba(0,0,0,.7);}
  .pinid span{display:inline-block;padding:7px 9px;border-radius:7px;
    font:800 .71rem/1 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
    color:var(--c,#fff);background:rgba(13,17,23,.72);
    border:1px solid var(--c,#30363d);white-space:nowrap;text-shadow:0 1px 2px #000;}
  .pinchip span{display:inline-block;font:700 .74rem/1 system-ui,sans-serif;color:#fff;
    padding:4px 7px;border-radius:7px;background:rgba(13,17,23,.72);
    border:1px solid var(--c,#30363d);white-space:nowrap;text-shadow:0 1px 2px #000;}
  .pinchip i{font-style:normal;color:var(--muted);font-weight:600;}
  .star{position:relative;width:34px;height:34px;display:flex;align-items:center;justify-content:center;}
  .star svg{width:30px;height:30px;filter:drop-shadow(0 1px 3px rgba(0,0,0,.95));}
  .star polygon{fill:var(--c);stroke:#0d1117;stroke-width:1.1;stroke-linejoin:round;}
  .star.on::after{content:"";position:absolute;inset:-4px;border-radius:50%;
    border:2.5px solid var(--c);}
  .star.on::before{content:"";position:absolute;inset:-4px;border-radius:50%;
    border:2.5px solid var(--c);animation:ring 1.9s ease-out infinite;}
  @keyframes ring{0%{transform:scale(.8);opacity:.9}100%{transform:scale(1.45);opacity:0}}
  .star.mini{width:26px;height:26px;} .star.mini svg{width:24px;height:24px;}
  .star.mini::before,.star.mini::after{display:none;}

  #watchbar{position:fixed;left:12px;right:12px;z-index:640;display:none;
    bottom:calc(22px + env(safe-area-inset-bottom));
    align-items:center;gap:10px;padding:10px 12px;border-radius:14px;
    background:rgba(20,26,34,.94);border:2px solid var(--c,var(--border));cursor:pointer;
    }
  body.watching #watchbar{display:flex;}
  #watchbar .wname{font-weight:800;font-size:.92rem;flex:1;min-width:0;
    overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  #watchbar .weta{display:flex;align-items:center;gap:7px;font-weight:800;color:var(--cyan);
    font-size:.92rem;white-space:nowrap;flex:none;}
  #watchbar .wx{width:30px;height:30px;border-radius:9px;border:1px solid var(--border);
    background:transparent;color:var(--muted);cursor:pointer;flex:none;}

  /* ---- the dashboard ---- */
  #dash{position:fixed;inset:0;z-index:800;background:var(--bg);
    transform:translateY(100%);transition:transform .22s ease;
    display:flex;flex-direction:column;}
  #dash.show{transform:translateY(0);}
  .dhead{display:flex;align-items:center;gap:10px;padding:14px 14px 10px;
    padding-top:calc(14px + env(safe-area-inset-top));border-bottom:1px solid var(--border);}
  .dhead{background:color-mix(in srgb,var(--c,#2a323d) 15%,var(--bg));
    border-bottom:2px solid var(--c,var(--border));}
  .dhead .pid{flex:none;padding:5px 8px;border-radius:8px;color:var(--c);
    border:1px solid var(--c);background:rgba(13,17,23,.5);
    font:800 .78rem/1 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;}
  .dhead .dtitle{flex:1;min-width:0;}
  .dhead b{font-size:1.05rem;letter-spacing:.02em;display:block;line-height:1.2;}
  .dhead .sub{color:var(--muted);font-size:.78rem;font-weight:600;}
  .dhead .close{margin-left:auto;width:38px;height:38px;border-radius:11px;
    border:1px solid var(--border);background:transparent;color:var(--text);
    font-size:1.05rem;cursor:pointer;}
  .dbody{flex:1;overflow-y:auto;padding:12px 12px calc(28px + env(safe-area-inset-bottom));
    -webkit-overflow-scrolling:touch;}

  .card{border:2px solid var(--c);border-radius:16px;margin-bottom:14px;overflow:hidden;
    background:var(--card);}
  .card.on{box-shadow:0 0 0 3px color-mix(in srgb,var(--c) 30%,transparent);}
  .chead{display:flex;align-items:center;gap:9px;padding:10px 12px;
    background:color-mix(in srgb,var(--c) 14%,transparent);}
  .chead .nm{font-weight:800;font-size:.98rem;line-height:1.2;flex:1;min-width:0;}
  .chead .nm i{display:block;font-style:normal;font-weight:600;font-size:.74rem;color:var(--muted);
    margin-top:2px;}
  .wbtn{flex:none;border:1.5px solid var(--c);background:transparent;color:var(--c);
    border-radius:999px;padding:7px 13px;font:800 .74rem/1 system-ui,sans-serif;cursor:pointer;
    letter-spacing:.04em;}
  .wbtn.on{background:var(--c);color:#0d1117;}
  .svwrap{position:relative;display:block;cursor:pointer;}
  .sv{display:block;width:100%;height:132px;object-fit:cover;background:#0a0e14;
    border-top:1px solid color-mix(in srgb,var(--c) 30%,transparent);
    border-bottom:1px solid color-mix(in srgb,var(--c) 30%,transparent);}
  .sv360{position:absolute;right:10px;bottom:10px;display:flex;align-items:center;gap:5px;
    padding:6px 11px;border-radius:999px;background:rgba(13,17,23,.82);
    border:1px solid rgba(255,255,255,.28);color:#fff;
    font:800 .72rem/1 system-ui,sans-serif;letter-spacing:.06em;}
  /* ---- station location pin centred on the Street View photo ---- */
  .svpin{position:absolute;top:50%;left:50%;transform:translate(-50%,-100%);
    pointer-events:none;filter:drop-shadow(0 2px 8px rgba(0,0,0,.75));
    display:flex;flex-direction:column;align-items:center;}
  .svpinlabel{background:rgba(13,17,23,.82);color:var(--c);border:1.5px solid var(--c);
    border-radius:7px;padding:2px 7px;font:800 .7rem/1.5 system-ui,sans-serif;
    letter-spacing:.04em;white-space:nowrap;margin-bottom:5px;
    }
  .svpin::before{content:"";display:block;width:28px;height:28px;border-radius:50%;
    background:var(--c);border:3px solid #fff;
    box-shadow:0 0 0 0 color-mix(in srgb,var(--c) 60%,transparent);
    animation:svpinpulse 2.2s ease-out infinite;}
  .svpin::after{content:"";display:block;width:0;height:0;
    border-left:10px solid transparent;border-right:10px solid transparent;
    border-top:13px solid var(--c);margin:0 auto;}
  @keyframes svpinpulse{
    0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--c) 60%,transparent);}
    60%{box-shadow:0 0 0 10px rgba(0,0,0,0);}
    100%{box-shadow:0 0 0 0 rgba(0,0,0,0);}}
  .svnone{padding:9px 12px;color:var(--muted);font-size:.74rem;font-weight:600;
    border-top:1px solid var(--border);border-bottom:1px solid var(--border);}
  .arr{padding:4px 0;}
  .arow{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;
    padding:9px 12px;border-bottom:1px solid rgba(255,255,255,.045);}
  .arow:last-child{border-bottom:0;}
  .rt{display:inline-flex;align-items:center;justify-content:center;min-width:34px;height:28px;
    padding:0 7px;border-radius:8px;background:var(--r);color:#0d1117;
    font:800 .92rem/1 system-ui,sans-serif;border:1.5px solid var(--r);}
  .rt.sched{background:transparent;color:var(--r);}
  .rt.sm{min-width:26px;height:22px;font-size:.78rem;border-radius:6px;}
  .od{min-width:0;font-size:.82rem;font-weight:700;line-height:1.25;}
  .od i{display:block;font-style:normal;font-weight:600;font-size:.72rem;color:var(--muted);
    margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .od .from{color:var(--muted);font-weight:600;}
  .tm{text-align:right;white-space:nowrap;}
  .tm b{display:block;font-size:1.02rem;font-weight:800;}
  .tm b.soon{color:var(--green);} .tm b.now{color:var(--gold);}
  .tm small{display:block;color:var(--muted);font-size:.7rem;font-weight:700;margin-top:1px;}
  .wifi{vertical-align:-1px;margin-left:3px;}
  .ptag{display:inline-block;margin-left:5px;padding:1px 5px;border-radius:4px;
    border:1px solid var(--border);color:var(--muted);font-size:.62rem;font-weight:800;
    letter-spacing:.05em;vertical-align:1px;}
  .arow.printed .rt{border-style:dashed;}
  .warnbox{margin:0 0 12px;padding:9px 11px;border-radius:10px;
    border:1px solid rgba(212,160,23,.45);background:rgba(212,160,23,.09);
    color:var(--gold);font-size:.76rem;font-weight:700;line-height:1.4;}
  .srow{display:flex;align-items:center;gap:9px;padding:8px 2px;
    border-bottom:1px solid rgba(255,255,255,.05);}
  .srow:last-child{border-bottom:0;}
  .srow .sr{flex:none;min-width:32px;height:24px;padding:0 7px;border-radius:7px;
    display:inline-flex;align-items:center;justify-content:center;
    background:var(--r);color:#0d1117;font:800 .78rem/1 system-ui,sans-serif;}
  .srow .sn{flex:1;min-width:0;font-size:.78rem;font-weight:700;}
  .srow .sn i{display:block;font-style:normal;font-weight:600;font-size:.7rem;
    color:var(--muted);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .srow .sn i.bad{color:var(--gold);}
  .srow .sx{flex:none;width:28px;height:28px;border-radius:8px;border:1px solid var(--border);
    background:transparent;color:var(--muted);cursor:pointer;font-size:.8rem;}
  .btnrow{display:flex;gap:8px;flex-wrap:wrap;}
  .msg.good{color:var(--green);} .msg.bad{color:var(--red);}
  .msg.busy{color:var(--cyan);}
  select.pick{width:100%;margin-top:10px;padding:11px 12px;border-radius:10px;
    background:#1d242e;color:var(--text);border:1px solid var(--border);
    font:700 .82rem/1 system-ui,sans-serif;-webkit-appearance:none;appearance:none;}
  select.pick:disabled{opacity:.5;}
  .picklbl{display:block;margin-top:11px;font-size:.74rem;font-weight:700;
    color:var(--muted);letter-spacing:.02em;}
  .d.late{color:var(--red);font-weight:800;} .d.ok{color:var(--green);font-weight:800;}
  .empty{padding:16px 12px;color:var(--muted);font-size:.82rem;font-weight:600;text-align:center;}

  /* ---- the 360 viewer ---- */
  #pano{position:fixed;inset:0;z-index:950;background:#000;display:none;}
  #pano.show{display:block;}
  #panoView{position:absolute;inset:0;}
  .panomsg{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
    color:var(--muted);font-size:.86rem;font-weight:600;text-align:center;padding:24px;}
  .panobar{position:absolute;left:0;right:0;top:0;z-index:5;display:flex;align-items:center;
    gap:10px;padding:12px 14px;padding-top:calc(12px + env(safe-area-inset-top));
    background:linear-gradient(180deg,rgba(0,0,0,.78),transparent);pointer-events:none;}
  .panobar b{font-size:.95rem;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;
    white-space:nowrap;text-shadow:0 1px 3px #000;}
  .panobar button{pointer-events:auto;flex:none;height:38px;padding:0 13px;border-radius:11px;
    border:1px solid rgba(255,255,255,.3);background:rgba(13,17,23,.65);color:#fff;
    font:700 .78rem/1 system-ui,sans-serif;cursor:pointer;}
  .panobar button.on{border-color:var(--cyan);color:var(--cyan);}
  .panohint{position:absolute;left:0;right:0;bottom:calc(22px + env(safe-area-inset-bottom));
    text-align:center;color:rgba(255,255,255,.66);font:600 .76rem/1 system-ui,sans-serif;
    text-shadow:0 1px 3px #000;pointer-events:none;transition:opacity .5s;}

  /* ---- settings ---- */
  #setup{position:fixed;inset:0;z-index:900;background:var(--bg);display:none;
    overflow-y:auto;padding:0 14px calc(30px + env(safe-area-inset-bottom));}
  #setup.show{display:block;}
  #map .leaflet-tile-pane { filter:invert(1) hue-rotate(180deg) brightness(.95) contrast(.9) saturate(.7); }
  .keytop { border-color:var(--gold, var(--accent, #d4a017)) !important; }
  .keyguide { margin-top:10px; font-size:.86rem; line-height:1.45; }
  .keyguide summary { cursor:pointer; font-weight:700; padding:6px 0; }
  .keyguide ol { margin:6px 0 6px 18px; padding:0; }
  .keyguide li { margin:4px 0; }
  .keyguide a { color:inherit; font-weight:700; }
  .ipline { font-size:.74rem; color:var(--cyan); background:var(--card); border:1px solid var(--border);
    border-radius:9px; padding:7px 10px; margin:0 0 10px; font-variant-numeric:tabular-nums; word-break:break-all; }
  .sh{display:flex;align-items:center;gap:10px;padding:16px 0 12px;
    padding-top:calc(16px + env(safe-area-inset-top));position:sticky;top:0;background:var(--bg);
    border-bottom:1px solid var(--border);margin-bottom:14px;z-index:2;}
  .sh b{font-size:1.05rem;} .sh .close{margin-left:auto;}
  .box{background:var(--card);border:1px solid var(--border);border-radius:14px;
    padding:14px;margin-bottom:14px;}
  .box h3{margin:0 0 9px;font-size:.9rem;letter-spacing:.02em;}
  .note{display:block;color:var(--muted);font-size:.76rem;line-height:1.45;margin-top:9px;}
  .btn{display:inline-block;border:1px solid var(--border);background:#1d242e;color:var(--text);
    border-radius:10px;padding:10px 14px;font:700 .82rem/1 system-ui,sans-serif;cursor:pointer;}
  .btn.ghost{background:transparent;}
  .keyfile{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none;}
  .msg{margin-top:9px;font-size:.78rem;color:var(--cyan);font-weight:600;min-height:1em;}
  .dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--red);
    vertical-align:middle;margin-left:5px;}
  .dot.ok{background:var(--green);}
  .kv{display:flex;justify-content:space-between;gap:12px;font-size:.8rem;padding:3px 0;}
  .kv span{color:var(--muted);font-weight:600;} .kv b{font-weight:700;}

  /* the layer stack, heaviest at the top */
  .eng{display:flex;gap:8px;margin-bottom:4px;}
  .eng button{flex:1;border:1px solid var(--border);background:transparent;color:var(--muted);
    border-radius:10px;padding:9px 6px;font:700 .78rem/1.3 system-ui,sans-serif;cursor:pointer;}
  .eng button i{display:block;font-style:normal;font-weight:600;font-size:.68rem;
    margin-top:3px;opacity:.75;}
  .eng button.on{border-color:var(--cyan);color:var(--cyan);background:rgba(57,208,216,.08);}
  .lrow{display:flex;align-items:center;gap:11px;padding:10px 2px;
    border-bottom:1px solid rgba(255,255,255,.05);cursor:pointer;}
  .lrow:last-child{border-bottom:0;}
  .lnum{flex:none;width:21px;height:21px;border-radius:6px;background:#1d242e;
    color:var(--muted);font:800 .7rem/21px system-ui,sans-serif;text-align:center;}
  .lname{flex:1;min-width:0;font-size:.84rem;font-weight:700;line-height:1.2;}
  .lname i{display:block;font-style:normal;font-weight:600;font-size:.72rem;
    color:var(--muted);margin-top:2px;}
  .lsw{flex:none;width:42px;height:24px;border-radius:999px;background:#1d242e;
    border:1px solid var(--border);position:relative;transition:background .15s;}
  .lsw::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;
    border-radius:50%;background:var(--muted);transition:transform .15s,background .15s;}
  .lsw.on{background:rgba(57,208,216,.22);border-color:var(--cyan);}
  .lsw.on::after{transform:translateX(18px);background:var(--cyan);}
  .llock{flex:none;font:700 .68rem/1 system-ui,sans-serif;color:var(--muted);
    border:1px solid var(--border);border-radius:999px;padding:6px 9px;}
  .lrow.off{opacity:.42;} .lrow.off .lsw{opacity:.5;}
  .lrow.heavy .lnum{background:rgba(212,160,23,.2);color:var(--gold);}

  body.panoopen .leaflet-control-attribution{display:none;}
  .leaflet-control-attribution{font-size:9px;background:rgba(13,17,23,.55);color:#6e7681;}
  .leaflet-control-attribution a{color:#8b949e;}
</style>
</head>
<body>
  <div id="map"></div>
  <div id="gmap"></div>
  <div id="hud">Finding you…</div>
  <div id="tools">
    <div class="viewseg">
      <button id="viewStars" title="Star view">
        <svg viewBox="0 0 24 24"><polygon id="segStar" points=""/></svg></button>
      <button id="viewGoogle" title="Google station view">
        <svg viewBox="0 0 24 24">
          <rect x="3" y="3" width="18" height="18" rx="5" fill="currentColor" opacity=".22"/>
          <rect x="8" y="6.4" width="8" height="8.2" rx="2.4" fill="none"
                stroke="currentColor" stroke-width="1.7"/>
          <path d="M8.6 11.4h6.8" stroke="currentColor" stroke-width="1.5"/>
          <path d="M9.6 14.8 8.4 17.2M14.4 14.8l1.2 2.4" stroke="currentColor"
                stroke-width="1.5" stroke-linecap="round"/>
        </svg></button>
    </div>
    <button class="tool locate" id="btnLocate" title="Show my location">
      <svg viewBox="0 0 24 24" width="20" height="20" fill="none"
           stroke="currentColor" stroke-width="1.9">
        <circle cx="12" cy="12" r="4.2"/><circle cx="12" cy="12" r="8" opacity=".45"/>
        <path d="M12 1.6v3M12 19.4v3M1.6 12h3M19.4 12h3" stroke-linecap="round"/>
      </svg></button>
    <button class="tool" id="btnLabels" title="Street names">A</button>
    <button class="tool" id="btnSetup" title="Settings">⚙</button>
  </div>

  <div id="gpsChip" title="Tap for the whole picture">
    <span class="gdot"></span><b id="gpsAcc">—</b><span id="gpsSrc">looking…</span>
  </div>

  <div id="watchbar">
    <span class="star mini" id="wbStar"></span>
    <span class="wname" id="wbName">—</span>
    <span class="weta" id="wbEta">—</span>
    <button class="wx" id="wbX" title="Stop watching">✕</button>
  </div>
  <div id="dash">
    <div class="dhead">
      <span class="pid" id="dId">—</span>
      <div class="dtitle"><b id="dName">—</b><div class="sub" id="dSub">—</div></div>
      <button class="close" id="dClose" title="Back to the map">✕</button>
    </div>
    <div class="dbody" id="dBody"></div>
  </div>

  <div id="pano">
    <div id="panoView"></div>
    <div class="panobar">
      <b id="panoName">—</b>
      <button id="panoMotion" title="Move the phone to look around">gyro</button>
      <button id="panoClose">✕</button>
    </div>
    <div class="panohint" id="panoHint">drag to look around</div>
  </div>

  <div id="setup">
    <div class="sh"><b>all.commute</b><button class="btn ghost close" id="sClose">Done</button></div>
    <div class="ipline" id="ipLine">on this phone only</div>
    <div class="box keytop">
      <h3>Map key <span class="dot" id="keyDot"></span></h3>
      <input type="file" id="keyFile" accept=".txt,text/plain" class="keyfile">
      <div class="btnrow">
        <label for="keyFile" class="btn">Choose the key file</label>
        <button class="btn ghost" id="keyTest">Test key</button>
      </div>
      <div class="msg" id="keyMsg"></div>
      <div class="keyguide">
        <p>The map is OpenStreetMap: free, and it works without a key. A Google key adds three things: the detailed map, the station photograph and the 360&deg; view. Kept on the phone in ~/.all.commute/google-api.txt and never shown.</p>
        <details><summary>How to get a Google Maps key</summary>
        <ol>
          <li>Open <a href="https://console.cloud.google.com/" target="_blank" rel="noopener">console.cloud.google.com</a> and sign in with a Google account.</li>
          <li>Create a project: the project menu at the top, then New project.</li>
          <li>Add billing. Google asks for a card before its maps work. The use of one person normally stays inside Google's free monthly allowance.</li>
          <li>APIs and Services, then Library: switch on <b>Maps JavaScript API</b> and <b>Street View Static API</b>.</li>
          <li>APIs and Services, then Credentials: Create credentials, API key. Copy the key.</li>
          <li>Restrict the key to those APIs, so it is useless for anything else if it ever leaks.</li>
          <li>Put the key alone in a text file named <b>google-api.txt</b>, then pick that file with the button above.</li>
        </ol>
        <a href="https://developers.google.com/maps/documentation/javascript/get-api-key" target="_blank" rel="noopener">Google's own guide</a>
        </details>
      </div>
    </div>


    <div class="box">
      <h3>Map layers</h3>
      <div class="eng">
        <button id="engFree">Free map<i>roads and names</i></button>
        <button id="engDetail">Detailed map<i>every layer, needs key</i></button>
      </div>
      <div id="layerBox"></div>
      <span class="note" id="layerNote"></span>
    </div>

    <div class="box">
      <h3>Position <span class="dot" id="posDot"></span></h3>
      <div id="posBox"><span class="note">Waiting for a fix…</span></div>
      <div class="btnrow" style="margin-top:11px">
        <button class="btn" id="posSharpen">Sharpen — hold still</button>
        <button class="btn ghost" id="posPin">Pin by tapping the map</button>
        <button class="btn ghost" id="posProv">Ask Android now</button>
      </div>
      <div class="msg" id="posMsg"></div>
      <span class="note">A phone gives its first answer from cell towers and
        wifi, then tightens as the satellites lock. This listens for 30 seconds
        and weights each fix by how sure it claims to be, which cancels the
        random half of the error. It cannot cancel the other half: signal
        bouncing off the buildings along a street like Ilica arrives late and
        pushes the fix sideways, confidently. That is why the ring is drawn —
        it is the phone's own estimate, and standing where two streets open up
        will do more than any setting here.</span>
    </div>

    <div class="box">
      <h3>Printed timetables <span class="dot" id="schedDot"></span></h3>
      <div id="schedWarn"></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn" id="schedNear">Store the lines around me</button>
        <button class="btn ghost" id="schedAll">Delete all</button>
      </div>
      <div class="msg" id="schedMsg"></div>
      <div id="schedList" style="margin-top:8px"></div>
      <span class="note">ZET publishes the official vozni red of every line as a
        PDF. This reads one per line, keeps the times, and throws the PDF away in
        the same breath — nothing but a small file of times stays on the phone,
        and it works with no signal at all. When the GTFS feed breaks or the
        index is a day behind, these fill the holes in the board.</span>
    </div>

    <div class="box">
      <h3>Gemini key <span class="dot" id="gemDot"></span></h3>
      <input type="file" id="gemFile" accept=".txt,text/plain" class="keyfile">
      <div class="btnrow">
        <label for="gemFile" class="btn">Load key from file</label>
        <button class="btn ghost" id="gemTest">Test key</button>
        <button class="btn ghost" id="gemRefresh">Check available models</button>
      </div>
      <div class="msg" id="gemMsg"></div>
      <span class="picklbl">Model for reading timetable PDFs</span>
      <select class="pick" id="gemPick"><option value="">Automatic</option></select>
      <div class="msg" id="gemPickMsg"></div>
      <span class="note">Needed to read the timetable PDFs. The printed grids are
        an hour column with loose minutes beside it, in two directions and three
        day columns — without a key all this can do is scrape stray times it
        cannot place, and those are never allowed near the board. One call per
        line, once, then never again.</span>
    </div>

    <div class="box">
      <h3>Station cache</h3>
      <div id="statBox"><span class="note">Loading…</span></div>
      <div style="margin-top:11px"><button class="btn" id="cacheBtn">Cache all stations</button></div>
      <div class="msg" id="cacheMsg"></div>
      <span class="note">Every stop in the ZET network, kept on the phone. Built once a day.</span>
    </div>

    <div class="box">
      <h3>Search radius</h3>
      <div style="display:flex;gap:8px;align-items:center">
        <button class="btn" id="rMinus">−</button>
        <b id="rLbl" style="min-width:78px;text-align:center">150 m</b>
        <button class="btn" id="rPlus">+</button>
      </div>
      <span class="note">How far around you the map looks for stations. 150 m is walking
        distance to the platform. If nothing is that close, the app reaches further
        on its own and says so.</span>
    </div>

    <div class="box">
      <h3>About</h3>
      <div class="kv"><span>Interface</span><b>stations · v45</b></div>
      <div class="kv"><span>Engine</span><b id="verLine">…</b></div>
    </div>
  </div>

<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
/* ---- MAHA COMMUTE, reset on a new run ---------------------------------
   Runs before anything below reads localStorage, which is the only reason
   it sits at the top of this block rather than at the end of the file. */
(function () {
  try {
    var run  = new URLSearchParams(location.search).get("run") || "";
    var nav  = (performance.getEntriesByType("navigation")[0] || {}).type || "";
    var prev = localStorage.getItem("maha_run") || "";
    // With a run id, a new run is a different id. Without one, a fresh
    // navigation is a new run and a reload is not, so refreshing the page
    // in the middle of a journey does not throw the pick away.
    var fresh = run ? (run !== prev) : (nav !== "reload" && nav !== "back_forward");
    if (fresh) {
      ["ac2_watch", "ac2_view"].forEach(function (k) { try { localStorage.removeItem(k); } catch (e) {} });
    }
    if (run) localStorage.setItem("maha_run", run);
  } catch (e) { /* a page that cannot reset is still a page that works */ }
})();

/* =========================================================================
   all.commute — star interface
   Open it, it finds you, it puts a coloured star on every tram and bus stop
   you can walk to. Every line carries its own colour, the same colour on
   every board. The dashboard shows what is coming to each station, framed in
   that station's colour, with the stop itself in Street View — tap the photo
   and you can turn all the way round.
   ========================================================================= */

/* ---------------- small helpers ---------------- */
function esc(x){
  return String(x == null ? "" : x).replace(/[&<>"']/g, c =>
    ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
}
function fmtDist(m){
  if (m == null) return "";
  return m < 1000 ? m + " m" : (m / 1000).toFixed(m < 10000 ? 1 : 0) + " km";
}
function metres(aLat, aLon, bLat, bLon){
  const R = 6371000, p = Math.PI / 180;
  const dla = (bLat - aLat) * p, dlo = (bLon - aLon) * p;
  const h = Math.sin(dla / 2) ** 2 +
    Math.cos(aLat * p) * Math.cos(bLat * p) * Math.sin(dlo / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(h)));
}
function dirAbbr(b){
  if (b == null) return null;
  return ["N","NE","E","SE","S","SW","W","NW"][Math.round((((b % 360) + 360) % 360) / 45) % 8];
}
const BRAILLE = ["\u280b","\u2819","\u2839","\u2838","\u283c","\u2834","\u2826","\u2827","\u2807","\u280f"];
let _spinT = null, _spinI = 0;
function hud(html, busy){
  // Same signature it always had, so every existing caller keeps working.
  // What changed is that busy now turns, instead of showing a dot that
  // looks identical whether the app is working or has died.
  const el = document.getElementById("hud");
  if (!el) return;
  if (_spinT) { clearInterval(_spinT); _spinT = null; }
  if (!busy) { el.innerHTML = html; return; }
  const paint = () => {
    el.innerHTML = '<span class="spin">' + BRAILLE[_spinI % BRAILLE.length] +
                   '</span> ' + html;
    _spinI++;
  };
  paint();
  _spinT = setInterval(paint, 90);
}
const WIFI = '<svg class="wifi" width="13" height="10" viewBox="0 0 16 12">' +
  '<circle cx="8" cy="10" r="1.2" fill="#3fb950"/>' +
  '<path d="M4.8 7.2a4.5 4.5 0 0 1 6.4 0" fill="none" stroke="#3fb950" stroke-width="1.6" stroke-linecap="round"/>' +
  '<path d="M2.6 4.8a7.6 7.6 0 0 1 10.8 0" fill="none" stroke="#3fb950" stroke-width="1.6" stroke-linecap="round"/></svg>';

const STAR_PTS = (() => {
  const p = [];
  for (let i = 0; i < 10; i++) {
    const a = (-90 + i * 36) * Math.PI / 180;
    const r = i % 2 ? 4.6 : 11;
    p.push((12 + r * Math.cos(a)).toFixed(2) + "," + (12 + r * Math.sin(a)).toFixed(2));
  }
  return p.join(" ");
})();
function starHTML(colour, on, mini){
  return '<div class="star' + (on ? " on" : "") + (mini ? " mini" : "") +
    '" style="--c:' + colour + '">' +
    '<svg viewBox="0 0 24 24"><polygon points="' + STAR_PTS + '"/></svg></div>';
}

/* eight hues that stay apart on a dark map, and none of them is the green or
   the red we use for early and late */
const PALETTE = ["#d4a017", "#39d0d8", "#c77dff", "#ff9f1c",
                 "#5ee1a0", "#ff6b9d", "#60a5fa", "#f4e04d"];

/* ---------------- one colour per line, forever ----------------
   Line 6 is the same colour on every board, every day, on every stop. The
   colour is worked out from the number itself, so nothing has to be stored
   and nothing drifts between sessions. The hue walks the wheel in golden-angle
   steps, because the lines you see together are nearly always numerically
   close, and consecutive numbers land opposite each other. Brightness and
   saturation come from a separate hash so two distant numbers that happen to
   share a hue still pull apart. */
const TINT = {};
function routeColour(route){
  const k = String(route == null ? "" : route).trim().toUpperCase();
  if (TINT[k]) return TINT[k];
  let n = parseInt(k, 10);
  if (!isFinite(n) || String(n) !== k.replace(/^0+/, "")) {
    n = 0;
    for (let i = 0; i < k.length; i++) n = (n * 33 + k.charCodeAt(i)) >>> 0;
  }
  const h = (n * 137.508) % 360;
  const mix = Math.imul(n + 1, 2654435761) >>> 0;
  let l = 62 + (((mix >>> 3) % 4) - 1.5) * 11;
  const s = 62 + ((mix >>> 11) % 2) * 20;
  if (h > 195 && h < 285) l += 7;
  else if (h > 40 && h < 80) l -= 6;
  l = Math.max(45, Math.min(82, l));
  TINT[k] = "hsl(" + h.toFixed(1) + " " + s + "% " + l.toFixed(0) + "%)";
  return TINT[k];
}

/* ---------------- state ---------------- */
const LS = {
  get(k, d){ try { const v = localStorage.getItem("ac2_" + k); return v == null ? d : JSON.parse(v); }
             catch (e) { return d; } },
  set(k, v){ try { localStorage.setItem("ac2_" + k, JSON.stringify(v)); } catch (e) {} },
  del(k){ try { localStorage.removeItem("ac2_" + k); } catch (e) {} },
};

/* The layer stack, heaviest first. Row one is the map itself and cannot be
   turned off. Everything below it is optional, and the further down you go the
   less it has to do with catching a tram. */
const LAYER_DEFS = [
  { id:"base",      name:"Roads & water",         note:"the map itself",              lock:true },
  { id:"streets",   name:"Street names",          note:"Ilica, Savska, Vukovarska" },
  { id:"places",    name:"District & place names", note:"Trešnjevka, Črnomerec",      google:true },
  { id:"parks",     name:"Parks & green space",   note:"Maksimir, Bundek, Sava banks", google:true },
  { id:"buildings", name:"Buildings",             note:"footprints once you zoom in",  google:true },
  { id:"transit",   name:"Transit lines",         note:"tram and rail drawn on the map", google:true },
  { id:"shops",     name:"Shops, cafés & food",   note:"McDonald's and everything like it", google:true },
];
let LAYERS = Object.assign(
  { base:true, streets:true, places:false, parks:false, buildings:false, transit:false, shops:false },
  LS.get("layers", {}));
let ENGINE = LS.get("engine", "free");     // "free" (Leaflet) or "detail" (Google)
/* "stars"  — our own coloured stars, either basemap
   "google" — Google's own transit icons are the thing you tap. We draw nothing
              but the ring around whichever one you picked. */
let MODE = LS.get("mode", "stars");

let API_KEY = "";
let map = null, tiles = null, names = null;      // free engine
let gmap = null, HtmlMarker = null;              // detailed engine
let gPins = [], gMe = null, gRing = null;
let ME = null, meMk = null, meRing = null;
let CENTRED = false;          // true once the map has really been moved to you
// The map moves to you ONLY when you press the locate button (WANT_CENTRE), or
// once on the very first run, before there is any view of yours to keep. The
// dot moves by itself; the map never follows it and never changes zoom.
let WANT_CENTRE = false, HAD_VIEW = !!LS.get("view", null);
let STOPSEQ = 0;              // the newest stations request; an older answer is dropped

let STOPS = [];                       // the stations around you, nearest first
let COLOUR = {};                      // stop_id -> colour, kept steady as you walk
let MARKS = {};                       // stop_id -> leaflet marker
let BOARDS = {};                      // stop_id -> board payload
let WATCH = LS.get("watch", null);    // the station you said you are waiting at
let RADIUS = LS.get("radius", 150);
let INDEX_OK = false;
let lastFix = 0, lastStopFetch = null, boardTimer = null, indexTimer = null;
const RSTEPS = [100, 150, 200, 300, 400, 600, 900];
const SV_CACHE = {};                  // stop_id -> street view url, or null

/* =========================================================================
   THE FREE ENGINE — Leaflet on CARTO raster tiles
   The base carries roads, water and parks and no writing at all. The names
   ride on a transparent layer above it, in their own pane so they sit over the
   radius ring but under the stars. Raster tiles cannot separate street names
   from district names, and carry no shops at all — that is what the detailed
   engine is for.
   ========================================================================= */
// v18: OpenStreetMap's own tiles. CARTO began answering every tile with one
// picture saying API KEY REQUIRED. OpenStreetMap tiles carry their own labels,
// so the separate names layer is an empty group and nothing else has to change.
const TILE_BASE  = "https://tile.openstreetmap.org/{z}/{x}/{y}.png";

function initFreeMap(){
  const v = LS.get("view", { lat: 45.8131, lng: 15.9775, zoom: 17 });
  map = L.map("map", { zoomControl: false, attributionControl: true,
    clickTolerance: 10, tapTolerance: 22 })
    .setView([v.lat, v.lng], v.zoom);
  tiles = L.tileLayer(TILE_BASE,
    { maxZoom: 19, attribution: "© OpenStreetMap contributors" }).addTo(map);
  map.createPane("names");
  map.getPane("names").style.zIndex = 450;
  map.getPane("names").style.pointerEvents = "none";
  names = L.layerGroup();
  map.on("moveend", saveView);
  map.on("zoomend", layoutPins);
  map.on("click", (e) => { if (PINMODE) pinAt(e.latlng.lat, e.latlng.lng); });
}

/* =========================================================================
   THE DETAILED ENGINE — Google Maps JavaScript API
   The only thing that can actually take the map apart feature by feature. It
   is also what the 360° view runs on, so once a key is in, both arrive
   together. Loaded lazily: nothing is fetched from Google until you ask.
   ========================================================================= */
let gPromise = null;
function loadGoogle(){
  if (gPromise) return gPromise;
  if (!API_KEY) return Promise.reject(new Error("no Google key loaded"));
  gPromise = new Promise((resolve, reject) => {
    const cb = "__gmapcb" + Math.random().toString(36).slice(2);
    let settled = false;
    window.gm_authFailure = () => {
      if (settled) return; settled = true; gPromise = null;
      reject(new Error("the key was refused, check Maps JavaScript API"));
    };
    window[cb] = () => { if (settled) return; settled = true; resolve(window.google); };
    const s = document.createElement("script");
    s.async = true;
    s.src = "https://maps.googleapis.com/maps/api/js?v=weekly&loading=async&key=" +
      encodeURIComponent(API_KEY) + "&callback=" + cb;
    s.onerror = () => {
      if (settled) return; settled = true; gPromise = null;
      reject(new Error("could not reach Google"));
    };
    document.head.appendChild(s);
    setTimeout(() => {
      if (settled) return; settled = true; gPromise = null;
      reject(new Error("timed out"));
    }, 15000);
  });
  return gPromise;
}

/* Later rules win, so everything optional is switched off first and only the
   layers you asked for are switched back on. */
function gStyles(){
  const on = [{ visibility: "on" }], off = [{ visibility: "off" }];
  const s = [
    { elementType:"geometry", stylers:[{ color:"#161b23" }] },
    { elementType:"labels.text.fill", stylers:[{ color:"#98a3b0" }] },
    { elementType:"labels.text.stroke", stylers:[{ color:"#0d1117" }, { weight:3 }] },
    { elementType:"labels.icon", stylers:off },
    { featureType:"landscape", elementType:"geometry", stylers:[{ color:"#161b23" }] },
    { featureType:"water", elementType:"geometry", stylers:[{ color:"#0a141d" }] },
    { featureType:"road", elementType:"geometry", stylers:[{ color:"#2b333f" }] },
    { featureType:"road.arterial", elementType:"geometry", stylers:[{ color:"#333c4a" }] },
    { featureType:"road.highway", elementType:"geometry", stylers:[{ color:"#414c5c" }] },
    { featureType:"road", elementType:"labels", stylers:off },
    { featureType:"administrative", elementType:"labels", stylers:off },
    { featureType:"poi", stylers:off },
    { featureType:"transit", stylers:off },
  ];
  if (LAYERS.streets) s.push({ featureType:"road", elementType:"labels.text", stylers:on });
  if (LAYERS.places)  s.push({ featureType:"administrative", elementType:"labels.text", stylers:on });
  if (LAYERS.parks)   s.push(
    { featureType:"poi.park", stylers:on },
    { featureType:"poi.park", elementType:"geometry", stylers:[{ color:"#16261c" }] },
    { featureType:"poi.park", elementType:"labels.text.fill", stylers:[{ color:"#6f9a7c" }] });
  if (LAYERS.buildings) s.push(
    { featureType:"landscape.man_made", elementType:"geometry.fill", stylers:[{ color:"#1d232d" }] },
    { featureType:"landscape.man_made", elementType:"geometry.stroke", stylers:[{ color:"#2c3542" }] });
  if (LAYERS.transit) s.push(
    { featureType:"transit", stylers:on },
    { featureType:"transit.line", elementType:"geometry", stylers:[{ color:"#3f4d5f" }] },
    { featureType:"transit", elementType:"labels.icon", stylers:on });
  if (MODE === "google") s.push(
    /* the icons are the interface here, so they come back on no matter what
       the layer stack says */
    { featureType:"transit.station", stylers:on },
    { featureType:"transit.station", elementType:"labels.icon", stylers:on },
    { featureType:"transit.station", elementType:"labels.text", stylers:on });
  if (LAYERS.shops) s.push(
    { featureType:"poi.business", stylers:on },
    { featureType:"poi.business", elementType:"labels.icon", stylers:on },
    { featureType:"poi.business", elementType:"labels.text.fill", stylers:[{ color:"#8b949e" }] });
  return s;
}

/* one HTML element pinned to one coordinate, so the stars look identical on
   both engines instead of being redrawn as flat images for Google */
function makeMarkerClass(g){
  if (HtmlMarker) return HtmlMarker;
  HtmlMarker = class extends g.maps.OverlayView {
    constructor(pos, html, onClick, z){ super(); this.p = pos; this.h = html; this.c = onClick; this.z = z || 0; }
    onAdd(){
      this.div = document.createElement("div");
      /* fixed to the star's own box: the name chip is absolutely positioned
         inside it, so it cannot widen this and shift the star off-centre */
      this.div.style.cssText = "position:absolute;width:34px;height:34px;" +
        "transform:translate(-50%,-50%);cursor:pointer;z-index:" + this.z;
      this.div.innerHTML = this.h;
      if (this.c) {
        this.div.addEventListener("click", (e) => { e.stopPropagation(); this.c(e); });
        if (g.maps.OverlayView.preventMapHitsAndGesturesFrom)
          g.maps.OverlayView.preventMapHitsAndGesturesFrom(this.div);
      }
      this.getPanes().overlayMouseTarget.appendChild(this.div);
    }
    draw(){
      if (!this.div) return;
      const pt = this.getProjection()
        .fromLatLngToDivPixel(new google.maps.LatLng(this.p.lat, this.p.lng));
      if (pt) { this.div.style.left = pt.x + "px"; this.div.style.top = pt.y + "px"; }
    }
    onRemove(){ if (this.div) { this.div.remove(); this.div = null; } }
  };
  return HtmlMarker;
}

function buildGoogleMap(g){
  if (gmap) return;
  const v = LS.get("view", { lat: 45.8131, lng: 15.9775, zoom: 17 });
  gmap = new g.maps.Map(document.getElementById("gmap"), {
    center: { lat: v.lat, lng: v.lng }, zoom: v.zoom,
    disableDefaultUI: true, gestureHandling: "greedy", clickableIcons: true,
    backgroundColor: "#0d1117", styles: gStyles(),
  });
  makeMarkerClass(g);
  gmap.addListener("idle", saveView);
  gmap.addListener("idle", layoutPins);
  gmap.addListener("click", onMapClick);
}

/* ---------------- one view, whichever engine is showing ---------------- */
function usingGoogle(){ return ENGINE === "detail" && !!gmap; }
function currentView(){
  if (usingGoogle()) {
    const c = gmap.getCenter();
    return c ? { lat:c.lat(), lng:c.lng(), zoom:gmap.getZoom() } : LS.get("view", null);
  }
  const c = map.getCenter();
  return { lat:c.lat, lng:c.lng, zoom:map.getZoom() };
}
function setView(v, zoom){
  const z = zoom == null ? (v.zoom == null ? 17 : v.zoom) : zoom;
  if (usingGoogle()) { gmap.setCenter({ lat:v.lat, lng:v.lng }); gmap.setZoom(z); }
  else map.setView([v.lat, v.lng], z);
}
function saveView(){ const v = currentView(); if (v) LS.set("view", v); }
function inView(lat, lng){
  try {
    if (usingGoogle()) { const b = gmap.getBounds(); return b ? b.contains({ lat, lng }) : true; }
    return map.getBounds().contains([lat, lng]);
  } catch (e) { return true; }
}

async function setEngine(mode, quiet){
  if (mode === ENGINE && (mode === "free" || gmap)) { applyLayers(); return true; }
  const keep = currentView();
  if (mode === "detail") {
    if (!API_KEY) {
      hud("The detailed map needs a Google key. ⚙ → Load key from file.");
      renderLayers(); return false;
    }
    if (!quiet) hud("Loading the detailed map…", true);
    try {
      const g = await loadGoogle();
      /* the container has to be on screen first — Google measures the div when
         the map is created, and a hidden one measures zero */
      document.body.classList.add("gengine");
      buildGoogleMap(g);
      ENGINE = "detail"; LS.set("engine", ENGINE);
      if (keep) setView(keep, keep.zoom);
      applyLayers(); redrawAll();
      if (!quiet) hud("Detailed map on. Every layer is yours in ⚙.");
    } catch (e) {
      ENGINE = "free"; LS.set("engine", "free");
      document.body.classList.remove("gengine");
      hud("Detailed map unavailable: " + esc(e.message) + ".");
      applyLayers(); renderLayers(); redrawAll();
      return false;
    }
  } else {
    ENGINE = "free"; LS.set("engine", "free");
    document.body.classList.remove("gengine");
    if (keep) setView(keep, keep.zoom);
    setTimeout(() => map.invalidateSize(), 60);
    applyLayers(); redrawAll();
    if (!quiet) hud("Free map on.");
  }
  renderLayers();
  return true;
}

function applyLayers(){
  LS.set("layers", LAYERS);
  if (usingGoogle()) { gmap.setOptions({ styles: gStyles() }); }
  else if (names) { if (LAYERS.streets) names.addTo(map); else map.removeLayer(names); }
  document.getElementById("btnLabels").classList.toggle("on", !!LAYERS.streets);
}
document.getElementById("btnLabels").addEventListener("click", () => {
  LAYERS.streets = !LAYERS.streets; applyLayers(); renderLayers();
  hud(LAYERS.streets ? "Street names on." : "Street names off. Only the stations remain.");
});

/* ---------------- drawing, on whichever engine ---------------- */
/* [id] ★ Name DIR — the GTFS stop id rides on the left of the star, in the
   station's own colour. Both chips are absolutely positioned inside the pin,
   so neither of them can shift the star off its coordinate. */
function pinHTML(s){
  // The number, and nothing else.
  //
  // This pin used to carry three things: a number, a star and a name. On a
  // phone, in the middle of a city, that is three overlapping labels for
  // every station and half a dozen stations in view, so the map became a
  // pile of text with a map somewhere underneath it.
  //
  // The star is gone. It marked a station as "watched", which was a second
  // idea stacked on top of simply picking one, and it had to be learned
  // before it meant anything.
  //
  // The name is gone from the map because the number already identifies the
  // station, and the name comes back in the popup the moment the number is
  // tapped, which is the only moment it is needed.
  //
  // The direction letter stays. It is one character, and two stops sharing
  // a number on opposite sides of a road is exactly the confusion a map has
  // to resolve rather than add to.
  const c = COLOUR[s.stop_id], ab = dirAbbr(s.bearing);
  return '<div class="pin">' +
    '<span class="pinid"><span style="--c:' + c + '">' + esc(s.stop_id) +
    (ab ? ' <i>' + ab + '</i>' : "") + '</span></span></div>';
}
// Arming a station: the outline is immediate, the fetch is not.
//
// A tap used to go straight to the network, so the first thing that happened
// after touching a station was nothing, for as long as the request took. On
// a phone that reads as a dead app and the finger taps again.
//
// Now the outline lands on the same frame as the tap, and the fetch waits a
// third of a second. Long enough to change your mind after a mis-tap, short
// enough that a deliberate tap does not feel held back. Tap three stations
// in a row and only the third is ever fetched: each tap moves the outline
// and cancels the one before it.
//
// SELGEN is what makes a cancelled fetch stay cancelled. A request already
// in flight cannot be recalled, but its answer can be thrown away, and the
// generation it was started under is how it knows it is stale.
let ARM_T = null, SELGEN = 0;
function armStation(s){
  SELGEN++;
  const gen = SELGEN;
  if (ARM_T) { clearTimeout(ARM_T); ARM_T = null; }
  document.querySelectorAll(".pin.armed").forEach(e => e.classList.remove("armed"));
  const mk = MARKS[s.stop_id];
  const el = mk && mk.getElement ? mk.getElement() : null;
  const pin = el ? el.querySelector(".pin") : null;
  if (pin) pin.classList.add("armed");
  hud("<b>" + esc(s.stop_id) + "</b> selected", true);
  ARM_T = setTimeout(() => {
    if (gen !== SELGEN) return;
    hud("<b>" + esc(s.stop_id) + "</b> reading arrivals", true);
    openPop(s, gen);
  }, 180);
}
function clearStars(){
  Object.values(MARKS).forEach(m => { try { map.removeLayer(m); } catch (e) {} });
  MARKS = {};
  gPins.forEach(p => { try { p.setMap(null); } catch (e) {} });
  gPins = [];
}

/* v21: labels never sit on top of each other. A label is moved off its station,
   to the side of the street the platform is on (the right of the way the
   vehicles leave, as they drive on the right), far enough that its edge clears
   the station; labels that still touch are pushed apart. A thin line and a dot
   keep the true position visible. Recomputed on every zoom, in screen pixels. */
function pxOf(s){
  try {
    if (usingGoogle()) {
      const pr = gmap.getProjection(); if (!pr) return null;
      const q = pr.fromLatLngToPoint(new google.maps.LatLng(s.lat, s.lon));
      const k = Math.pow(2, gmap.getZoom());
      return { x: q.x * k, y: q.y * k };
    }
    const q = map.latLngToContainerPoint([s.lat, s.lon]);
    return { x: q.x, y: q.y };
  } catch (e) { return null; }
}
function pinEl(s){
  if (usingGoogle()) {
    const p = gPins[STOPS.indexOf(s)];
    return p && p.div ? p.div.querySelector(".pin") : null;
  }
  const m = MARKS[s.stop_id], e = m && m.getElement ? m.getElement() : null;
  return e ? e.querySelector(".pin") : null;
}
function layoutPins(){
  const it = [];
  STOPS.forEach(s => {
    const el = pinEl(s), p = pxOf(s);
    if (!el || !p) return;
    const sp = el.querySelector(".pinid span");
    const r = sp ? sp.getBoundingClientRect() : { width: 60, height: 27 };
    const w = (r.width || 60) + 6, h = (r.height || 27) + 6;
    let dx = 0, dy = 0;
    if (s.bearing != null) {
      const b = s.bearing * Math.PI / 180;
      const rx = Math.cos(b), ry = Math.sin(b);          // right of the way it leaves
      const d = Math.abs(rx) * w / 2 + Math.abs(ry) * h / 2 + 18;
      dx = rx * d; dy = ry * d;
    }
    it.push({ s, el, p, w, h, dx, dy });
  });
  // a label must stay on the screen: keep its centre inside the map, with a margin
  // (the Leaflet map only; the Google pixels have no fixed origin to clamp against)
  const sz = !usingGoogle() && map ? map.getSize() : null;
  // What is drawn over the map, measured now and not guessed: the status line,
  // the buttons and the GPS chip on top; the watch bar at the bottom.
  const lim = { top: 8, bottom: sz ? sz.y - 4 : 0 };
  if (sz) {
    const mr = map.getContainer().getBoundingClientRect();
    ["hud", "tools", "gpsChip"].forEach(id => {
      const e = document.getElementById(id); if (!e) return;
      const r = e.getBoundingClientRect();
      if (r.width > 0 && r.height > 0) lim.top = Math.max(lim.top, r.bottom - mr.top + 6);
    });
    const wb = document.getElementById("watchbar");
    if (wb && getComputedStyle(wb).display !== "none") {
      const r = wb.getBoundingClientRect();
      if (r.height > 0) lim.bottom = Math.min(lim.bottom, r.top - mr.top - 6);
    }
  }
  const clampAll = () => {
    if (!sz) return false;
    let c = false;
    it.forEach(o => {
      const nx = Math.min(Math.max(o.p.x + o.dx, o.w / 2 + 4), sz.x - o.w / 2 - 4) - o.p.x;
      const lo = lim.top + o.h / 2, hi = lim.bottom - o.h / 2;
      const ny = (hi > lo ? Math.min(Math.max(o.p.y + o.dy, lo), hi) : o.p.y + o.dy) - o.p.y;
      if (Math.abs(nx - o.dx) > .5 || Math.abs(ny - o.dy) > .5) c = true;
      o.dx = nx; o.dy = ny;
    });
    return c;
  };
  for (let k = 0; k < 80; k++) {
    let moved = false;
    for (let i = 0; i < it.length; i++) for (let j = i + 1; j < it.length; j++) {
      const a = it[i], b = it[j];
      const cx = (b.p.x + b.dx) - (a.p.x + a.dx), cy = (b.p.y + b.dy) - (a.p.y + a.dy);
      const ox = (a.w + b.w) / 2 - Math.abs(cx), oy = (a.h + b.h) / 2 - Math.abs(cy);
      if (ox <= 0 || oy <= 0) continue;
      moved = true;
      if (ox < oy) { const sg = cx === 0 ? (i < j ? 1 : -1) : Math.sign(cx); a.dx -= sg * ox / 2; b.dx += sg * ox / 2; }
      else { const sg = cy === 0 ? (i < j ? 1 : -1) : Math.sign(cy); a.dy -= sg * oy / 2; b.dy += sg * oy / 2; }
    }
    if (clampAll()) moved = true;
    if (!moved) break;
  }
  it.forEach(o => {
    const L = Math.hypot(o.dx, o.dy);
    o.el.style.setProperty("--dx", o.dx.toFixed(1) + "px");
    o.el.style.setProperty("--dy", o.dy.toFixed(1) + "px");
    let ld = o.el.querySelector(".pinlead");
    if (!ld) { ld = document.createElement("i"); ld.className = "pinlead"; o.el.insertBefore(ld, o.el.firstChild); }
    ld.style.display = L < 6 ? "none" : "block";
    ld.style.width = L.toFixed(1) + "px";
    ld.style.background = COLOUR[o.s.stop_id] || "#fff";
    ld.style.color = COLOUR[o.s.stop_id] || "#fff";
    ld.style.transform = "rotate(" + (Math.atan2(-o.dy, -o.dx) * 180 / Math.PI).toFixed(1) + "deg)";
  });
}
function drawStars(){
  clearStars();
  if (MODE === "google") return;   // Google draws the stations in that view
  if (!STOPS.length) return;
  STOPS.forEach(s => {
    const on = isWatched(s.stop_id);
    if (usingGoogle()) {
      const p = new HtmlMarker({ lat:s.lat, lng:s.lon }, pinHTML(s),
        () => armStation(s), on ? 1000 : 500);
      p.setMap(gmap); gPins.push(p);
    } else {
      const icon = L.divIcon({ html: pinHTML(s), className: "starwrap",
        iconSize: [34, 34], iconAnchor: [17, 17] });
      const m = L.marker([s.lat, s.lon], { icon, zIndexOffset: on ? 1000 : 500 }).addTo(map);
      m.on("click", () => armStation(s));
      MARKS[s.stop_id] = m;
    }
  });
  layoutPins(); setTimeout(layoutPins, 80);
}
let gAcc = null, meAcc = null;
function meHTML(){
  const cls = ME && ME.pinned ? " pin" : ((ME && ME.acc > 25) ? " weak" : "");
  return '<div class="medot' + cls + '"><i></i><b></b></div>';
}
function drawMe(){
  if (meMk) { try { map.removeLayer(meMk); } catch (e) {} meMk = null; }
  if (meRing) { try { map.removeLayer(meRing); } catch (e) {} meRing = null; }
  if (meAcc) { try { map.removeLayer(meAcc); } catch (e) {} meAcc = null; }
  if (gMe) { gMe.setMap(null); gMe = null; }
  if (gRing) { gRing.setMap(null); gRing = null; }
  if (gAcc) { gAcc.setMap(null); gAcc = null; }
  if (!ME) return;
  const acc = ME.pinned ? 0 : (ME.acc || 0);
  if (usingGoogle()) {
    gRing = new google.maps.Circle({ map:gmap, center:{ lat:ME.lat, lng:ME.lng },
      radius:RADIUS, strokeColor:"#39d0d8", strokeOpacity:.32, strokeWeight:1,
      fillColor:"#39d0d8", fillOpacity:.04, clickable:false });
    if (acc > 4) gAcc = new google.maps.Circle({ map:gmap,
      center:{ lat:ME.lat, lng:ME.lng }, radius:acc, strokeColor:"#39d0d8",
      strokeOpacity:.5, strokeWeight:1, fillOpacity:0, clickable:false, zIndex:40 });
    /* fixed 22 px, the size of Google's own station icon. The old version was a
       Circle with radius 9 METRES, which is why it swelled as you zoomed in. */
    gMe = new HtmlMarker({ lat:ME.lat, lng:ME.lng }, meHTML(), null, 60);
    gMe.setMap(gmap);
  } else {
    meRing = L.circle([ME.lat, ME.lng], { radius:RADIUS, color:"#39d0d8", weight:1,
      opacity:.32, fill:false, interactive:false }).addTo(map);
    if (acc > 4) meAcc = L.circle([ME.lat, ME.lng], { radius:acc, color:"#39d0d8",
      weight:1, opacity:.5, fill:false, interactive:false }).addTo(map);
    meMk = L.marker([ME.lat, ME.lng], { interactive:false, zIndexOffset:60,
      icon: L.divIcon({ html: meHTML(), className:"starwrap",
                        iconSize:[22,22], iconAnchor:[11,11] }) }).addTo(map);
  }
}
function redrawAll(){ drawMe(); drawStars(); }

/* ---------------- where you are ---------------- */
/* =========================================================================
   POSITION
   A single getCurrentPosition returns whatever the phone has to hand, which is
   usually the coarse network fix -- cell towers and wifi -- because the GNSS
   chip has not finished converging. That is the loose position you were
   seeing, and no option fixes it because the problem is that we stopped
   listening too early.

   So we listen in bursts instead. watchPosition keeps delivering fixes as more
   satellites lock and the estimate tightens, and we keep the good ones and
   average them. Averaging cancels the random half of the error. It does NOT
   cancel multipath -- signal bouncing off the buildings along Ilica -- which
   is a bias, not noise, and is the reason a phone in a street canyon can sit
   confidently thirty metres from where you stand.
   ========================================================================= */
let FIXES = [];            // recent accepted fixes
let watchId = null, burstEnd = 0, burstTick = null;
const FIX_TTL = 90000;     // a fix older than this is stale

function fuse(){
  /* inverse-variance weighting: a fix claiming 5 m counts for far more than
     one claiming 40 m, which is exactly how you should treat them */
  const now = Date.now();
  const live = FIXES.filter(f => now - f.t < FIX_TTL);
  if (!live.length) return null;
  const best = Math.min.apply(null, live.map(f => f.acc));
  const use = live.filter(f => f.acc <= Math.max(best * 2.5, best + 8));
  let wsum = 0, la = 0, lo = 0;
  use.forEach(f => { const w = 1 / (f.acc * f.acc); wsum += w; la += f.lat * w; lo += f.lng * w; });
  if (!wsum) return null;
  /* honest error estimate: averaging n independent samples would give
     best/sqrt(n), but GNSS errors are correlated over short spans, so we never
     claim better than 60% of the best single fix */
  const acc = Math.max(best * 0.6, best / Math.sqrt(use.length));
  return { lat: la / wsum, lng: lo / wsum, acc: Math.round(acc * 10) / 10, n: use.length };
}

function applyFix(quiet){
  if (ME && ME.pinned) return;
  const f = fuse();
  if (!f) return;
  const moved = ME ? metres(ME.lat, ME.lng, f.lat, f.lng) : 1e9;
  ME = { lat: f.lat, lng: f.lng, acc: f.acc, n: f.n };
  // No map yet: the fix is kept (FIXES) and boot calls this again the moment
  // the map is up. Nothing is drawn onto a map that is not there.
  if (!map && !gmap) return;
  drawMe();
  updateAccBox(); paintChip();
  if (WANT_CENTRE || (!CENTRED && !HAD_VIEW)) { setView(ME, Math.max(17, curZoom())); CENTRED = true; WANT_CENTRE = false; }
  const need = lastStopFetch
    ? metres(lastStopFetch.lat, lastStopFetch.lng, ME.lat, ME.lng) : 1e9;
  if (need > 35 || !STOPS.length) loadStops();
  else if (!quiet) hud(stopsLine());
}
function curZoom(){ const v = currentView(); return v && v.zoom ? v.zoom : 17; }

function startBurst(ms){
  if (!navigator.geolocation) { hud("This browser has no location service."); return; }
  burstEnd = Math.max(burstEnd, Date.now() + ms);
  if (watchId !== null) return;
  hud("Finding you…", true);
  watchId = navigator.geolocation.watchPosition(p => {
    const acc = p.coords.accuracy == null ? 999 : p.coords.accuracy;
    if (acc > 300) return;                       // a cell-tower guess, not a fix
    FIXES.push({ lat: p.coords.latitude, lng: p.coords.longitude, acc: acc, t: Date.now() });
    if (FIXES.length > 40) FIXES.shift();
    applyFix(true);
    const f = fuse();
    if (f) hud("Within <b>±" + Math.round(f.acc) + " m</b>" +
      (STOPS.length ? " · " + STOPS.length + " stations near you" : "") +
      ". Tap a station.");
    /* good enough, and settled: stop burning the GNSS chip */
    if (f && f.acc <= 8 && f.n >= 4 && Date.now() > burstEnd - ms + 6000) stopBurst();
  }, err => {
    stopBurst();
    if (err && err.code === 1)
      hud("Location refused. Pan the map to where you are, or pin yourself in ⚙.");
    else hud("No position yet. ⚙ → Position has ways to help.");
    if (!STOPS.length) loadStops();
  }, { enableHighAccuracy: true, maximumAge: 0, timeout: ms });
  /* a repeating check, not a one-shot: a burst can be extended by another
     foreground event, and a single timer would fire early and leave the GNSS
     chip running for the rest of the day */
  if (burstTick === null) burstTick = setInterval(() => {
    if (watchId === null || Date.now() >= burstEnd) {
      clearInterval(burstTick); burstTick = null; stopBurst();
    }
  }, 1000);
}
function stopBurst(){
  if (watchId !== null) { try { navigator.geolocation.clearWatch(watchId); } catch (e) {} }
  watchId = null;
  if (burstTick !== null) { clearInterval(burstTick); burstTick = null; }
  paintChip(); loadGps(false);
  updateAccBox();
}
function autoLocate(force){
  if (ME && ME.pinned) return;
  const now = Date.now();
  if (!force && now - lastFix < 8000) return;
  lastFix = now;
  startBurst(force ? 30000 : 18000);
}
function sharpen(){
  if (ME && ME.pinned) { hud("You are pinned by hand. Unpin in ⚙ first."); return; }
  FIXES = [];
  hud("Hold still — collecting satellites for 30 seconds…", true);
  startBurst(30000);
}

/* ---------------- the stations ---------------- */
function anchor(){
  if (ME) return { lat: ME.lat, lng: ME.lng };
  const v = currentView();
  return { lat: v.lat, lng: v.lng };
}
function assignColours(list){
  /* nearest first gets first pick, but a station keeps the colour it already
     had if that colour is still free. Walking past a stop must not repaint the
     whole map. */
  const taken = new Set(), next = {};
  list.forEach(s => {
    const had = COLOUR[s.stop_id];
    if (had && !taken.has(had)) { next[s.stop_id] = had; taken.add(had); }
  });
  list.forEach(s => {
    if (next[s.stop_id]) return;
    const free = PALETTE.find(c => !taken.has(c)) ||
      PALETTE[Object.keys(next).length % PALETTE.length];
    next[s.stop_id] = free; taken.add(free);
  });
  COLOUR = next;
}
function stopsLine(){
  const n = STOPS.length;
  if (!n) return "No station within <b>" + fmtDist(RADIUS) + "</b>.";
  return "<b>" + n + "</b> station" + (n === 1 ? "" : "s") + " within <b>" +
    fmtDist(STOPS[STOPS.length - 1].dist) + "</b>. Tap a station to see what is coming.";
}
async function loadStops(){
  if (!INDEX_OK) return;
  const at = anchor();
  lastStopFetch = at;
  const seq = ++STOPSEQ;
  hud("Reading the stations around you…", true);
  try {
    let d = await fetch("stops?lat=" + at.lat + "&lon=" + at.lng + "&r=" + RADIUS + "&widen=0",
      { cache: "no-store" }).then(r => r.json());
    let widened = false;
    if (d.ok && !(d.stops || []).length) {
      d = await fetch("stops?lat=" + at.lat + "&lon=" + at.lng + "&r=" + RADIUS + "&widen=1",
        { cache: "no-store" }).then(r => r.json());
      widened = true;
    }
    if (seq !== STOPSEQ) return;       // a newer request has gone out since
    if (!d.ok) { hud("Server said: " + esc(d.reason || "no reason given")); return; }
    STOPS = (d.stops || []).slice(0, 8);
    assignColours(STOPS);
    drawStars();
    if (!STOPS.length) hud("No station anywhere near. Try the radius in ⚙.");
    else if (widened) hud("Nothing within <b>" + fmtDist(RADIUS) +
      "</b>, so this reaches out to <b>" + fmtDist(STOPS[STOPS.length - 1].dist) + "</b>.");
    else hud(stopsLine());
    refreshBoards();
  } catch (e) {
    hud("Could not reach the server: " + esc(e.message || e));
  }
}

/* ---------------- the boards ---------------- */
function isWatched(id){ return !!(WATCH && WATCH.stop_id === id); }
async function fetchBoard(s){
  try {
    const d = await fetch("board?stop=" + encodeURIComponent(s.stop_id) +
      "&mins=60&back=10", { cache: "no-store" }).then(r => r.json());
    if (d.ok) BOARDS[s.stop_id] = d;
  } catch (e) { /* keep whatever we had */ }
}
async function refreshBoards(){
  if (!STOPS.length) return;
  /* the first warms the server's realtime cache, the rest ride behind it
     instead of all reaching for the feed at the same moment */
  await fetchBoard(STOPS[0]);
  await Promise.all(STOPS.slice(1).map(fetchBoard));
  if (document.getElementById("dash").classList.contains("show")) renderDash();
  updateWatchBar();
}
function comingAt(id){
  const b = BOARDS[id];
  return b ? (b.departures || []).filter(x => !x.passed) : [];
}

/* ---------------- the still photograph ---------------- */
async function streetView(s){
  if (s.stop_id in SV_CACHE) return SV_CACHE[s.stop_id];
  if (!API_KEY) { SV_CACHE[s.stop_id] = null; return null; }
  const loc = s.lat + "," + s.lon;
  const head = s.bearing == null ? "" : "&heading=" + Math.round((s.bearing + 180) % 360);
  const url = "https://maps.googleapis.com/maps/api/streetview?size=640x260&location=" +
    loc + "&fov=80&pitch=2" + head + "&return_error_code=true&key=" + encodeURIComponent(API_KEY);
  try {
    const meta = await fetch("https://maps.googleapis.com/maps/api/streetview/metadata?location=" +
      loc + "&key=" + encodeURIComponent(API_KEY)).then(r => r.json());
    SV_CACHE[s.stop_id] = meta && meta.status === "OK" ? url : null;
  } catch (e) {
    SV_CACHE[s.stop_id] = url;      // metadata blocked; show it and let it try
  }
  return SV_CACHE[s.stop_id];
}

/* ---------------- the 360 view ----------------
   The card photo is a still because four live panoramas in a scrolling list
   would fight your finger and cost four panorama loads. Tap it and you get
   the real thing, full screen, turning under your thumb. */
let pano = null, panoGyro = false;
async function openPano(id){
  const s = stationFor(id);
  if (!s) return;
  const box = document.getElementById("pano");
  const el = document.getElementById("panoView");
  document.getElementById("panoName").textContent = s.name;
  const hint = document.getElementById("panoHint");
  hint.textContent = "drag to look around";
  hint.style.opacity = "1";
  box.classList.add("show");
  document.body.classList.add("panoopen");
  if (!API_KEY) {
    el.innerHTML = '<div class="panomsg">The 360° view needs a Google key.<br>' +
      '⚙ → Load key from file.</div>';
    return;
  }
  el.innerHTML = '<div class="panomsg">Opening the street…</div>';
  let g;
  try { g = await loadGoogle(); }
  catch (e) {
    el.innerHTML = '<div class="panomsg">Could not open the 360° view:<br>' +
      esc(e.message) + '</div>';
    return;
  }
  new g.maps.StreetViewService().getPanorama(
    { location: { lat: s.lat, lng: s.lon }, radius: 70 },
    (data, status) => {
      if (status !== "OK" || !data || !data.location) {
        el.innerHTML = '<div class="panomsg">No Street View imagery at this stop.</div>';
        return;
      }
      el.innerHTML = "";
      panoGyro = false;
      document.getElementById("panoMotion").classList.remove("on");
      pano = new g.maps.StreetViewPanorama(el, {
        pano: data.location.pano,
        pov: { heading: s.bearing == null ? 0 : (s.bearing + 180) % 360, pitch: 0 },
        zoom: 0,
        addressControl: false, fullscreenControl: false, zoomControl: false,
        panControl: false, motionTracking: false, motionTrackingControl: false,
        linksControl: true, enableCloseButton: false, showRoadLabels: true,
      });
      setTimeout(() => { document.getElementById("panoHint").style.opacity = "0"; }, 4000);
    });
}
function closePano(){
  document.getElementById("pano").classList.remove("show");
  document.body.classList.remove("panoopen");
  /* let go of the panorama so it is not left running behind the map */
  if (pano) { try { pano.setVisible(false); } catch (e) {} pano = null; }
  document.getElementById("panoView").innerHTML = "";
}
document.getElementById("panoClose").addEventListener("click", closePano);
document.getElementById("panoMotion").addEventListener("click", () => {
  if (!pano) return;
  panoGyro = !panoGyro;
  try { pano.setOptions({ motionTracking: panoGyro }); }
  catch (e) { panoGyro = false; }
  document.getElementById("panoMotion").classList.toggle("on", panoGyro);
  document.getElementById("panoHint").style.opacity = "1";
  document.getElementById("panoHint").textContent = panoGyro
    ? "turn the phone to look around" : "drag to look around";
  setTimeout(() => { document.getElementById("panoHint").style.opacity = "0"; }, 3500);
});

/* ---------------- the dashboard ---------------- */
function delayBit(x){
  if (!x.live || x.delay == null) return "";
  if (Math.abs(x.delay) < 30) return ' · <span class="d ok">on time</span>';
  const m = Math.round(Math.abs(x.delay) / 60);
  return ' · <span class="d ' + (x.delay > 0 ? "late" : "ok") + '">' +
    (x.delay > 0 ? "+" : "−") + (m < 1 ? "<1" : m) + " min</span>";
}
const PTAG = '<span class="ptag">printed</span>';
function arrivalRow(x){
  const t = x.live && x.live_at
    ? new Date(x.live_at * 1000).toTimeString().slice(0, 5) : x.sched;
  const cls = x.passed ? "" : (x.mins <= 0 ? "now" : (x.mins <= 5 ? "soon" : ""));
  /* one that has already gone counts backwards: 6 left three minutes ago */
  const big = x.passed ? "−" + Math.abs(x.mins) : (x.mins <= 0 ? "now" : x.mins);
  const unit = x.passed ? "min ago" : (x.mins <= 0 ? "" : "min");
  const from = x.origin ? '<span class="from">' + esc(x.origin) + "</span> → " : "";
  const mark = x.printed ? PTAG : (x.live ? WIFI : "");
  return '<div class="arow' + (x.printed ? " printed" : "") + '">' +
    '<span class="rt' + (x.live ? "" : " sched") + '" style="--r:' +
      routeColour(x.route) + '">' + esc(x.route) + '</span>' +
    '<span class="od">' + from + esc(x.head || "—") +
      '<i>' + t + mark + delayBit(x) + '</i></span>' +
    '<span class="tm"><b class="' + cls + '">' + big + '</b>' +
      '<small>' + unit + '</small></span>' +
    '</div>';
}
function subLine(s, b){
  const ab = dirAbbr(s.bearing);
  let extra = "";
  if (b && b.printed) extra += " · " + b.printed + " from the printed timetable";
  else if (b && b.index_stale) extra += " · index is from " + (b.service_date || "another day");
  if (b && !b.feed_ok) extra += " · live feed down";
  return fmtDist(s.dist) + " away" + (ab ? " · vehicles head " + ab : "") + extra;
}
function arrHTML(b){
  if (!b) return '<div class="empty">Reading the board…</div>';
  const all = b.departures || [];
  const gone = all.filter(x => x.passed).slice(-4);
  const coming = all.filter(x => !x.passed).slice(0, 10);
  let html = "";
  if (gone.length) html += '<div class="popsec">just left</div>' +
    gone.map(x => arrivalRow(x).replace('class="arow', 'class="arow gone')).join("");
  return html + '<div class="popsec">coming</div>' + (coming.length
    ? coming.map(arrivalRow).join("")
    : '<div class="empty">Nothing in the next hour.</div>');
}
function photoHTML(s){
  const sv = SV_CACHE[s.stop_id];
  if (sv === undefined) return '<div class="svnone">Loading the photograph…</div>';
  if (!sv) return '<div class="svnone">' + (API_KEY
    ? "No Street View photograph here."
    : "Add a Google key in ⚙ to see the stop.") + '</div>';
  return '<span class="svwrap" data-pano="' + esc(s.stop_id) + '">' +
    '<img class="sv" src="' + esc(sv) + '" alt="' + esc(s.name) + '" loading="lazy"' +
    ' onerror="this.style.display=\'none\'">' +
    '<span class="svpin"><span class="svpinlabel">' + esc(s.stop_id) + '</span></span>' +
    '<span class="sv360">◉ 360°</span></span>';
}
function cardHTML(s){
  const c = stationColour(s.stop_id), on = isWatched(s.stop_id);
  return '<div class="card' + (on ? " on" : "") + '" style="--c:' + c + '" id="card-' +
      esc(s.stop_id) + '">' +
    '<div class="chead">' + starHTML(c, false, true) +
      '<span class="nm">' + (on ? "You are watching this stop" : "Watch it from the map") +
        '<i>' + (on ? "the bar at the bottom keeps the next one" : "its next arrival stays in a bar") + '</i></span>' +
      '<button class="wbtn' + (on ? " on" : "") + '" data-watch="' + esc(s.stop_id) + '">' +
        (on ? "WATCHING" : "WATCH") + '</button>' +
    '</div>' + photoHTML(s) +
    '<div class="arr">' + arrHTML(BOARDS[s.stop_id]) + '</div></div>';
}

/* v20: one station, one dashboard. The dashboard is never a list of every
   station around you; it opens for the station that was tapped, and only
   that one. Everything it shows is that station: its photograph, what has
   just left and what is coming. */
let DASH_SIG = "", DASH_HIST = false;
function stationFor(id){
  if (SEL && SEL.stop_id === id) return SEL;
  const s = STOPS.find(x => x.stop_id === id);
  if (s) return s;
  if (WATCH && WATCH.stop_id === id) {
    const w = Object.assign({}, WATCH);
    if (ME) w.dist = metres(ME.lat, ME.lng, w.lat, w.lon);
    return w;
  }
  return null;
}
function renderDash(){
  const s = SEL, body = document.getElementById("dBody");
  if (!s) { DASH_SIG = ""; body.innerHTML = ""; return; }
  const b = BOARDS[s.stop_id];
  document.getElementById("dash").style.setProperty("--c", stationColour(s.stop_id));
  document.getElementById("dId").textContent = s.stop_id;
  document.getElementById("dName").textContent = s.name;
  document.getElementById("dSub").textContent =
    subLine(s, b) + (b && b.feed_ok ? " · live" : "");
  /* rebuilt only when the station, its photograph or the watch changes, so a
     twenty-second refresh neither reloads the picture nor moves your scroll */
  const sig = s.stop_id + ":" +
    (s.stop_id in SV_CACHE ? (SV_CACHE[s.stop_id] ? "p" : "n") : "?") +
    (isWatched(s.stop_id) ? "w" : "");
  if (sig !== DASH_SIG) {
    const same = DASH_SIG.split(":")[0] === s.stop_id;
    DASH_SIG = sig;
    const keep = same ? body.scrollTop : 0;
    body.innerHTML = cardHTML(s);
    body.scrollTop = keep;
    return;
  }
  const arr = body.querySelector(".arr");
  if (arr) arr.innerHTML = arrHTML(b);
}
function dashOpen(){ return document.getElementById("dash").classList.contains("show"); }
function openDash(id){ const s = stationFor(id); if (s) openPop(s); }
document.getElementById("dClose").addEventListener("click", () => closePop());
document.getElementById("dBody").addEventListener("click", (e) => {
  const w = e.target.closest("[data-watch]");
  if (w) { toggleWatch(w.dataset.watch); return; }
  const p = e.target.closest("[data-pano]");
  if (p) { openPano(p.dataset.pano); return; }
});
/* the phone's back gesture closes the dashboard instead of leaving the app */
window.addEventListener("popstate", () => {
  if (DASH_HIST) { DASH_HIST = false; closePop(true); }
});

/* ---------------- watching one station ---------------- */
function watchStation(s){
  WATCH = { stop_id: s.stop_id, name: s.name, lat: s.lat, lon: s.lon };
  LS.set("watch", WATCH);
  document.body.classList.add("watching");
  if (!COLOUR[s.stop_id]) COLOUR[s.stop_id] = stationColour(s.stop_id);
  drawStars(); updateWatchBar();
  if (!boardTimer) boardTimer = setInterval(refreshBoards, 20000);
}
function toggleWatch(id){
  if (isWatched(id)) { clearWatch(); return; }
  const s = stationFor(id);
  if (!s) return;
  watchStation(s); renderDash();
  hud("Watching <b>" + esc(s.name) + "</b>.");
}
function clearWatch(){
  WATCH = null; LS.del("watch");
  document.body.classList.remove("watching");
  drawStars(); renderDash();
}
function updateWatchBar(){
  if (!WATCH) return;
  const c = COLOUR[WATCH.stop_id] || PALETTE[0];
  const bar = document.getElementById("watchbar");
  bar.style.setProperty("--c", c);
  const st = document.getElementById("wbStar");
  if (st) st.outerHTML = starHTML(c, false, true)
    .replace('class="star mini"', 'class="star mini" id="wbStar"');
  document.getElementById("wbName").textContent = WATCH.name;
  const next = comingAt(WATCH.stop_id)[0];
  document.getElementById("wbEta").innerHTML = next
    ? '<span class="rt sm' + (next.live ? "" : " sched") + '" style="--r:' +
      routeColour(next.route) + '">' + esc(next.route) + '</span> ' +
      (next.mins <= 0 ? "now" : next.mins + " min") + (next.live ? WIFI : "")
    : "—";
}
document.getElementById("watchbar").addEventListener("click", (e) => {
  if (e.target.closest("#wbX")) { clearWatch(); return; }
  if (WATCH) openDash(WATCH.stop_id);
});

/* ---------------- settings ---------------- */
function setDot(ok){ document.getElementById("keyDot").className = "dot " + (ok ? "ok" : ""); }
function renderLayers(){
  const detail = ENGINE === "detail";
  document.getElementById("engFree").classList.toggle("on", !detail);
  document.getElementById("engDetail").classList.toggle("on", detail);
  document.getElementById("layerBox").innerHTML = LAYER_DEFS.map((d, i) => {
    const avail = d.lock || !d.google || detail;
    let note = d.note, on = d.lock ? true : !!LAYERS[d.id];
    if (!avail) {
      note = "detailed map only";
      if (d.id === "places") { note = "comes with street names on the free map"; on = !!LAYERS.streets; }
    }
    return '<div class="lrow' + (avail ? "" : " off") + (i < 2 ? " heavy" : "") +
      '" data-layer="' + d.id + '">' +
      '<span class="lnum">' + (i + 1) + '</span>' +
      '<span class="lname">' + esc(d.name) + '<i>' + esc(note) + '</i></span>' +
      (d.lock ? '<span class="llock">always</span>'
              : '<span class="lsw' + (on ? " on" : "") + '"></span>') +
      '</div>';
  }).join("");
  document.getElementById("layerNote").innerHTML = detail
    ? "Google's map, taken apart layer by layer. Turn off what you do not need — " +
      "the fewer layers, the faster it is to read a stop at a glance."
    : "Free tiles are pre-drawn pictures, so street names and district names come " +
      "as one layer and there are no shops in them at all. For real control over " +
      "every layer, switch to the detailed map.";
}
document.getElementById("layerBox").addEventListener("click", (e) => {
  const row = e.target.closest("[data-layer]");
  if (!row) return;
  const id = row.dataset.layer;
  const def = LAYER_DEFS.find(d => d.id === id);
  if (!def || def.lock) return;
  if (def.google && ENGINE !== "detail") {
    hud("That layer lives on the detailed map.");
    document.getElementById("layerNote").textContent =
      "“" + def.name + "” needs the detailed map. Switch it on above.";
    return;
  }
  LAYERS[id] = !LAYERS[id];
  applyLayers(); renderLayers();
});
document.getElementById("engFree").addEventListener("click", () => setEngine("free"));
document.getElementById("engDetail").addEventListener("click", () => setEngine("detail"));

document.getElementById("btnSetup").addEventListener("click", () => {
  document.getElementById("setup").classList.add("show");
  document.getElementById("rLbl").textContent = fmtDist(RADIUS);
  fetch("lan-ip", { cache: "no-store" }).then(r => r.json()).then(d => { const el = document.getElementById("ipLine");
    if (el) el.textContent = (d && d.ip) ? "on Wi-Fi:  http://" + d.ip + ":" + (location.port || "8084") + "/all.html"
      : "on this phone only (no Wi-Fi address)"; }).catch(() => {});
  renderLayers(); loadStatus(); updateAccBox();
  loadGemStatus().then(() => { loadSched(); loadModelState(); });
});
document.getElementById("sClose").addEventListener("click", () =>
  document.getElementById("setup").classList.remove("show"));
document.getElementById("keyFile").addEventListener("change", async (e) => {
  const msg = document.getElementById("keyMsg");
  const f = e.target.files && e.target.files[0]; if (!f) return;
  const text = (await f.text()).trim(); e.target.value = "";
  if (!text) { msg.textContent = "Empty file."; return; }
  msg.textContent = "Saving…";
  try {
    const d = await fetch("api-keys", { method: "POST", body: text }).then(r => r.json());
    if (d.ok) {
      API_KEY = d.keys[0]; setDot(true);
      msg.textContent = "Saved. The 360° view and the detailed map are open to you now.";
      Object.keys(SV_CACHE).forEach(k => delete SV_CACHE[k]);
      gPromise = null;
      loadPhotos(); renderLayers();
    } else msg.textContent = "Could not save the key.";
  } catch (err) { msg.textContent = "Could not save the key."; }
});
function stepRadius(dir){
  let i = RSTEPS.indexOf(RADIUS); if (i < 0) i = 1;
  i = Math.max(0, Math.min(RSTEPS.length - 1, i + dir));
  RADIUS = RSTEPS[i]; LS.set("radius", RADIUS);
  document.getElementById("rLbl").textContent = fmtDist(RADIUS);
  drawMe(); loadStops();
}
document.getElementById("rPlus").addEventListener("click", () => stepRadius(1));
document.getElementById("rMinus").addEventListener("click", () => stepRadius(-1));

async function loadStatus(){
  try {
    const d = await fetch("status", { cache: "no-store" }).then(r => r.json());
    document.getElementById("statBox").innerHTML =
      '<div class="kv"><span>Stations</span><b>' + (d.ok ? "cached" : "not cached") + '</b></div>' +
      '<div class="kv"><span>Schedule day</span><b>' + (d.service_date || "—") + '</b></div>' +
      '<div class="kv"><span>Stops</span><b>' + (d.stops || "—") + '</b></div>' +
      '<div class="kv"><span>Live feed</span><b>' +
        (d.feed_ok ? d.feed_trips + " vehicles" : "unreachable") + '</b></div>';
  } catch (e) {
    document.getElementById("statBox").innerHTML =
      '<span class="note">Could not read the status.</span>';
  }
}
document.getElementById("cacheBtn").addEventListener("click", () => {
  const msg = document.getElementById("cacheMsg");
  msg.textContent = "Caching the whole network from ZET, this runs once…";
  fetch("rebuild?force=1", { method: "POST" }).catch(() => {});
  const poll = setInterval(async () => {
    let d = {};
    try { d = await fetch("status", { cache: "no-store" }).then(r => r.json()); } catch (e) { return; }
    loadStatus();
    if (d.ok) {
      clearInterval(poll);
      msg.textContent = "Cached " + (d.stops || "?") + " stations.";
      INDEX_OK = true; loadStops();
    }
  }, 3000);
});



/* =========================================================================
   GOOGLE STATION VIEW
   Google already draws every tram and bus stop, and draws them better than we
   would. In this view we add nothing to the map at all -- we just listen for a
   tap on one of its icons, work out which GTFS stop it is, and put a ring
   round it. The ring is hollow so the icon still shows through.
   ========================================================================= */
let SEL = null;          // the stop whose window is open
let selMk = null, lSel = null;   // the ring, one per engine
let popTimer = null;

function stationColour(id){
  if (COLOUR[id]) return COLOUR[id];
  let n = 0;
  for (let i = 0; i < String(id).length; i++) n = (n * 33 + String(id).charCodeAt(i)) >>> 0;
  return PALETTE[n % PALETTE.length];
}
function clearSel(){
  if (selMk) { try { selMk.setMap(null); } catch (e) {} selMk = null; }
  if (lSel) { try { map.removeLayer(lSel); } catch (e) {} lSel = null; }
}
function markSel(s){
  clearSel();
  if (!s) return;
  const c = stationColour(s.stop_id);
  const html = '<div class="selring" style="--c:' + c + '">' +
    '<i class="core"></i><i class="w1"></i><i class="w2"></i><i class="w3"></i></div>';
  if (usingGoogle()) {
    selMk = new HtmlMarker({ lat: s.lat, lng: s.lon }, html, null, 400);
    selMk.setMap(gmap);
  } else {
    lSel = L.marker([s.lat, s.lon], {
      icon: L.divIcon({ html, className: "starwrap", iconSize: [46, 46], iconAnchor: [23, 23] }),
      interactive: false, zIndexOffset: 400 }).addTo(map);
  }
}

/* A tap on one of Google's icons gives a place id and a point, never a GTFS
   id, so we ask our own index what is standing there. A tap on bare map is
   allowed too but has to be much closer, otherwise panning around would keep
   opening stations you did not mean. */
async function onMapClick(e){
  const onIcon = !!(e && e.placeId);
  if (onIcon && e.stop) e.stop();          // no Google info window, this is ours
  const ll = e && e.latLng;
  if (!ll) return;
  if (PINMODE) { pinAt(ll.lat(), ll.lng()); return; }
  if (MODE !== "google") return;
  const lat = ll.lat(), lng = ll.lng();
  const r = onIcon ? 120 : 40;
  const gen = ++SELGEN;
  try {
    const d = await fetch("stops?lat=" + lat + "&lon=" + lng + "&r=" + r + "&widen=0",
      { cache: "no-store" }).then(x => x.json());
    const st = (d.stops || [])[0];
    if (!st) { if (onIcon) hud("No ZET stop registered at that icon."); return; }
    openPop(st, gen);
  } catch (err) { hud("Could not reach the server: " + esc(err.message || err)); }
}

/* ---------------- the station's dashboard ---------------- */
async function openPop(stop, gen){
  // gen is the arming generation. If a later tap has happened while this was
  // in flight, everything below would draw the wrong station over the right
  // one, so it stops here instead.
  if (gen !== undefined && gen !== SELGEN) return;
  if (!stop) return;
  SEL = stop;
  // Opening a station IS watching it, as it has been since v39.
  if (!WATCH || WATCH.stop_id !== stop.stop_id) watchStation(stop);
  markSel(stop);
  document.getElementById("dash").classList.add("show");
  if (!DASH_HIST) { try { history.pushState({ dash: 1 }, ""); DASH_HIST = true; } catch (e) {} }
  renderDash();
  streetView(stop).then(() => { if (SEL === stop) renderDash(); });
  await refreshPop();
  if (gen !== undefined && gen !== SELGEN) return;
  if (SEL !== stop) return;
  hud("<b>" + esc(stop.stop_id) + "</b> " + esc(stop.name), false);
  if (popTimer) clearInterval(popTimer);
  popTimer = setInterval(refreshPop, 20000);
}
async function refreshPop(){
  const s = SEL;
  if (!s) return;
  let b = null;
  try {
    b = await fetch("board?stop=" + encodeURIComponent(s.stop_id) +
      "&mins=60&back=10", { cache: "no-store" }).then(r => r.json());
  } catch (e) { return; }
  if (!b || !b.ok) return;
  BOARDS[s.stop_id] = b;
  if (SEL === s) renderDash();
  updateWatchBar();
}
function closePop(fromBack){
  SEL = null;
  SELGEN++;                              // a fetch still in flight stays closed
  if (ARM_T) { clearTimeout(ARM_T); ARM_T = null; }
  document.getElementById("dash").classList.remove("show");
  document.querySelectorAll(".pin.armed").forEach(e => e.classList.remove("armed"));
  if (popTimer) { clearInterval(popTimer); popTimer = null; }
  clearSel();
  if (!fromBack && DASH_HIST) { DASH_HIST = false; try { history.back(); } catch (e) {} }
  hud(MODE === "google" ? "Tap any station Google draws to see what is coming." : stopsLine());
}

/* ---------------- the view switch ---------------- */
async function setMode(m, quiet){
  if (m === "google") {
    if (!API_KEY) {
      hud("Google station view needs a Google key. ⚙ → Load key from file.");
      paintMode(); return;
    }
    const ok = await setEngine("detail", true);
    if (!ok) { MODE = "stars"; LS.set("mode", MODE); paintMode(); return; }
    MODE = "google"; LS.set("mode", MODE);
    applyLayers(); drawStars(); paintMode();
    if (!quiet) hud("Tap any station Google draws to see what is coming.");
  } else {
    MODE = "stars"; LS.set("mode", MODE);
    closePop();
    applyLayers(); drawStars(); paintMode();
    if (!quiet) hud(stopsLine());
  }
}
function paintMode(){
  document.getElementById("viewStars").classList.toggle("on", MODE !== "google");
  document.getElementById("viewGoogle").classList.toggle("on", MODE === "google");
}
document.getElementById("viewStars").addEventListener("click", () => setMode("stars"));
document.getElementById("viewGoogle").addEventListener("click", () => setMode("google"));
document.getElementById("segStar").setAttribute("points", STAR_PTS);


/* ---------------- position readout, sharpening, and pinning ---------------- */
let PINMODE = false;
function updateAccBox(){
  const box = document.getElementById("posBox");
  if (!box) return;
  const dot = document.getElementById("posDot");
  if (!ME) {
    box.innerHTML = '<span class="note">No fix yet.</span>';
    dot.className = "dot"; return;
  }
  if (ME.pinned) {
    box.innerHTML = '<div class="kv"><span>Source</span><b>pinned by hand</b></div>' +
      '<div class="kv"><span>Position</span><b>' + ME.lat.toFixed(5) + ", " +
      ME.lng.toFixed(5) + '</b></div>' + providerRows();
    dot.className = "dot ok"; return;
  }
  const a = ME.acc || 0;
  const grade = a <= 8 ? "good" : (a <= 20 ? "usable" : "loose");
  box.innerHTML =
    '<div class="kv"><span>Accuracy</span><b>±' + Math.round(a) + " m · " + grade + '</b></div>' +
    '<div class="kv"><span>Fixes averaged</span><b>' + (ME.n || 1) + '</b></div>' +
    '<div class="kv"><span>Listening</span><b>' + (watchId !== null ? "yes" : "idle") + '</b></div>' +
    '<div class="kv"><span>Position</span><b>' + ME.lat.toFixed(5) + ", " + ME.lng.toFixed(5) + '</b></div>';
  dot.className = "dot " + (a <= 20 ? "ok" : "");
  box.innerHTML += providerRows();
}
document.getElementById("posProv").addEventListener("click", async () => {
  document.getElementById("posMsg").textContent = "Asking Android for a fresh fix from each provider…";
  await loadGps(true);
  document.getElementById("posMsg").textContent = GPSINFO && GPSINFO.termux
    ? "Android answered." : "Termux:API is not installed.";
});
document.getElementById("posSharpen").addEventListener("click", () => {
  document.getElementById("setup").classList.remove("show");
  sharpen();
});
document.getElementById("posPin").addEventListener("click", () => {
  if (ME && ME.pinned) {
    ME.pinned = false; FIXES = [];
    document.getElementById("posMsg").textContent = "Back to the satellites.";
    drawMe(); updateAccBox(); autoLocate(true);
    return;
  }
  PINMODE = true;
  document.getElementById("setup").classList.remove("show");
  hud("Tap the map where you actually are.");
});
function pinAt(lat, lng){
  PINMODE = false;
  stopBurst();
  ME = { lat: lat, lng: lng, acc: 0, n: 0, pinned: true };
  drawMe(); updateAccBox(); paintChip();
  const el = document.getElementById("posMsg");
  if (el) el.textContent = "Pinned. Tap the same button again to go back to the satellites.";
  hud("Pinned by hand. Nothing is guessing any more.");
  lastStopFetch = null;
  loadStops();
}


/* ---------------- the live fix readout ----------------
   Accuracy comes from the browser and is always there. Which provider answered
   comes from Android through Termux:API, because the Geolocation API simply
   does not carry that field. Satellite count is in neither: it lives in
   GnssStatus, a native API no web page and no Termux tool can reach, so the
   panel says so rather than showing an invented number. */
let GPSINFO = null, gpsPoll = null;

function accGrade(a){
  if (a == null) return "";
  return a <= 8 ? "good" : (a <= 20 ? "ok" : "weak");
}
function srcLabel(){
  if (ME && ME.pinned) return "pinned by hand";
  if (!GPSINFO || !GPSINFO.termux) {
    /* no Termux:API, so infer from the accuracy. A phone that says 8 m is on
       satellites; one that says 60 m is triangulating masts and wifi. */
    if (!ME) return "looking…";
    return ME.acc <= 20 ? "satellites (likely)" : "wifi / cell (likely)";
  }
  if (GPSINFO.better === "gps") return "satellites";
  if (GPSINFO.better === "network") return "wifi / cell";
  return "no provider answered";
}
function paintChip(){
  const chip = document.getElementById("gpsChip");
  const a = ME && !ME.pinned ? ME.acc : null;
  chip.className = (ME && ME.pinned ? "" : accGrade(a)) + (watchId !== null ? " live" : "");
  document.getElementById("gpsAcc").textContent =
    ME ? (ME.pinned ? "pinned" : "±" + Math.round(a) + " m") : "—";
  document.getElementById("gpsSrc").textContent = srcLabel();
}
document.getElementById("gpsChip").addEventListener("click", () => {
  document.getElementById("setup").classList.add("show");
  document.getElementById("rLbl").textContent = fmtDist(RADIUS);
  renderLayers(); loadStatus(); updateAccBox(); loadGps(true);
  document.getElementById("posBox").scrollIntoView({ block: "center", behavior: "smooth" });
});
document.getElementById("btnLocate").addEventListener("click", () => {
  const b = document.getElementById("btnLocate");
  if (ME && ME.pinned) {
    setView(ME, Math.max(17, curZoom()));
    hud("You are pinned by hand. Unpin in ⚙ to use the satellites again.");
    return;
  }
  b.classList.add("busy");
  // The button, and only the button, brings the map to you: now to the last
  // position, and again to the first fix of the new burst, which is where you
  // are. The flag lapses after the burst so a later automatic fix cannot use it.
  WANT_CENTRE = true;
  if (ME) setView(ME, Math.max(17, curZoom()));
  clearTimeout(window.__wantT); window.__wantT = setTimeout(() => { WANT_CENTRE = false; }, 35000);
  sharpen();
  setTimeout(() => b.classList.remove("busy"), 30000);
});

async function loadGps(fresh){
  try {
    GPSINFO = await fetch("gps" + (fresh ? "?fresh=1" : ""), { cache: "no-store" })
      .then(r => r.json());
  } catch (e) { GPSINFO = null; }
  paintChip(); updateAccBox();
}
function providerRows(){
  if (!GPSINFO) return '<div class="kv"><span>Provider</span><b>not read yet</b></div>';
  if (!GPSINFO.termux) return '<div class="kv"><span>Provider</span><b>' +
    esc(srcLabel()) + '</b></div>' +
    '<span class="note">Android will not tell a web page which provider answered. ' +
    'Install the <b>Termux:API</b> app and this becomes a straight answer instead ' +
    'of a guess from the accuracy figure.</span>';
  const one = (o, name) => {
    if (!o || !o.ok) return '<div class="kv"><span>' + name + '</span><b>' +
      esc((o && o.reason) || "no fix") + '</b></div>';
    const age = o.elapsedMs != null ? " · " + Math.round(o.elapsedMs / 1000) + " s old" : "";
    return '<div class="kv"><span>' + name + '</span><b>±' +
      (o.accuracy == null ? "?" : Math.round(o.accuracy)) + " m" + esc(age) + '</b></div>';
  };
  return one(GPSINFO.gps, "Satellites (GPS)") + one(GPSINFO.network, "Wifi / cell") +
    (GPSINFO.gap_m != null
      ? '<div class="kv"><span>They disagree by</span><b>' + GPSINFO.gap_m + ' m</b></div>'
      : "") +
    '<div class="kv"><span>Satellites in view</span><b>not available</b></div>';
}

/* ---------------- printed timetables ---------------- */
let GEM_OK = false;
function fmtAgo(ts){
  if (!ts) return "";
  const d = Math.floor((Date.now() / 1000 - ts) / 86400);
  return d <= 0 ? "today" : (d === 1 ? "yesterday" : d + " days ago");
}
async function loadSched(){
  let d = { items: [] };
  try { d = await fetch("sched-list", { cache: "no-store" }).then(r => r.json()); } catch (e) {}
  const items = d.items || [];
  const bad = items.filter(x => x.approx);
  document.getElementById("schedDot").className = "dot " + (items.length && !bad.length ? "ok" : "");
  document.getElementById("schedWarn").innerHTML = !GEM_OK
    ? '<div class="warnbox">No Gemini key, so the PDFs cannot be read properly. ' +
      'Anything stored without one is marked below and is never used on the board.</div>'
    : (bad.length
      ? '<div class="warnbox">' + bad.length + ' line' + (bad.length === 1 ? "" : "s") +
        ' stored before the key was added. Tap “Store the lines around me” to read ' +
        'them again properly.</div>'
      : "");
  document.getElementById("schedList").innerHTML = items.length
    ? items.map(x =>
        '<div class="srow"><span class="sr" style="--r:' + routeColour(x.route) + '">' +
        esc(x.route) + '</span><span class="sn">' +
        esc(x.name || (x.directions || []).filter(Boolean).join(" ⇄ ") || "line " + x.route) +
        '<i class="' + (x.approx ? "bad" : "") + '">' +
        (x.approx ? "unreadable without a key, not used"
                  : x.times + " times · " + (x.directions || []).length + " direction" +
                    ((x.directions || []).length === 1 ? "" : "s")) +
        " · stored " + fmtAgo(x.fetched) + '</i></span>' +
        '<button class="sx" data-sdel="' + esc(x.route) + '">✕</button></div>').join("")
    : '<span class="note">Nothing stored yet.</span>';
}
document.getElementById("schedList").addEventListener("click", async (e) => {
  const b = e.target.closest("[data-sdel]");
  if (!b) return;
  await fetch("sched-delete?route=" + encodeURIComponent(b.dataset.sdel), { method: "POST" }).catch(() => {});
  loadSched();
});
document.getElementById("schedAll").addEventListener("click", async () => {
  await fetch("sched-delete?all=1", { method: "POST" }).catch(() => {});
  document.getElementById("schedMsg").textContent = "Cleared.";
  loadSched();
});
document.getElementById("schedNear").addEventListener("click", async () => {
  const msg = document.getElementById("schedMsg");
  const at = anchor();
  msg.textContent = "Reading the official timetables from ZET. One PDF per line, " +
    "then each one is thrown away…";
  try {
    const d = await fetch("sched-near?lat=" + at.lat + "&lon=" + at.lng +
      "&r=" + Math.max(RADIUS, 400) + "&force=1", { cache: "no-store" })
      .then(r => r.json());
    if (!d.ok) { msg.textContent = "Could not do it: " + esc(d.reason || "no reason given"); return; }
    const got = Object.values(d.routes || {});
    const good = got.filter(x => x.ok && !x.approx).length;
    const failed = got.filter(x => !x.ok).length;
    msg.textContent = good + " of " + got.length + " line" + (got.length === 1 ? "" : "s") +
      " stored properly" + (failed ? ", " + failed + " had no PDF published" : "") + ".";
  } catch (e) {
    msg.textContent = "Could not reach ZET: " + esc(e.message || e);
  }
  loadSched();
});
document.getElementById("gemFile").addEventListener("change", async (e) => {
  const msg = document.getElementById("gemMsg");
  const f = e.target.files && e.target.files[0]; if (!f) return;
  const text = (await f.text()).trim(); e.target.value = "";
  if (!text) { msg.textContent = "Empty file."; return; }
  msg.textContent = "Saving…";
  try {
    const d = await fetch("gemini-key", { method: "POST", body: text }).then(r => r.json());
    if (d.ok) { msg.textContent = "Saved."; GEM_OK = true;
                document.getElementById("gemDot").className = "dot ok"; loadSched(); }
    else msg.textContent = "Could not save the key.";
  } catch (err) { msg.textContent = "Could not save the key."; }
});
async function loadGemStatus(){
  try {
    const d = await fetch("gemini-key", { cache: "no-store" }).then(r => r.json());
    GEM_OK = !!d.set;
  } catch (e) { GEM_OK = false; }
  document.getElementById("gemDot").className = "dot " + (GEM_OK ? "ok" : "");
}


/* ---------------- key manager ----------------
   Three questions a key can answer: does it work, what can it call, and which
   of those should read the timetable PDFs. The choice is stored on the server,
   not here, because the PDFs are parsed server-side with no browser involved. */
function say(id, text, cls){
  const el = document.getElementById(id);
  el.className = "msg" + (cls ? " " + cls : "");
  el.innerHTML = text;
}
function fmtWhen(ts){
  if (!ts) return "never checked";
  const m = Math.floor((Date.now() / 1000 - ts) / 60);
  if (m < 1) return "just now";
  if (m < 60) return m + " min ago";
  const hrs = Math.floor(m / 60);
  return hrs < 24 ? hrs + " h ago" : Math.floor(hrs / 24) + " d ago";
}
function fillPicker(models, chosen, checked){
  const sel = document.getElementById("gemPick");
  sel.innerHTML = '<option value="">Automatic (' + esc(GEM_DEFAULT) + ')</option>' +
    (models || []).map(m =>
      '<option value="' + esc(m) + '"' + (m === chosen ? " selected" : "") + '>' +
      esc(m) + '</option>').join("");
  if (chosen && !(models || []).includes(chosen))
    sel.insertAdjacentHTML("beforeend",
      '<option value="' + esc(chosen) + '" selected>' + esc(chosen) + '</option>');
  sel.disabled = !GEM_OK;
  say("gemPickMsg", (models || []).length
    ? (models.length + " models this key can call · list " + fmtWhen(checked))
    : (GEM_OK ? "Tap “Check available models” to see what this key can call."
              : "Load a key first."));
}
let GEM_DEFAULT = "gemini-2.5-flash";
async function loadModelState(){
  try {
    const d = await fetch("gemini-model", { cache: "no-store" }).then(r => r.json());
    GEM_DEFAULT = d.default || GEM_DEFAULT;
    fillPicker(d.models, d.model, d.checked);
  } catch (e) { fillPicker([], "", 0); }
}
document.getElementById("gemPick").addEventListener("change", async (e) => {
  const v = e.target.value;
  say("gemPickMsg", "Saving…", "busy");
  try {
    const d = await fetch("gemini-model", { method: "POST", body: v }).then(r => r.json());
    if (d.ok) say("gemPickMsg", v ? "Timetable PDFs will be read by " + esc(v) + "."
                                  : "Back to automatic.", "good");
    else { say("gemPickMsg", esc(d.reason || "Could not save that."), "bad"); loadModelState(); }
  } catch (err) { say("gemPickMsg", "Could not save that.", "bad"); }
});
document.getElementById("gemRefresh").addEventListener("click", async () => {
  say("gemMsg", "Asking Google what this key can call…", "busy");
  try {
    const d = await fetch("gemini-models?force=1", { cache: "no-store" }).then(r => r.json());
    if (!d.ok) { say("gemMsg", esc(d.reason || "Could not read the list."), "bad"); return; }
    say("gemMsg", d.models.length + " models available to this key.", "good");
    loadModelState();
  } catch (e) { say("gemMsg", "Could not reach Google.", "bad"); }
});
document.getElementById("gemTest").addEventListener("click", async () => {
  say("gemMsg", "Asking the model a one-word question…", "busy");
  try {
    const d = await fetch("gemini-test", { cache: "no-store" }).then(r => r.json());
    if (d.ok) {
      GEM_OK = true;
      document.getElementById("gemDot").className = "dot ok";
      say("gemMsg", "Working — " + esc(d.model) + " answered in " + d.ms + " ms.", "good");
      loadSched();
    } else say("gemMsg", esc(d.reason || "No answer."), "bad");
  } catch (e) { say("gemMsg", "Could not reach Google.", "bad"); }
});
document.getElementById("keyTest").addEventListener("click", async () => {
  say("keyMsg", "Testing Street View and the Maps library…", "busy");
  let sv = null, maps = null, why = "";
  try {
    const d = await fetch("key-test", { cache: "no-store" }).then(r => r.json());
    sv = !!d.ok; if (!d.ok) why = d.reason || d.status || "";
  } catch (e) { sv = false; why = "could not reach Google"; }
  try { gPromise = null; await loadGoogle(); maps = true; }
  catch (e) { maps = false; if (!why) why = e.message || ""; }
  const line = (sv ? "✓" : "✕") + " Street View Static &nbsp; " +
               (maps ? "✓" : "✕") + " Maps JavaScript";
  say("keyMsg", line + (sv && maps ? "" : "<br>" + esc(why)),
      sv && maps ? "good" : "bad");
  document.getElementById("keyDot").className = "dot " + (sv || maps ? "ok" : "");
});

/* ---------------- the index has to exist before anything works ---------------- */
async function watchIndex(){
  try {
    const d = await fetch("status", { cache: "no-store" }).then(r => r.json());
    // The stations are permanent (stations.json), so they are drawn at once
    // even while the schedule is being rebuilt behind them.
    if (d.ok || d.stations) { INDEX_OK = true; if (!STOPS.length) loadStops(); }
    if (d.ok) {
      if (indexTimer) { clearInterval(indexTimer); indexTimer = null; }
      return;
    }
    if (!d.stations) hud("Building the station index. This runs once a day…", true);
    if (!indexTimer) indexTimer = setInterval(watchIndex, 4000);
  } catch (e) { /* leave the status line alone */ }
}

/* ---------------- boot ---------------- */
(async function(){
  try {
    const d = await fetch("api-keys", { cache: "no-store" }).then(r => r.json());
    API_KEY = (d.keys || [])[0] || "";
  } catch (e) { API_KEY = ""; }
  setDot(!!API_KEY);
  initFreeMap();
  applyLayers();
  if (FIXES.length) applyFix(true);     // a fix that beat the map here
  if (WATCH) {
    document.body.classList.add("watching");
    document.getElementById("wbName").textContent = WATCH.name;
  }
  if (MODE === "google" && !API_KEY) MODE = "stars";
  if ((ENGINE === "detail" || MODE === "google") && API_KEY) {
    ENGINE = "free";
    await setEngine("detail", true);
  } else { ENGINE = "free"; MODE = "stars"; }
  paintMode();
  await watchIndex();
  autoLocate(true);
  loadGps(false);
  if (!gpsPoll) gpsPoll = setInterval(() => { if (!document.hidden) paintChip(); }, 3000);
  fetch("version").then(r => r.json())
    .then(v => { document.getElementById("verLine").textContent = v.version + " · " + v.build; })
    .catch(() => { document.getElementById("verLine").textContent = "—"; });
})();

/* the foreground is the trigger. coming back to the app re-finds you. */
document.addEventListener("visibilitychange", () => {
  if (document.hidden) stopBurst(); else autoLocate();
});
window.addEventListener("focus", () => autoLocate());
window.addEventListener("pageshow", () => autoLocate());
setInterval(() => { if (!document.hidden) autoLocate(); }, 90000);
if (WATCH && !boardTimer) boardTimer = setInterval(refreshBoards, 20000);
window.addEventListener("resize", () => {
  if (map && !usingGoogle()) setTimeout(() => map.invalidateSize(), 90);
});
</script>
</body>
</html>
ALLC_STAR_HTML
done_

step "installing the all.commute command"
cat > "$BIN/all.commute" << 'ALLC_LAUNCH'
#!/data/data/com.termux/files/usr/bin/bash
# all.commute — what is coming to the stop I am standing at, anywhere on ZET.
#   all.commute          start in the foreground and open the app
#   all.commute stop     stop a running server
#   all.commute status   running? on which port?
#   all.commute update   rebuild the station index now

APPDIR="$HOME/.all.commute"
SERVER="$APPDIR/all_commute_server.py"
PORTFILE="$APPDIR/port"
mkdir -p "$APPDIR"

if [ -t 1 ]; then
  OK="\033[1;32m"; WARN="\033[1;33m"; KEY="\033[1;37m"; DIM="\033[0;90m"; OFF="\033[0m"
else
  OK=""; WARN=""; KEY=""; DIM=""; OFF=""
fi

case "$1" in
  stop)
    if pkill -f all_commute_server.py 2>/dev/null; then
      printf "  ${OK}all.commute stopped${OFF}\n"
    else
      printf "  ${DIM}not running${OFF}\n"
    fi
    rm -f "$PORTFILE"; exit 0 ;;
  status)
    if pgrep -f all_commute_server.py >/dev/null 2>&1; then
      printf "  ${OK}running${OFF} on ${KEY}http://127.0.0.1:%s${OFF}\n" "$(cat "$PORTFILE" 2>/dev/null)"
    else
      printf "  ${DIM}stopped${OFF}\n"
    fi
    exit 0 ;;
  update)
    ALLC_DIR="$APPDIR" ALLC_FORCE=1 python "$APPDIR/update_all.py"; exit 0 ;;
esac

[ -f "$SERVER" ] || { printf "  ${WARN}server missing; run the installer again${OFF}\n"; exit 1; }

if [ -f "$HOME/.ma/banner.sh" ]; then
  . "$HOME/.ma/banner.sh"
  [ -z "$MA_NESTED" ] && ma_name "ALL.COMMUTE" "$MA_WATER" "Water | every stop"
else
  printf "\n  ${KEY}\xe0\xa5\x90 ALL.COMMUTE \xe0\xa5\x90${OFF}\n  ${DIM}Water | every stop${OFF}\n\n"
fi

# never let an older instance keep the port; the newest one must win
for sig in TERM TERM KILL; do
  pkill -$sig -f all_commute_server.py >/dev/null 2>&1 || true
  sleep 0.2
done
if command -v fuser >/dev/null 2>&1; then
  for port in $(seq 8084 8123); do fuser -k -n tcp "$port" >/dev/null 2>&1 || true; done
fi
rm -f "$PORTFILE"
exec python "$SERVER"
ALLC_LAUNCH
chmod +x "$BIN/all.commute"
done_

step "Termux:Widget desktop shortcut"
mkdir -p "$HOME/.shortcuts" "$HOME/.shortcuts/icons"
cat > "$HOME/.shortcuts/all.commute" << 'SHORTCUT'
#!/data/data/com.termux/files/usr/bin/bash
# Tap-to-start shortcut for Termux:Widget. Launches all.commute and opens the app.
export PATH="$PREFIX/bin:$PATH"
exec all.commute
SHORTCUT
sed -i 's/\r$//' "$HOME/.shortcuts/all.commute"
chmod +x "$HOME/.shortcuts/all.commute"
if command -v base64 >/dev/null 2>&1; then
  base64 -d > "$HOME/.shortcuts/icons/all.commute.png" << 'ICONB64'

ICONB64
fi
done_
if [ "$MODE" = "online" ]; then
  step "refreshing the station cache"
  printf "\n"
  ALLC_DIR="$APPDIR" ALLC_FORCE=1 python "$APPDIR/update_all.py" || \
    printf "  ${WARN}the cache refresh failed; the app will try again on its own${OFF}\n"
  step "refreshing the station cache"; done_
else
  step "station cache"; skip_
fi

printf "\n  ${OK}installed the star interface %s${OFF}  type ${KEY}all.commute${OFF} to start it\n" "$ALLC_UI_VERSION"
printf "  ${DIM}open it, let it find you, tap a station${OFF}\n"
printf "  ${DIM}in settings: load a Gemini key, then Store the lines around me${OFF}\n"
printf "  ${DIM}on the Google key: Street View Static API draws the photograph,${OFF}\n"
printf "  ${DIM}Maps JavaScript API draws the 360 view and the detailed map layers${OFF}\n"
printf "  ${DIM}to go back: cp ~/.all.commute/NAME.prev.bak ~/.all.commute/NAME${OFF}\n"
printf "  ${DIM}            for NAME = all.html and all_commute_server.py${OFF}\n\n"
MAHA_PAY_all_7c1a
      ;;
  esac
}

maha_emit_menu() {
  cat <<'MAHA_MENU_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# maha-commute, the launcher. Written by the installer.
#
# Midnight Commander, and the debt is deliberate. What is lifted is not the
# look, it is the way mc lets a pair of panels share one set of keys.
#
# FOUR QUADRANTS, one app each. A quadrant is empty when its app is not
# running and empty when there is no app for it at all: the fourth is free
# and stays drawn, because a slot that appears when a fourth app arrives is
# a screen that moves under the hand. Nothing appears, nothing disappears.
#
#   +-----------------+-----------------+
#   | 1 day.commute   | 2 night.commute |
#   +-----------------+-----------------+
#   | 3 all.commute   | 4 free          |
#   +-----------------+-----------------+
#
# 1 2 3 4 LIGHT a quadrant. An idle app is started by its number and the
# quadrant says RUNNING; an app that is already running is only lit, so with
# two apps up the numbers just swap the light between them. Enter or o opens
# the page. 0 lights nothing: it is the launcher itself, and the keys that
# belong to no single app act on all of it.
#
# u UPDATES according to what is running. With nothing running it updates the
# whole launcher. With apps running it updates only the lit one, because an
# update replaces files that a running server is serving from.
#
# The label is drawn whether the quadrant is filled or not, so the number
# never has to be looked up. 1 is always day.commute, on this phone and on
# every other one.
#
# THE VERBS ARE THE SAME FOR EVERY QUADRANT and they act on the focused one.
# That is the whole point: one set of keys, learned once, and the only thing
# that changes is which app is listening.
#
#   Enter  open it, starting it first if it is not running
#   o      open the page again, for when the tab was closed
#   s      stop it
#   R      restart it
#   l      its log, the last twenty lines in its own words
#   i      install it, or remove it if it is here
#
# SERVERS STACK. Starting one does not take the terminal and does not stop
# another. All three can run at once: they hold 8082, 8087 and 8084.
#
# The bottom row is the things that belong to no single app, and it is
# always the same ten slots in the same order, dim when they do not apply.

. "$HOME/.maha.commute/env.sh" 2>/dev/null || {
  printf 'maha-commute: ~/.maha.commute/env.sh is missing.\n'
  printf 'Run the installer again.\n'; exit 1; }

if [ -t 1 ]; then
  AM="\033[38;5;214m"; SAND="\033[38;5;223m"; OK="\033[1;32m"
  BAD="\033[1;31m"; KEY="\033[1;37m"; DIM="\033[0;90m"
  BAR="\033[48;5;24m\033[1;37m"; OFF="\033[0m"
else
  AM=""; SAND=""; OK=""; BAD=""; KEY=""; DIM=""; BAR=""; OFF=""
fi

RUNDIR="$APPHOME/running"; mkdir -p "$RUNDIR"
# One id per launcher session. The page compares it with the one it stored
# and clears what you picked when they differ, which is what makes a new
# run start clean instead of where you left off.
RUN=$(date +%s)
PY="$(command -v python3 || command -v python)"
SEL=0     # 0 is the launcher itself; 1 to 4 light an app
LAST=""

STTY_SAVED=""
restore_tty() { [ -n "$STTY_SAVED" ] && stty "$STTY_SAVED" 2>/dev/null || true; }
trap 'restore_tty' EXIT INT TERM HUP
STTY_SAVED=$(stty -g 2>/dev/null || true)

field()   { printf '%s' "$1" | cut -d'|' -f"$2"; }
app_row() { printf '%s\n' "$MAHA_APPS" | grep "^$1|" || true; }
app_ids() { printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1; }
app_at()  { case "$1" in ''|0|*[!0-9]*) return 0 ;; esac; app_ids | sed -n "${1}p"; }
n_apps()  { app_ids | wc -l | tr -d ' '; }

# Installed means the command AND the app's own files (field test v21, F4): a
# command whose folder was deleted is a broken install, not an installed app.
app_files_present() {
  local row dir proc
  row=$(app_row "$1"); dir=$(field "$row" 3); proc=$(field "$row" 7)
  [ -n "$dir" ] && [ -f "$HOME/$dir/$(basename "$proc")" ]
}
is_installed() { local c; c=$(field "$(app_row "$1")" 2); [ -n "$c" ] && [ -x "$BIN/$c" ] && app_files_present "$1"; }
stamped()      { if [ -f "$STAMPDIR/$1" ]; then tr -d ' \n' < "$STAMPDIR/$1"; else printf '?'; fi; }

# The app's OWN launcher. Since v17 the command on the PATH (day.commute and
# the others) is a small shim that opens this screen with that app focused, and
# the app's real launcher is kept in orig/. This screen always talks to the
# real one and never to the shim, so nothing here can call itself, and the
# stop verb it looks for is the app's own.
launcher_of() {
  local c; c=$(field "$(app_row "$1")" 2)
  if [ -x "$APPHOME/orig/$c" ]; then printf '%s' "$APPHOME/orig/$c"; else printf '%s' "$BIN/$c"; fi
}
# A plain connect in a subshell, which is what v1 shipped and what Test 1
# exercises. The "hardened" version wrapped this in `timeout 1 bash -c` and
# that is what hung the panel: the wrapper child inherits the terminal, and
# killing the wrapper does not always close what it left open. A deadline
# that introduces a process is not a deadline, it is another thing to wait
# for. Connect only, never read, so there is nothing to wait on.
port_live() {
  (exec 3<>"/dev/tcp/127.0.0.1/$1") 2>/dev/null && exec 3<&- && return 0
  return 1
}

# The process first, the socket second, because asking the process table is
# local and cannot block on anything. pgrep is not everywhere, so ps is the
# fallback rather than an assumption: without this the socket probe is on
# the hot path of every redraw.
proc_alive() {
  if command -v pgrep >/dev/null 2>&1; then
    pgrep -f "$1" >/dev/null 2>&1
  else
    ps -eo args 2>/dev/null | grep -v grep | grep -qF "$1"
  fi
}

# The port an app actually bound, which is not always the one it wanted:
# each of the three walks forward when its first choice is busy. The file
# the server writes is the truth; the table is only the fallback.
app_port() {
  local row dir p
  row=$(app_row "$1"); dir="$HOME/$(field "$row" 3)"
  # The file is tested before it is read. A redirection from a file that is
  # not there is bash's error to print, not the command's to swallow, so
  # 2>/dev/null on the read does not stop it landing in the middle of the
  # frame. Checking first is the only thing that does.
  p=""
  [ -f "$dir/port" ] && p=$(tr -d ' \n' < "$dir/port" 2>/dev/null)
  if [ -n "$p" ]; then printf '%s' "$p"; else field "$row" 5; fi
}

# Up means two things at once: its own process is alive, AND the port that
# process wrote down answers. Either alone lied. The process alone counted an
# app as up before it had bound anything, and the menu then opened the
# table's port rather than the one it took. The port alone counted whatever
# else was sitting on 8082 as day.commute. (v20: and the day server is found
# by its path, because "commute_server.py" is also inside all.commute's name.)
running() {
  local row proc dir p=""
  row=$(app_row "$1"); proc=$(field "$row" 7); dir="$HOME/$(field "$row" 3)"
  proc_alive "$proc" || return 1
  [ -f "$dir/port" ] && p=$(tr -d ' \n' < "$dir/port" 2>/dev/null)
  [ -n "$p" ] && port_live "$p"
}

# am first, and its OUTPUT read rather than its exit code, because asking
# for a package that is not installed prints an error and still exits zero.
open_url() {
  local url="$1" out pkg
  for pkg in com.android.chrome com.chrome.beta com.chrome.dev; do
    out=$(am start -a android.intent.action.VIEW -d "$url" -p "$pkg" 2>&1)
    case "$out" in
      *rror*|*xception*|*"not found"*|*"unable to resolve"*) : ;;
      *) return 0 ;;
    esac
  done
  command -v termux-open-url >/dev/null 2>&1 && { termux-open-url "$url"; return 0; }
  command -v xdg-open >/dev/null 2>&1 && { xdg-open "$url" >/dev/null 2>&1; return 0; }
  command -v open >/dev/null 2>&1 && { open "$url" >/dev/null 2>&1; return 0; }
  printf "  %s\n" "$url"
}

anykey() {
  printf "\n  ${DIM}%s${OFF} " "${1:-any key}"
  read -rsn1 _x 2>/dev/null || read -r _x
  printf "\n"
}

offer_install() {
  local id="$1" cmd a; cmd=$(field "$(app_row "$id")" 2)
  printf "\n  ${SAND}%s is not installed.${OFF}\n" "$cmd"
  printf "  ${DIM}its payload is already here, so this needs no download${OFF}\n"
  printf "\n  ${KEY}Enter${OFF} ${DIM}install${OFF}   ${KEY}n${OFF} ${DIM}leave it${OFF}\n\n  ${AM}>${OFF} "
  IFS= read -r a || a="n"
  case "$a" in [nN]*) return 0 ;; esac
  bash "$APPHOME/install-one.sh" "$id" --offline || true
  anykey
}

start_app() {
  local id="$1" cmd port i last shown=""
  cmd=$(field "$(app_row "$id")" 2)
  if ! is_installed "$id"; then offer_install "$id"; return; fi
  if running "$id"; then LAST="$id"; open_url "http://127.0.0.1:$(app_port "$id")/?run=$RUN"; return; fi

  printf "\n  ${DIM}starting %s${OFF}\n" "$cmd"

  # setsid and </dev/null. The app gets its own session and no terminal, so
  # it cannot compete with this menu for a keypress and it does not die when
  # the menu is quit. Inheriting the terminal is how a backgrounded server
  # ends up eating the key you pressed for something else.
  #
  # FIELD TEST v21, F5. This used to be `( cd "$HOME" && setsid nohup X ... & echo $! )`,
  # and the `&` belongs to the WHOLE `cd && setsid ...` list: it ran in a forked
  # copy of this script that stayed alive as the server's parent, holding the
  # caller's stdout. `maha-commute day | cat` (a script, a widget, Termux:Boot)
  # never returned, 94 seconds here, 25 minutes on the phone. Now the subshell
  # that backgrounds the server is a single exec: nothing of this script is left
  # behind and nothing holds the caller's terminal or pipe.
  L=$(launcher_of "$id")
  if command -v setsid >/dev/null 2>&1; then
    ( cd "$HOME" 2>/dev/null; exec setsid nohup "$L" </dev/null >"$RUNDIR/$id.log" 2>&1 ) &
  else
    ( cd "$HOME" 2>/dev/null; exec nohup "$L" </dev/null >"$RUNDIR/$id.log" 2>&1 ) &
  fi
  echo $! > "$RUNDIR/$id.pid"
  disown 2>/dev/null || true

  # A FIRST start is not a restart. day.commute fetches an eleven megabyte
  # schedule from ZET and builds its caches before it binds anything, which
  # on a phone on mobile data is minutes. The old wait here was sixteen
  # seconds, so it announced failure while the app was still working, and
  # the app opened its own browser tab in the meantime. That is the whole
  # bug: a tab with nothing behind it yet, and a menu saying it did not
  # come up.
  #
  # So the wait is long, it says how long it has been, it shows the app's
  # own last line, and a keypress leaves it running rather than killing it.
  printf "  ${DIM}first start builds the schedule, this can take minutes${OFF}\n"
  printf "  ${DIM}any key to leave it working and go back${OFF}\n\n"
  for i in $(seq 1 450); do
    running "$id" && break
    if [ $((i % 5)) = 0 ]; then
      last=$(tail -1 "$RUNDIR/$id.log" 2>/dev/null | tr -d '\r' | sed 's/\x1b\[[0-9;]*[A-Za-z]//g' | cut -c1-40)
      [ -n "$last" ] && [ "$last" != "$shown" ] && { printf "  ${DIM}%s${OFF}\n" "$last"; shown="$last"; }
      printf "\r  ${AM}%ss${OFF}${DIM} waiting for port %s${OFF}   " "$((i * 2 / 5))" "$(app_port "$id")"
    fi
    # A key means stop waiting, not stop the app. Without a terminal (a script,
    # a widget, Termux:Boot) `read -t` returns at once, which turned the three
    # minute wait into a few seconds (field test v21, F10), so it sleeps instead.
    if [ -t 0 ]; then
      if read -rsn1 -t 0.4 _k 2>/dev/null; then
        printf "\n\n  ${SAND}left working in the background.${OFF}\n"
        printf "  ${DIM}the quadrant fills when it answers${OFF}\n"
        sleep 1; return
      fi
    else
      sleep 0.4
    fi
  done
  printf "\r                                                  \r"

  if running "$id"; then
    port=$(app_port "$id"); LAST="$id"
    printf "  ${OK}up${OFF} ${DIM}on %s${OFF}\n" "$port"
    open_url "http://127.0.0.1:$port/?run=$RUN"
    sleep 1
  else
    printf "  ${BAD}%s has not answered in three minutes${OFF}\n" "$cmd"
    printf "  ${DIM}it may still be working. Its own words:${OFF}\n\n"
    tail -6 "$RUNDIR/$id.log" 2>/dev/null | sed 's/^/    /'
    printf "\n  ${DIM}%s${OFF}\n" "$RUNDIR/$id.log"
    anykey
  fi
}

stop_app() {
  local id="$1" cmd proc
  cmd=$(field "$(app_row "$id")" 2); proc=$(field "$(app_row "$id")" 7)
  # alive but not answering is still something to stop
  if ! running "$id" && ! proc_alive "$proc"; then printf "  ${DIM}%s is not running${OFF}\n" "$cmd"; return; fi
  # Its own launcher first where it has a stop verb, because it knows what
  # else it started. Then the process name, for the ones that do not.
  local L; L=$(launcher_of "$id")
  grep -q '^  stop)' "$L" 2>/dev/null && "$L" stop >/dev/null 2>&1
  pkill -f "$proc" 2>/dev/null
  [ -f "$RUNDIR/$id.pid" ] && kill "$(cat "$RUNDIR/$id.pid")" 2>/dev/null
  rm -f "$RUNDIR/$id.pid"
  sleep 1
  if proc_alive "$proc"; then
    printf "  ${BAD}%s would not stop${OFF}\n" "$cmd"
  else
    printf "  ${OK}%s stopped${OFF}\n" "$cmd"
    [ "$LAST" = "$id" ] && LAST=""
  fi
}

stop_all() {
  printf "\n"
  local id any=0
  for id in $(app_ids); do running "$id" && { stop_app "$id"; any=1; }; done
  [ "$any" = 0 ] && printf "  ${DIM}nothing was running${OFF}\n"
  anykey
}

# ---------------------------------------------------------------
# the grid
#
# Four quadrants, two by two, one app each. A quadrant that holds no app
# is drawn empty rather than left out, because the grid is the map: the
# fourth is where the next app goes, and its frame being there already is
# what makes that true rather than a plan.
#
# 1 2 3 4 move the focus. The focused quadrant is lit and EVERY command
# below acts on it. The commands do not change from one app to the next,
# on purpose: the same key does the same thing whichever quadrant is lit,
# so the fingers learn it once. That is worth more than giving each app
# its own clever key.
#
# Colour is padded AFTER the string is sized. printf counts an escape
# sequence as characters, so colouring first and padding second makes
# every coloured cell nine columns narrower than its neighbour, and the
# frame stops being a frame.
# ---------------------------------------------------------------
CW=22

# u. What it updates depends on what is running, because an update replaces
# files a running server is serving from.
#   nothing running   the whole launcher, every installed app
#   something running only the lit app (its server is stopped first by the
#                     installer, nothing else is touched). With no app lit
#                     there is nothing to aim at, and it says so.
update_focus() {
  local n_run=0 id sel_id
  for id in $(app_ids); do running "$id" && n_run=$((n_run+1)); done
  printf "\n"
  if [ "$n_run" = 0 ]; then
    bash "$APPHOME/update.sh"; anykey; return
  fi
  sel_id=$(app_at "$SEL")
  if [ "$SEL" = 0 ] || [ -z "$sel_id" ]; then
    printf "  ${SAND}%s running.${OFF} ${DIM}Light one with 1 to 4 and press u to update just that app,${OFF}\n" "$n_run"
    printf "  ${DIM}or press S to stop them all and update the whole launcher.${OFF}\n"
    anykey; return
  fi
  if ! is_installed "$sel_id"; then
    printf "  ${DIM}%s is not installed, so there is nothing to update.${OFF}\n" "$(field "$(app_row "$sel_id")" 2)"
    anykey; return
  fi
  bash "$APPHOME/update.sh" --app "$sel_id"; anykey
}

pad() { printf '%-*.*s' "$CW" "$CW" "$1"; }

cell_lines() {
  # Three lines for one quadrant, plain text, into L1 L2 L3.
  local n="$1" id row cmd ver
  id=$(app_at "$n")
  if [ -z "$id" ]; then
    L1=" $n  free"; L2="   for the next app"; L3=""; CQ="dim"; return
  fi
  row=$(app_row "$id"); cmd=$(field "$row" 2)
  if ! is_installed "$id"; then
    L1=" $n $cmd"; L2="   not installed"; L3="   i puts it here"; CQ="dim"
  elif running "$id"; then
    ver=$(stamped "$id")
    L1=" $n $cmd"
    L2="   running  $(app_port "$id")"
    if [ "$LAST" = "$id" ]; then L3="   $ver  last opened"; else L3="   $ver"; fi
    CQ="ok"
  else
    L1=" $n $cmd"; L2="   ready"; L3="   $(stamped "$id")"; CQ="sand"
  fi
}

paint() {
  case "$1" in
    ok)   printf '%b%s%b' "$OK" "$2" "$OFF" ;;
    sand) printf '%b%s%b' "$SAND" "$2" "$OFF" ;;
    dim)  printf '%b%s%b' "$DIM" "$2" "$OFF" ;;
    bar)  printf '%b%s%b' "$BAR" "$2" "$OFF" ;;
    *)    printf '%s' "$2" ;;
  esac
}

row_pair() {
  # Two quadrants side by side. Left is $1, right is $2.
  local a="$1" b="$2" al1 al2 al3 ac bl1 bl2 bl3 bc
  cell_lines "$a"; al1=$(pad "$L1"); al2=$(pad "$L2"); al3=$(pad "$L3"); ac="$CQ"
  cell_lines "$b"; bl1=$(pad "$L1"); bl2=$(pad "$L2"); bl3=$(pad "$L3"); bc="$CQ"
  local at="$ac" bt="$bc"
  [ "$FOCUS" = "$a" ] && at="bar"
  [ "$FOCUS" = "$b" ] && bt="bar"
  printf "  ${AM}|${OFF}%s${AM}|${OFF}%s${AM}|${OFF}\n" "$(paint "$at" "$al1")" "$(paint "$bt" "$bl1")"
  printf "  ${AM}|${OFF}%s${AM}|${OFF}%s${AM}|${OFF}\n" "$(paint "$ac" "$al2")" "$(paint "$bc" "$bl2")"
  printf "  ${AM}|${OFF}%s${AM}|${OFF}%s${AM}|${OFF}\n" "$(paint "$ac" "$al3")" "$(paint "$bc" "$bl3")"
}

rule() { printf "  ${AM}+----------------------+----------------------+${OFF}\n"; }

fkey() {
  if [ "$4" = 1 ]; then
    printf "${DIM}%s${OFF}${KEY}%s${OFF}${SAND}%-7s${OFF}" "$1" "$2" "$3"
  else
    printf "${DIM}%s%s%-7s${OFF}" "$1" "$2" "$3"
  fi
}

W=21   # inner width of one quadrant, so two of them plus the rules fit a
       # phone terminal at about fifty columns. Measured, not guessed.

# Padding is done on the PLAIN text and the colour wrapped around it
# afterwards. printf counts the bytes of an escape sequence as width, so a
# coloured string handed to %-21s comes out short by exactly the length of
# the escapes, and every rule on the right hand side walks left.
PW=$W
pad() { printf "%-${PW}.${PW}s" "$1"; }

uptime_of() {
  local id="$1" pidf="$RUNDIR/$1.pid" s
  [ -f "$pidf" ] || { printf ''; return; }
  s=$(( $(date +%s) - $(date -r "$pidf" +%s 2>/dev/null || date +%s) ))
  if   [ "$s" -lt 60 ];   then printf '%ds' "$s"
  elif [ "$s" -lt 3600 ]; then printf '%dm' "$((s/60))"
  else printf '%dh' "$((s/3600))"; fi
}

# One quadrant's three lines, as plain text, into q1 q2 q3.
cell() {
  local slot="$1" id cmd
  id=$(app_at "$slot")
  if [ -z "$id" ]; then
    q1=$(printf '%d free' "$slot"); q2=''; q3='room for a fourth'
    qstate='empty'; return
  fi
  cmd=$(field "$(app_row "$id")" 2)
  # the version rides on the first line; the third line is what the app is for
  q3=$(field "$(app_row "$id")" 8)
  if ! is_installed "$id"; then
    q1=$(printf '%d %s' "$slot" "$cmd")
    q2='not installed'; qstate='absent'
  elif running "$id"; then
    q1=$(printf '%d %s %s' "$slot" "$cmd" "$(stamped "$id")")
    q2=$(printf 'RUNNING %s  %s' "$(app_port "$id")" "$(uptime_of "$id")")
    [ "$LAST" = "$id" ] && q2="$q2 *"
    qstate='running'
  else
    q1=$(printf '%d %s %s' "$slot" "$cmd" "$(stamped "$id")")
    q2='ready'
    qstate='ready'
  fi
}

# A quadrant is drawn by its state and by whether it has the focus. Colour
# carries the state and nothing else: green is running, sand is installed
# and idle, grey is not here. The focus is a bar, which is a different
# channel, so the two can be read at once.
paint() {
  local text="$1" state="$2" focused="$3"
  if [ "$focused" = 1 ]; then printf "${BAR}%s${OFF}" "$(pad "$text")"; return; fi
  case "$state" in
    running) printf "${OK}%s${OFF}" "$(pad "$text")" ;;
    ready)   printf "${SAND}%s${OFF}" "$(pad "$text")" ;;
    *)       printf "${DIM}%s${OFF}" "$(pad "$text")" ;;
  esac
}

rule() { printf "  ${AM}+"; printf -- '-%.0s' $(seq 1 $W); printf "+"; printf -- '-%.0s' $(seq 1 $W); printf "+${OFF}\n"; }

quad_row() {
  local left="$1" right="$2" l1 l2 l3 r1 r2 r3 ls rs lf rf
  cell "$left";  l1="$q1"; l2="$q2"; l3="$q3"; ls="$qstate"
  cell "$right"; r1="$q1"; r2="$q2"; r3="$q3"; rs="$qstate"
  lf=0; rf=0
  [ "$SEL" = "$left" ] && lf=1
  [ "$SEL" = "$right" ] && rf=1
  printf "  ${AM}|${OFF}%b${AM}|${OFF}%b${AM}|${OFF}\n" \
    "$(paint "$l1" "$ls" "$lf")" "$(paint "$r1" "$rs" "$rf")"
  printf "  ${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}\n" \
    "$(pad "  $l2")" "$(pad "  $r2")"
  printf "  ${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}\n" \
    "$(pad "  $l3")" "$(pad "  $r3")"
}

# Width of the terminal. Below 49 columns the 2 by 2 frame (47 wide) cannot be
# drawn, so the four apps are four lines instead (field test v21, F12).
term_cols() {
  local c; c=$(tput cols 2>/dev/null || true)
  case "$c" in ''|*[!0-9]*) c=${COLUMNS:-80} ;; esac
  case "$c" in ''|*[!0-9]*) c=80 ;; esac
  printf '%s' "$c"
}

# Dim text wrapped to the terminal, never cut mid-word.
say_wrapped() {
  local l
  printf '%s\n' "$1" | fold -s -w "$((COLS-4))" | while IFS= read -r l; do
    printf "  ${DIM}%s${OFF}\n" "$l"
  done
}

grid_narrow() {
  local n focused
  PW=$((COLS-4)); [ "$PW" -lt 20 ] && PW=20
  for n in 1 2 3 4; do
    cell "$n"
    focused=0; [ "$SEL" = "$n" ] && focused=1
    if [ -n "$q2" ]; then _l=$(printf '%s  %s' "$q1" "$q2"); else _l="$q1"; fi
    printf "  %b\n" "$(paint "$_l" "$qstate" "$focused")"
  done
  PW=$W
}

# The ten keys, five to a row where they fit and fewer where they do not.
draw_keys() {
  local any_run="$1" per n=0 item
  per=$(( (COLS-2) / 8 )); [ "$per" -gt 5 ] && per=5; [ "$per" -lt 2 ] && per=2
  printf "  "
  for item in "h|elp |1" "r|efresh |1" "c|heck |1" "t|est |1" "i|nstall|1" \
              "u|pdate |1" "k|ey |1" "S|topAll|$any_run" "w|ipe |1" "q|uit|1"; do
    fkey "" "${item%%|*}" "$(printf '%s' "$item" | cut -d'|' -f2)" "${item##*|}"
    n=$((n+1))
    if [ $((n % per)) = 0 ] && [ "$n" -lt 10 ]; then printf "\n  "; fi
  done
  printf "\n"
}

draw() {
  clear 2>/dev/null || true
  COLS=$(term_cols)
  local id any_run=0 sel_id sel_run=0 sel_inst=0 narrow=0
  [ "$COLS" -lt 49 ] && narrow=1
  printf "\n  ${KEY}MAHA COMMUTE${OFF} ${DIM}%s${OFF}\n" "$MAHA_VERSION"
  if [ "$narrow" = 1 ]; then grid_narrow
  else rule; quad_row 1 2; rule; quad_row 3 4; rule; fi

  sel_id=$(app_at "$SEL")
  [ -n "$sel_id" ] && { running "$sel_id" && sel_run=1; is_installed "$sel_id" && sel_inst=1; }
  for id in $(app_ids); do running "$id" && any_run=1; done

  # The verbs, which act on whichever quadrant has the focus. Focus 0 is the
  # launcher itself: nothing is lit and the keys below act on all of it.
  if [ "$SEL" = 0 ]; then
    if [ "$any_run" = 1 ]; then
      say_wrapped "launcher: apps are running, so u needs one lit app"
    else
      say_wrapped "launcher: nothing runs, so u updates all of it"
    fi
    printf "\n"
  elif [ -z "$sel_id" ]; then
    say_wrapped "quadrant 4 is free. The verbs wait for an app."
    printf "\n"
  else
    printf "  ${DIM}on ${OFF}${KEY}%s${OFF}${DIM}:${OFF}" "$(field "$(app_row "$sel_id")" 2)"
    if [ "$narrow" = 1 ]; then printf "\n  "; else printf "  "; fi
    if [ "$sel_inst" != 1 ]; then
      printf "${KEY}Enter${OFF}${SAND}=install${OFF}${DIM}  open stop restart log${OFF}"
    elif [ "$sel_run" = 1 ]; then
      printf "${KEY}Enter${OFF}${SAND}=open${OFF}  ${KEY}s${OFF}${SAND}top${OFF}  ${KEY}R${OFF}${SAND}estart${OFF}  ${KEY}l${OFF}${SAND}og${OFF}"
    else
      printf "${KEY}Enter${OFF}${SAND}=start${OFF}${DIM}  stop restart${OFF}  ${KEY}l${OFF}${SAND}og${OFF}"
    fi
    printf "\n\n"
  fi
  # Every label is spelled by its own key: r efresh, c heck, w ipe. A key
  # whose letter does not begin its word has to be read rather than
  # recognised, and this row is meant to be recognised.
  draw_keys "$any_run"
  printf "\n"
  say_wrapped "1-4 light an app (starts it if idle), 0 the launcher"
  printf "  ${AM}>${OFF} "
}

screen_log() {
  local id="$1" f="$RUNDIR/$1.log"
  clear 2>/dev/null || true
  printf "\n  ${KEY}%s${OFF} ${DIM}in its own words${OFF}\n\n" "$(field "$(app_row "$id")" 2)"
  if [ -s "$f" ]; then
    tail -20 "$f" | cut -c1-46 | sed 's/^/  /'
  else
    printf "  ${DIM}nothing yet. It writes here when it is started from${OFF}\n"
    printf "  ${DIM}this launcher.${OFF}\n"
  fi
  anykey
}

# The panel says what is running. This says what is HERE: where each app
# keeps its data, how big it has grown, whether the payloads still match
# their checksums and whether a key is stored. It reads the disk and the
# local ports and nothing else.
screen_info() {
  local id row cmd dir port
  printf "\n  ${KEY}WHAT IS ON THIS PHONE${OFF}\n\n"
  for id in $(app_ids); do
    row=$(app_row "$id"); cmd=$(field "$row" 2)
    dir="$HOME/$(field "$row" 3)"; port=$(app_port "$id")
    printf "  ${SAND}%s${OFF}\n" "$cmd"
    if is_installed "$id"; then
      printf "    ${DIM}command  ${OFF}${OK}%s${OFF}\n" "$BIN/$cmd"
    else
      printf "    ${DIM}command  not installed${OFF}\n"
    fi
    if [ -d "$dir" ]; then
      printf "    ${DIM}data     %s, %s${OFF}\n" "$dir" "$(du -sh "$dir" 2>/dev/null | cut -f1)"
    else
      printf "    ${DIM}data     none yet${OFF}\n"
    fi
    if port_live "$port"; then
      printf "    ${DIM}port     ${OFF}${OK}%s answering${OFF}\n" "$port"
    else
      printf "    ${DIM}port     %s quiet${OFF}\n" "$port"
    fi
  done
  printf "\n  ${SAND}the umbrella${OFF}\n"
  printf "    ${DIM}payloads %s${OFF}\n" "$PAYDIR"
  if command -v sha256sum >/dev/null 2>&1 && [ -f "$PAYDIR/SHA256SUMS" ]; then
    if ( cd "$PAYDIR" && sha256sum -c --status SHA256SUMS 2>/dev/null ); then
      printf "    ${DIM}checked  ${OFF}${OK}all three match${OFF}\n"
    else
      printf "    ${DIM}checked  ${OFF}${BAD}a payload does not match its checksum${OFF}\n"
    fi
  else
    printf "    ${DIM}checked  no sha256sum here, sizes only${OFF}\n"
  fi
  if [ -s "$KEYFILE" ]; then
    printf "    ${DIM}key      present, %s characters${OFF}\n" \
      "$(tr -d ' \r\n' < "$KEYFILE" | wc -c | tr -d ' ')"
  else
    printf "    ${DIM}key      none${OFF}\n"
  fi
  printf "\n"
}

screen_help() {
  clear 2>/dev/null || true
  COLS=$(term_cols)
  # fold -s wraps at the terminal's width on a space, so nothing is cut in a word
  fold -s -w "$((COLS-2))" <<'HELPTEXT'

MAHA COMMUTE

Four quadrants, one app each. The fourth is free and stays drawn, so the screen does not move when a fourth app arrives.

1 2 3 4 light an app. If it is idle its number starts it. If it is already running the number only moves the light, so with two apps up, 1 and 3 swap between them and nothing reopens. Every running app says RUNNING in its quadrant, with its port.

0 is the launcher itself: nothing is lit and the keys that belong to no single app act on all of it.

Arrows move the light without starting anything, for when you want to look before you press.

The verbs are the same for every quadrant and act on the lit one, which is the whole point: one set of keys.

  Enter  open it, starting it first if it is not running
  o      open the page again
  s      stop it
  R      restart it
  l      its log, the last twenty lines
  i      install it, or remove it if it is here

Servers stack: start all three and all three keep running, on 8082, 8087 and 8084.

The bottom rows are always the same ten keys, dim when they do not apply. Press the letter shown in white.

  h  this
  r  refresh every ZET stream, then check it
  c  check the streams without refreshing
  t  test every key this phone holds
  i  install or remove an app
  u  update. Nothing running: the whole launcher. Apps running: only the lit one (0 or S first for all)
  k  the shared google key
  S  stop all of them
  w  wipe: uninstall, which asks twice
  q  quit the menu, leaving the servers running

Quitting does not stop anything. The servers keep serving and the pages stay open. S is what stops them.

HELPTEXT
  anykey
}

screen_install() {
  local id a cmd n
  while :; do
    clear 2>/dev/null || true
    printf "\n  ${KEY}INSTALL OR REMOVE${OFF}\n"
    printf "  ${DIM}a number adds it if missing, takes it away if here${OFF}\n\n"
    n=0
    for id in $(app_ids); do
      n=$((n+1))
      if is_installed "$id"; then
        printf "  ${KEY}%s${OFF}  ${OK}[x]${OFF} ${SAND}%-15s${OFF} ${DIM}%s${OFF}\n" \
          "$n" "$(field "$(app_row "$id")" 2)" "$(stamped "$id")"
      else
        printf "  ${KEY}%s${OFF}  ${DIM}[ ] %-15s not installed${OFF}\n" \
          "$n" "$(field "$(app_row "$id")" 2)"
      fi
    done
    printf "\n  ${KEY}a${OFF} ${DIM}all three${OFF}   ${KEY}q${OFF} ${DIM}back${OFF}\n\n  ${AM}>${OFF} "
    read -rsn1 a 2>/dev/null || read -r a
    printf "\n"
    case "$a" in
      1|2|3)
        id=$(app_at "$a")
        if is_installed "$id"; then
          running "$id" && stop_app "$id"
          cmd=$(field "$(app_row "$id")" 2)
          rm -f "$BIN/$cmd" "$APPHOME/orig/$cmd" "$STAMPDIR/$id"
          printf "  ${SAND}%s removed. Its data is untouched.${OFF}\n" "$cmd"
          anykey
        else
          bash "$APPHOME/install-one.sh" "$id" --offline || true; anykey
        fi ;;
      a|A) for id in $(app_ids); do
             is_installed "$id" || bash "$APPHOME/install-one.sh" "$id" --offline || true
           done; anykey ;;
      q|Q|"") return 0 ;;
    esac
  done
}

screen_key() {
  local a k
  clear 2>/dev/null || true
  printf "\n  ${KEY}GOOGLE KEY${OFF}\n"
  printf "  ${DIM}one key, shared by all three, never printed${OFF}\n\n"
  if [ -s "$KEYFILE" ]; then
    printf "  ${OK}present${OFF} ${DIM}%s characters${OFF}\n" \
      "$(tr -d ' \r\n' < "$KEYFILE" | wc -c | tr -d ' ')"
  else
    printf "  ${DIM}none stored${OFF}\n"
  fi
  printf "\n  ${KEY}Enter${OFF} ${DIM}back${OFF}  ${KEY}p${OFF} ${DIM}paste one${OFF}  ${KEY}x${OFF} ${DIM}forget it${OFF}\n\n  ${AM}>${OFF} "
  IFS= read -r a || a=""
  case "$a" in
    p|P) printf "\n  ${DIM}paste, then Enter${OFF}\n  ${AM}>${OFF} "
         IFS= read -r k || k=""
         k=$(printf '%s' "$k" | tr -cd 'A-Za-z0-9_.-' | head -c 200)
         if [ -n "$k" ]; then
           mkdir -p "$KEYDIR"; printf '%s\n' "$k" > "$KEYFILE"; chmod 600 "$KEYFILE"
           bash "$APPHOME/install-one.sh" --sync-key force >/dev/null 2>&1 || true
           printf "\n  ${OK}stored, and given to every app that is here${OFF}\n"
         else
           printf "\n  ${DIM}nothing was changed${OFF}\n"
         fi
         anykey ;;
    x|X) rm -f "$KEYFILE"; printf "\n  ${SAND}forgotten here${OFF}\n"; anykey ;;
  esac
}

case "${1:-}" in
  day|night|all)  start_app "$1"; exit 0 ;;
  # The four ways in that the app's own command now uses (see launcher_of).
  # focus opens this same screen with that app selected, starting it first if
  # it is not running, which is what pressing its number does.
  focus)          _n=$(app_ids | grep -nx "${2:-}" | cut -d: -f1); SEL=${_n:-1}
                  [ -n "${2:-}" ] && start_app "$2" ;;
  restart)        [ -n "${2:-}" ] && { stop_app "$2"; start_app "$2"; }; exit 0 ;;
  open)           [ -n "${2:-}" ] && { if running "$2"; then open_url "http://127.0.0.1:$(app_port "$2")/?run=$RUN"; else start_app "$2"; fi; }; exit 0 ;;
  log)            [ -n "${2:-}" ] && screen_log "$2"; exit 0 ;;
  stop)           if [ -n "${2:-}" ]; then stop_app "$2"; else stop_all; fi; exit 0 ;;
  # status draws the panel once and leaves. It asks the disk and the local
  # ports and nothing else: a question about what is installed must never
  # reach the network. This case was lost in a rewrite once, which turned
  # `maha-commute status` into an interactive session reading from whatever
  # stdin happened to be, so it is tested now rather than trusted.
  status)         draw; printf "\n"; exit 0 ;;
  info)           screen_info; exit 0 ;;
  install|add)    screen_install; exit 0 ;;
  key)            screen_key; exit 0 ;;
  keytest|keys)   exec "$PY" "$APPHOME/keytest.py" ;;
  refresh)        exec "$PY" "$APPHOME/stream.py" refresh --check ;;
  check|doctor)   exec "$PY" "$APPHOME/stream.py" check ;;
  update|-update|--update) exec bash "$APPHOME/update.sh" ;;
  uninstall|wipe) exec bash "$APPHOME/uninstall.sh" ;;
  -h|--help)
    printf 'maha.commute [day|night|all|-update|focus APP|open APP|restart APP|log APP|status|info|stop [app]|install|key|keytest|refresh|check|update|uninstall]\n'
    exit 0 ;;
esac

# The screen is a status board: it redraws by itself when an app comes up or
# goes away, so a server started from another window shows up here without a
# keypress. It redraws only when the picture would change, never on a timer,
# because a screen that repaints every few seconds flickers and eats the
# key being typed.
state_sig() { local id o=""; for id in $(app_ids); do running "$id" && o="$o$id,"; done; printf '%s' "$o"; }
SIG=$(state_sig)
REDRAW=1
while :; do
  [ "$REDRAW" = 1 ] && { draw; SIG=$(state_sig); }
  REDRAW=1
  # End of input is not a keypress. Reading EOF used to leave c empty, which
  # matched the Enter case and started an app, so piping anything into the
  # launcher launched something. EOF means the person is gone: leave.
  # A TIMEOUT (status above 128) is not EOF: it is the moment to look again.
  read -rsn1 -t 4 c 2>/dev/null; rc=$?
  if [ "$rc" -gt 128 ]; then
    NEWSIG=$(state_sig)
    if [ "$NEWSIG" != "$SIG" ]; then SIG="$NEWSIG"; else REDRAW=0; fi
    continue
  elif [ "$rc" -ne 0 ]; then
    if ! read -r c 2>/dev/null; then printf "\n\n"; exit 0; fi
  fi
  # An arrow arrives as escape, bracket, letter. The two extra reads carry a
  # timeout so Escape on its own does not hang here waiting for the rest of
  # a sequence that is never coming.
  if [ "$c" = "$(printf '\033')" ]; then
    read -rsn1 -t 0.05 c2 2>/dev/null || c2=""
    read -rsn1 -t 0.05 c3 2>/dev/null || c3=""
    case "$c2$c3" in
      "[A"|"[D") c="prev" ;; "[B"|"[C") c="next" ;; *) c="esc" ;;
    esac
  fi
  SELAPP=$(app_at "$SEL")
  case "$c" in
    # 0 is the launcher: nothing lit, and the keys act on all of it.
    0) SEL=0 ;;
    # A number LIGHTS an app. If it is idle it is started first, which is how
    # an app gets running; if it is already running the number only moves the
    # light, so with two apps up, 1 and 3 swap between them without opening a
    # page each time. Enter or o opens the page.
    1|2|3|4)
      SEL="$c"
      NEW=$(app_at "$SEL")
      if [ -n "$NEW" ] && ! running "$NEW"; then start_app "$NEW"; fi ;;
    prev) SEL=$((SEL-1)); [ "$SEL" -lt 0 ] && SEL=4 ;;
    next) SEL=$((SEL+1)); [ "$SEL" -gt 4 ] && SEL=0 ;;

    # the verbs, on the focused quadrant
    "")  [ -n "$SELAPP" ] && start_app "$SELAPP" ;;
    o|O) [ -n "$SELAPP" ] && { if running "$SELAPP"; then
           LAST="$SELAPP"; open_url "http://127.0.0.1:$(app_port "$SELAPP")/?run=$RUN"
         else start_app "$SELAPP"; fi; } ;;
    s)   [ -n "$SELAPP" ] && { printf "\n"; stop_app "$SELAPP"; sleep 1; } ;;
    R)   [ -n "$SELAPP" ] && { printf "\n"; stop_app "$SELAPP"; start_app "$SELAPP"; } ;;
    l|L) [ -n "$SELAPP" ] && screen_log "$SELAPP" ;;

    # the things that belong to no single app
    h|H) screen_help ;;
    r)   printf "\n"; "$PY" "$APPHOME/stream.py" refresh --check; anykey ;;
    c|C|d|D) printf "\n"; "$PY" "$APPHOME/stream.py" check; anykey ;;
    t|T) printf "\n"; "$PY" "$APPHOME/keytest.py"; anykey ;;
    i|I) screen_install ;;
    k|K) screen_key ;;
    u|U) update_focus ;;
    S)   stop_all ;;
    w|W|x|X) printf "\n"; bash "$APPHOME/uninstall.sh"; anykey ;;
    q|Q) printf "\n"
         for id in $(app_ids); do
           running "$id" && { printf "  ${DIM}servers left running. S stops them.${OFF}\n"; break; }
         done
         printf "\n"; exit 0 ;;
  esac
done
MAHA_MENU_7c1a
}

maha_emit_install_one() {
  cat <<'MAHA_INSTALLONE_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# install-one.sh, written by the MAHA COMMUTE installer.
#
# One app, from the payload already on the phone. This is the only
# routine that installs anything: the installer calls it for each app
# picked on the first run, and the commute menu calls the same file
# when an app is added later. Two callers, one implementation, so a
# fix to the install path cannot reach one of them and miss the other.
#
#   install-one.sh day --offline
#   install-one.sh night --online

set -e
. "$HOME/.maha.commute/env.sh"

APP="${1:-}"
FLAG="${2:---offline}"

# --sync-key [force]: copy the shared key into every installed app's own key
# file. Without "force" an app that already holds a key is left alone (it may be
# a different one, and it was put there by hand); with it (the person pasted a
# new key in the launcher) every app gets it. Never prints the key.
key_ok() { [ -f "$1" ] && [ "$(grep -v '^[[:space:]]*$' "$1" 2>/dev/null | head -1 | tr -cd 'A-Za-z0-9_-' | head -c 200 | wc -c | tr -d ' ')" -ge 20 ]; }
sync_key() {   # sync_key FORCE
  local force="$1" id row dir name dst
  key_ok "$KEYFILE" || return 0
  for id in $(printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1); do
    row=$(printf '%s\n' "$MAHA_APPS" | grep "^$id|" || true)
    dir="$HOME/$(printf '%s' "$row" | cut -d'|' -f3)"
    name=$(printf '%s' "$row" | cut -d'|' -f9)
    [ -d "$dir" ] && [ -n "$name" ] || continue
    dst="$dir/$name"
    if [ "$force" = "force" ] || ! key_ok "$dst"; then
      grep -v '^[[:space:]]*$' "$KEYFILE" | head -1 | tr -cd 'A-Za-z0-9_-' | head -c 200 > "$dst.new"
      printf '\n' >> "$dst.new"; chmod 600 "$dst.new"; mv -f "$dst.new" "$dst"
    fi
  done
}
if [ "$APP" = "--sync-key" ]; then sync_key "${2:-}"; exit 0; fi

if [ -t 1 ]; then
  AM="\033[38;5;214m"; OK="\033[1;32m"; BAD="\033[1;31m"
  DIM="\033[0;90m"; KEY="\033[1;37m"; OFF="\033[0m"
else
  AM=""; OK=""; BAD=""; DIM=""; KEY=""; OFF=""
fi

row=$(printf '%s\n' "$MAHA_APPS" | grep "^$APP|" || true)
if [ -z "$row" ]; then
  printf "  ${BAD}no such app: %s${OFF}\n" "$APP"; exit 2
fi
CMD=$(printf '%s' "$row" | cut -d'|' -f2)
VER=$(printf '%s' "$row" | cut -d'|' -f4)
PORT=$(printf '%s' "$row" | cut -d'|' -f5)
PROC=$(printf '%s' "$row" | cut -d'|' -f7)
SRC="$PAYDIR/$APP.payload.sh"

if [ ! -f "$SRC" ]; then
  printf "  ${BAD}the payload for %s is not on this phone${OFF}\n" "$APP"
  printf "  ${DIM}run the installer again to put it back${OFF}\n"
  exit 3
fi

# Check the payload before running it, not after. A payload that lost
# bytes somewhere installs half an app and says nothing.
if command -v sha256sum >/dev/null 2>&1 && [ -f "$PAYDIR/SHA256SUMS" ]; then
  if ! ( cd "$PAYDIR" && grep " $APP.payload.sh\$" SHA256SUMS | sha256sum -c --status - ); then
    printf "  ${BAD}the %s payload does not match its checksum${OFF}\n" "$APP"
    printf "  ${DIM}nothing was changed${OFF}\n"
    exit 4
  fi
else
  want=$(grep "^$APP|" "$PAYDIR/SIZES" 2>/dev/null | cut -d'|' -f2)
  have=$(wc -c < "$SRC" | tr -d ' ')
  if [ -n "$want" ] && [ "$want" != "$have" ]; then
    printf "  ${BAD}the %s payload is %s bytes, expected %s${OFF}\n" "$APP" "$have" "$want"
    printf "  ${DIM}nothing was changed${OFF}\n"
    exit 4
  fi
fi

# night.commute v9 begins by deleting its own app directory, so an
# upgrade takes everything in it with it. That is the payload's own
# decision and it is left alone: a clean directory is what stops stale
# state, and the umbrella does not get to overrule an app about its own
# data. What the umbrella can do is make it recoverable, so the payload
# is read first and a copy taken only when it is going to wipe.
APPDIR="$HOME/$(printf '%s' "$row" | cut -d'|' -f3)"
if [ -d "$APPDIR" ] && grep -qF "rm -rf \"\$HOME/$(printf '%s' "$row" | cut -d'|' -f3)\"" "$SRC"; then
  BK="$APPHOME/backup/$APP.prev"
  mkdir -p "$APPHOME/backup"
  rm -rf "$BK" 2>/dev/null || true
  if cp -a "$APPDIR" "$BK" 2>/dev/null; then
    printf "  ${DIM}%s clears its folder on install. A copy is kept in${OFF}\n" "$CMD"
    printf "  ${DIM}%s  (%s)${OFF}\n" "$BK" "$(du -sh "$BK" 2>/dev/null | cut -f1)"
    printf "  ${DIM}its key, its PDF timetables and the ZET schedule are kept in place${OFF}\n"
  else
    printf "  ${BAD}could not copy %s, and this install will clear it${OFF}\n" "$APPDIR"
    printf "  ${DIM}nothing was changed${OFF}\n"
    exit 5
  fi
fi

mkdir -p "$APPHOME/tmp"
chmod 700 "$APPHOME/tmp" 2>/dev/null || true
TMP="$APPHOME/tmp/$APP.run.sh"
trap 'rm -f "$TMP"' EXIT INT TERM HUP

# Cleaned again here, at the point of use, because the file could have
# been edited by hand between being written and being read.
GKEY=""
if [ -f "$KEYFILE" ]; then
  GKEY=$(grep -v '^[[:space:]]*$' "$KEYFILE" | head -1 | tr -cd 'A-Za-z0-9_-' | head -c 200)
fi

# The key goes into the copy that runs and never into the copy that is
# kept. The kept payload holds a placeholder and nothing else, which is
# why this file can sit in a repository.
{
  head -1 "$SRC"
  printf 'clear() { :; }\n'
  tail -n +2 "$SRC" | sed "s|__MAHA_GOOGLE_KEY__|$GKEY|g"
} > "$TMP"
chmod 600 "$TMP"

printf "\n  ${AM}|${OFF} ${KEY}%s${OFF} ${DIM}%s${OFF}\n" "$CMD" "$VER"

# A server already running is holding the old code in memory, and it
# goes on serving that code after its files have been replaced. From
# outside that looks like an install that did nothing. So it is stopped
# first, by its own launcher where the launcher knows how, and by the
# name of its process where it does not.
LAUNCH="$BIN/$CMD"; [ -x "$APPHOME/orig/$CMD" ] && LAUNCH="$APPHOME/orig/$CMD"
if [ -x "$BIN/$CMD" ] && (exec 3<>"/dev/tcp/127.0.0.1/$PORT") 2>/dev/null; then
  exec 3<&-
  printf "  ${DIM}stopping the running server first${OFF}\n"
  if grep -q '^  stop)' "$LAUNCH" 2>/dev/null; then
    "$LAUNCH" stop >/dev/null 2>&1 || true
  fi
  pkill -f "$PROC" 2>/dev/null || true
  sleep 1
fi

rc=0
bash "$TMP" "$FLAG" || rc=$?
rm -f "$TMP"

if [ "$rc" != "0" ]; then
  printf "  ${BAD}%s did not finish, exit %s${OFF}\n" "$CMD" "$rc"
  exit "$rc"
fi

# BEGIN SHIM
# v17: typing the app's own name opens the launcher's screen with that app
# focused, the same screen and the same verbs as everywhere else. The app's
# real launcher is kept in orig/ and the launcher always talks to THAT, never
# to this file, so nothing here can call itself. The new file is written beside
# its name and renamed over it, never truncated in place (termux-app.md 4).
write_shim() {   # write_shim ID CMD
  local id="$1" cmd="$2" orig="$APPHOME/orig/$2" new="$BIN/.$2.new"
  if [ -f "$BIN/$cmd" ] && ! grep -q '^# MAHA_SHIM ' "$BIN/$cmd" 2>/dev/null; then
    mkdir -p "$APPHOME/orig"
    cp -f "$BIN/$cmd" "$orig.new" && chmod +x "$orig.new" && mv -f "$orig.new" "$orig"
  fi
  [ -x "$orig" ] || return 0
  rm -f "$new"
  cat > "$new" <<'MAHA_SHIM_TEXT'
#!/data/data/com.termux/files/usr/bin/bash
# MAHA_SHIM @ID@, written by the MAHA COMMUTE installer and not part of the app.
# Typing this command opens the launcher screen with this app focused. The
# app's own launcher is kept in ~/.maha.commute/orig/ and still does the work.
ORIG="$HOME/.maha.commute/orig/@CMD@"
[ -x "$ORIG" ] || { echo "the launcher for @CMD@ is missing, run the MAHA COMMUTE installer again" >&2; exit 1; }
command -v maha-commute >/dev/null 2>&1 || exec "$ORIG" "$@"
case "${1:-}" in
"")      exec maha-commute focus @ID@ ;;
stop)    exec maha-commute stop @ID@ ;;
status)  exec maha-commute status ;;
restart) exec maha-commute restart @ID@ ;;
open)    exec maha-commute open @ID@ ;;
log)     exec maha-commute log @ID@ ;;
*)       exec "$ORIG" "$@" ;;
esac
MAHA_SHIM_TEXT
  sed -i "s/@ID@/$id/g; s/@CMD@/$cmd/g" "$new"
  chmod +x "$new" && mv -f "$new" "$BIN/$cmd"
}
# END SHIM
write_shim "$APP" "$CMD"
sync_key ""

mkdir -p "$STAMPDIR"
printf '%s\n' "$VER" > "$STAMPDIR/$APP"
# The checksum of the payload that is now on this phone. The next install
# compares against it and leaves this app alone when it has not moved, so an
# update touches the apps that changed and no others.
if command -v sha256sum >/dev/null 2>&1; then
  sha256sum "$SRC" | cut -d" " -f1 > "$STAMPDIR/$APP.sha"
else
  wc -c < "$SRC" | tr -d ' ' > "$STAMPDIR/$APP.sha"
fi
exit 0
MAHA_INSTALLONE_7c1a
}

maha_emit_stream() {
  cat <<'MAHA_STREAM_7c1a'
#!/usr/bin/env python3
"""stream.py, written by the MAHA COMMUTE installer.

Two jobs, one file, shared by all three apps because all three drink from
the same two ZET taps:

    the static schedule    https://www.zet.hr/gtfs-scheduled/latest   a zip
    the live feed          https://zet.hr/gtfs-rt-protobuf            protobuf

    python stream.py check     say whether what is arriving is sound
    python stream.py refresh   throw the cached copies away
    python stream.py refresh --check   both, in that order

WHY THIS EXISTS

An app that asks "did the download work" gets yes, and shows old data with
total confidence. Every one of the three apps checks the transport and none
of them checks the CARGO. A feed can be:

    stalled       200 OK, right size, right shape, and a header timestamp
                  from forty minutes ago. This is the common one and it is
                  invisible without reading that timestamp
    thin          200 OK and eleven vehicles in a city that runs six hundred
    disagreeing   live trip ids that are not in the static build the app is
                  holding, because ZET published a new schedule and the app
                  is a day behind. The field does not fit the timetable
    expired       a static build whose calendar ended before today
    misplaced     vehicles at 0,0 or in the Adriatic
    skewed        nothing wrong with the feed at all, the phone's clock is out

Each of those is a different fault with a different fix, and from inside the
app they all look the same: wrong numbers on the screen. So each is measured
separately and named separately.

Nothing here writes to any app's folder except to delete a cache. It never
touches a key, a station index, a stored timetable or a note.
"""

import json
import os
import struct
import sys
import time
import zipfile

APPHOME = os.path.join(os.path.expanduser("~"), ".maha.commute")
RT_URL = "https://zet.hr/gtfs-rt-protobuf"
STATIC_URL = "https://www.zet.hr/gtfs-scheduled/latest"
UA = "maha.commute-stream/1"

# Zagreb, generously. A vehicle outside this is not a vehicle.
LAT_MIN, LAT_MAX = 45.60, 46.05
LON_MIN, LON_MAX = 15.65, 16.30

# What may be deleted, per app. An allowlist and not a wildcard, because a
# refresh that also takes the station index or the stored timetables costs
# an hour of rebuilding and looks like the refresh broke the app.
CACHES = {
    "day": {
        "dir": ".commute",
        "files": ["zet_gtfs.zip", "bus.json", "trips_path.json", "gtfs_meta.json"],
        "dirs": ["daycache"],
        "keep": ["google-api.txt", "gemini-api.txt", "settings.json", "port",
                 "server.log", "pinned.txt"],
    },
    "night": {
        "dir": ".nightcommute",
        "files": ["zet_gtfs.zip"],
        "dirs": [],
        "keep": ["gmaps-api.txt", "gemini-api.txt", "port", "server.out"],
    },
    "all": {
        "dir": ".all.commute",
        "files": ["zet_gtfs.zip"],
        "dirs": [],
        "keep": ["google-api.txt", "gemini-api.txt", "stations.json",
                 "timetables", "all.html", "all_commute_server.py", "port"],
    },
}

STATE = os.path.join(APPHOME, "stream_state.json")


# ---------------------------------------------------------------------------
# a protobuf reader that reads only what it needs
#
# GTFS realtime is protobuf, and the phone has no protobuf library. Only
# three things are wanted: the header timestamp, how many entities there
# are, and the trip id and position inside each one. Wire types are enough
# for that: every field carries its own type, so an unknown field is
# skipped by length rather than guessed at.
# ---------------------------------------------------------------------------

def _varint(b, i):
    shift = 0
    val = 0
    while i < len(b):
        c = b[i]
        val |= (c & 0x7F) << shift
        i += 1
        if not c & 0x80:
            return val, i
        shift += 7
        if shift > 70:
            raise ValueError("varint too long")
    raise ValueError("varint ran off the end")


def _fields(b, start=0, end=None):
    """Yield (field_number, wire_type, value_or_slice) across one message."""
    i = start
    end = len(b) if end is None else end
    while i < end:
        key, i = _varint(b, i)
        fn, wt = key >> 3, key & 7
        if wt == 0:
            v, i = _varint(b, i)
            yield fn, wt, v
        elif wt == 1:
            v = b[i:i + 8]
            i += 8
            yield fn, wt, v
        elif wt == 2:
            ln, i = _varint(b, i)
            if i + ln > end:
                raise ValueError("length delimited field runs past the end")
            yield fn, wt, b[i:i + ln]
            i += ln
        elif wt == 5:
            v = b[i:i + 4]
            i += 4
            yield fn, wt, v
        else:
            raise ValueError("wire type %d, which this feed should not contain" % wt)


def parse_feed(b):
    """FeedMessage -> a small dictionary. Raises on anything malformed."""
    out = {"header_ts": None, "version": None, "entities": 0,
           "trip_ids": [], "positions": [], "entity_ts": []}
    for fn, wt, v in _fields(b):
        if fn == 1 and wt == 2:                      # FeedHeader
            for hfn, hwt, hv in _fields(v):
                if hfn == 1 and hwt == 2:
                    out["version"] = hv.decode("utf-8", "replace")
                elif hfn == 3 and hwt == 0:
                    out["header_ts"] = hv
        elif fn == 2 and wt == 2:                    # FeedEntity
            out["entities"] += 1
            _entity(v, out)
    return out


def _entity(b, out):
    for fn, wt, v in _fields(b):
        if wt != 2:
            continue
        if fn in (3, 4):                             # TripUpdate, VehiclePosition
            for sfn, swt, sv in _fields(v):
                if sfn == 1 and swt == 2:            # TripDescriptor
                    for tfn, twt, tv in _fields(sv):
                        if tfn == 1 and twt == 2:
                            out["trip_ids"].append(tv.decode("utf-8", "replace"))
                elif fn == 4 and sfn == 2 and swt == 2:   # Position
                    lat = lon = None
                    for pfn, pwt, pv in _fields(sv):
                        if pfn == 1 and pwt == 5:
                            lat = struct.unpack("<f", pv)[0]
                        elif pfn == 2 and pwt == 5:
                            lon = struct.unpack("<f", pv)[0]
                    if lat is not None and lon is not None:
                        out["positions"].append((lat, lon))
                elif swt == 0 and sfn in (4, 5):     # a timestamp on the entity
                    if sv > 1000000000:
                        out["entity_ts"].append(sv)


# ---------------------------------------------------------------------------
# the checks
# ---------------------------------------------------------------------------

class Result(list):
    def add(self, level, name, detail):
        self.append((level, name, detail))

    @property
    def bad(self):
        return sum(1 for lvl, _, _ in self if lvl == "bad")

    @property
    def warn(self):
        return sum(1 for lvl, _, _ in self if lvl == "warn")


def _get(url, timeout=20):
    import urllib.request
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    t0 = time.time()
    with urllib.request.urlopen(req, timeout=timeout) as r:
        body = r.read()
        # Lower cased on the way out. dict(r.headers) keeps the server's own
        # capitalisation and a plain dict lookup is case sensitive, so
        # headers.get("Content-Type") came back None against the real feed
        # and the "is this an HTML error page" check would never have fired.
        # A check that cannot fire looks exactly like a check that passes.
        heads = {k.lower(): v for k, v in r.headers.items()}
        return body, r.status, heads, time.time() - t0


def _state():
    try:
        with open(STATE, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _save_state(s):
    os.makedirs(APPHOME, exist_ok=True)
    tmp = STATE + ".new"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(s, f)
    os.replace(tmp, STATE)


def check_live(res, state):
    """The live feed: does it arrive, is it fresh, is it moving, does it fit."""
    try:
        body, status, headers, took = _get(RT_URL)
    except Exception as e:
        res.add("bad", "live feed", "did not answer: %s" % e)
        return None
    ctype = headers.get("content-type", "")
    res.add("ok", "live feed answered", "%d, %d bytes, %.1fs" % (status, len(body), took))

    # A captive portal or an error page is HTML and is still 200.
    if body[:15].lstrip()[:1] == b"<" or "html" in ctype.lower():
        res.add("bad", "live feed shape", "this is a web page, not a feed")
        return None
    if len(body) < 200:
        res.add("bad", "live feed size", "%d bytes is too small to be a feed" % len(body))
        return None
    try:
        feed = parse_feed(body)
    except Exception as e:
        res.add("bad", "live feed parse", "malformed protobuf: %s" % e)
        return None

    now = int(time.time())
    ts = feed["header_ts"]
    if not ts:
        res.add("warn", "live feed timestamp", "the feed carries no header timestamp")
    else:
        age = now - ts
        if age < 0:
            res.add("warn", "live feed timestamp",
                    "dated %ds in the FUTURE, so one of the two clocks is wrong" % -age)
        elif age <= 120:
            res.add("ok", "live feed is fresh", "%ds old" % age)
        elif age <= 600:
            res.add("warn", "live feed is late", "%d minutes old" % (age // 60))
        else:
            res.add("bad", "live feed is stale",
                    "%d minutes old. The numbers on the screen are from then, "
                    "not from now" % (age // 60))

    # An independent witness. The header timestamp is written by whoever
    # builds the feed; Last-Modified is written by the server that serves it.
    # When those two disagree by a lot, something in between is holding a
    # copy, and that is a different fault from a publisher that has stopped.
    lm = headers.get("last-modified")
    if lm and ts:
        try:
            import email.utils
            lmts = int(email.utils.parsedate_to_datetime(lm).timestamp())
            drift = abs(lmts - ts)
            if drift > 300:
                res.add("warn", "feed and server disagree",
                        "the body says %ds ago, the server says %ds ago, so "
                        "something between them is serving a copy"
                        % (now - ts, now - lmts))
            else:
                res.add("ok", "server agrees with the body", "within %ds" % drift)
        except Exception:
            pass

    # Stalled: the same header timestamp handed out again, some time later.
    prev = state.get("rt")
    if prev and ts and prev.get("header_ts") == ts:
        gap = int(time.time() - prev.get("seen_at", 0))
        if gap > 90:
            res.add("bad", "live feed is stalled",
                    "the same timestamp %ds apart, so nothing is being published" % gap)
    if ts:
        state["rt"] = {"header_ts": ts, "seen_at": int(time.time()),
                       "entities": feed["entities"]}

    # Thin: a collapse in vehicle count is a fault even when everything parses.
    n = feed["entities"]
    base = state.get("rt_baseline")
    if n == 0:
        res.add("bad", "live feed is empty", "0 vehicles")
    elif base and n < max(5, base * 0.3):
        res.add("bad", "live feed is thin",
                "%d vehicles against a usual %d" % (n, base))
    elif base and n < base * 0.6:
        res.add("warn", "live feed is thin", "%d vehicles against a usual %d" % (n, base))
    else:
        res.add("ok", "live vehicles", "%d" % n)
    if n:
        state["rt_baseline"] = int(base * 0.8 + n * 0.2) if base else n

    # Misplaced: a position outside Zagreb is not a Zagreb tram.
    bad_pos = [p for p in feed["positions"]
               if not (LAT_MIN <= p[0] <= LAT_MAX and LON_MIN <= p[1] <= LON_MAX)]
    if feed["positions"]:
        if bad_pos:
            res.add("bad", "vehicles off the map",
                    "%d of %d outside Zagreb, first at %.4f,%.4f"
                    % (len(bad_pos), len(feed["positions"]), bad_pos[0][0], bad_pos[0][1]))
        else:
            res.add("ok", "vehicle positions", "%d, all inside Zagreb" % len(feed["positions"]))

    # Skew: if the phone's clock is out, every departure is wrong and the
    # feed is innocent. Worth separating, because the fix is a different one.
    if feed["entity_ts"]:
        newest = max(feed["entity_ts"])
        skew = now - newest
        if abs(skew) > 900 and ts and abs(now - ts) > 900:
            res.add("warn", "clock",
                    "the phone and the feed disagree by %d minutes. Check the "
                    "phone's own clock before blaming ZET" % (abs(skew) // 60))
    return feed


def check_static(res, feed):
    """The schedule each app is holding: is it current, and does the live
    feed agree with it. This is the one that catches 'the field does not
    fit the timetable'."""
    for app, spec in CACHES.items():
        z = os.path.join(os.path.expanduser("~"), spec["dir"], "zet_gtfs.zip")
        if not os.path.exists(z):
            res.add("ok", "%s schedule" % app, "no cached copy yet")
            continue
        age_h = (time.time() - os.path.getmtime(z)) / 3600.0
        try:
            with zipfile.ZipFile(z) as zf:
                names = zf.namelist()
                if "trips.txt" not in names:
                    res.add("bad", "%s schedule" % app, "the zip has no trips.txt")
                    continue
                ymd = time.strftime("%Y%m%d")
                covered = None
                if "calendar.txt" in names:
                    covered = False
                    head = None
                    for raw in zf.open("calendar.txt"):
                        line = raw.decode("utf-8", "replace").strip()
                        if head is None:
                            head = [c.strip() for c in line.split(",")]
                            continue
                        row = dict(zip(head, line.split(",")))
                        if row.get("start_date", "0") <= ymd <= row.get("end_date", "9"):
                            covered = True
                            break
                trip_ids = set()
                head = None
                for raw in zf.open("trips.txt"):
                    line = raw.decode("utf-8", "replace").strip()
                    if head is None:
                        head = [c.strip() for c in line.split(",")]
                        continue
                    row = dict(zip(head, line.split(",")))
                    if row.get("trip_id"):
                        trip_ids.add(row["trip_id"])
        except zipfile.BadZipFile:
            res.add("bad", "%s schedule" % app, "the cached zip is not a zip")
            continue
        except Exception as e:
            res.add("bad", "%s schedule" % app, "unreadable: %s" % e)
            continue

        if covered is False:
            res.add("bad", "%s schedule expired" % app,
                    "no service period in it covers today. Refresh it")
        elif age_h > 24 * 8:
            res.add("warn", "%s schedule age" % app, "%d days old" % (age_h / 24))
        else:
            res.add("ok", "%s schedule" % app,
                    "%d trips, %d hours old" % (len(trip_ids), age_h))

        # The agreement check. Live trip ids that the held schedule has never
        # heard of mean the two are from different builds, and every lookup
        # against them silently misses.
        if feed and feed["trip_ids"] and trip_ids:
            live = set(feed["trip_ids"])
            miss = live - trip_ids
            pct = 100.0 * len(miss) / len(live)
            if pct >= 50:
                res.add("bad", "%s does not fit the field" % app,
                        "%.0f%% of live trips are not in this schedule, so the two "
                        "are different builds" % pct)
            elif pct >= 10:
                res.add("warn", "%s partly fits the field" % app,
                        "%.0f%% of live trips are unknown to it" % pct)
            else:
                res.add("ok", "%s fits the field" % app,
                        "%.0f%% of live trips unknown, which is normal churn" % pct)


def check_reachable(res):
    """The static tap itself, without downloading forty megabytes."""
    import urllib.request
    req = urllib.request.Request(STATIC_URL, method="HEAD",
                                 headers={"User-Agent": UA})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            ln = r.headers.get("Content-Length")
            res.add("ok", "schedule tap", "%d%s" % (r.status,
                    ", %s bytes" % ln if ln else ""))
    except Exception as e:
        res.add("warn", "schedule tap", "no answer to a HEAD: %s" % e)


# ---------------------------------------------------------------------------
# refresh
# ---------------------------------------------------------------------------

def refresh(only=None):
    import shutil
    home = os.path.expanduser("~")
    removed, kept, freed = 0, 0, 0
    for app, spec in CACHES.items():
        if only and app != only:
            continue
        base = os.path.join(home, spec["dir"])
        if not os.path.isdir(base):
            continue
        for name in spec["files"]:
            p = os.path.join(base, name)
            if os.path.isfile(p):
                freed += os.path.getsize(p)
                os.remove(p)
                removed += 1
        for name in spec["dirs"]:
            p = os.path.join(base, name)
            if os.path.isdir(p):
                for root, _, files in os.walk(p):
                    for f in files:
                        freed += os.path.getsize(os.path.join(root, f))
                        removed += 1
                shutil.rmtree(p, ignore_errors=True)
        kept += sum(1 for k in spec["keep"] if os.path.exists(os.path.join(base, k)))
    st = _state()
    st.pop("rt", None)
    _save_state(st)
    return removed, kept, freed


# ---------------------------------------------------------------------------

COLOURS = {"ok": "\033[1;32m", "warn": "\033[38;5;214m", "bad": "\033[1;31m"}
OFF = "\033[0m"
MARK = {"ok": "ok  ", "warn": "look", "bad": "FAIL"}


def main(argv):
    cmd = argv[1] if len(argv) > 1 else "check"
    tty = sys.stdout.isatty()

    def paint(level, text):
        return (COLOURS[level] + text + OFF) if tty else text

    if cmd == "refresh":
        removed, kept, freed = refresh()
        print("  %s  %d cached files thrown away, %.1f MB"
              % (paint("ok", "refreshed"), removed, freed / 1048576.0))
        print("  %d keys, indexes and stored timetables left alone" % kept)
        print("  each app rebuilds its schedule the next time it starts")
        if "--check" not in argv:
            return 0
        print("")

    res = Result()
    state = _state()
    feed = check_live(res, state)
    check_static(res, feed)
    check_reachable(res)
    _save_state(state)

    print("")
    # Stacked, like the key tester, for the same reason: a phone terminal
    # is about fifty characters and a feed error arrives longer than that.
    import textwrap
    for level, name, detail in res:
        print("  %s  %s" % (paint(level, MARK[level]), name))
        for chunk in textwrap.wrap(detail, 44, break_long_words=True):
            print("        %s" % chunk)
    print("")
    print("  %d checks, %d faults, %d worth a look"
          % (len(res), res.bad, res.warn))
    if res.bad:
        print("  a refresh is the first thing to try:  maha-commute refresh")
    print("")
    return 1 if res.bad else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
MAHA_STREAM_7c1a
}

maha_emit_keytest() {
  cat <<'MAHA_KEYTEST_7c1a'
#!/usr/bin/env python3
"""keytest.py, written by the MAHA COMMUTE installer.

    python keytest.py            test every key this phone holds
    python keytest.py --file F   also read keys out of a note
    python keytest.py --quiet    one line per key

WHAT THIS IS FOR

`keyring.md` says never test a key speculatively: use the first key not
known dead and let a real request find out. That rule is about the app's
normal running. This is the one place it does not apply, because being
asked "is this key good" IS the job here, and it is asked by hand.

The question actually being asked is never "does the key work". It is one
of five, and they need different answers and different fixes:

    is it a key at all          shape, before a single call is made
    is it accepted              the credential itself
    is the API turned on        a good key on a project with that API off
    is it restricted            a browser key called from a server. This is
                                the one that looks like a dead key and is not
    has the money run out       billing off, or the cap reached

The last one is the reason this exists, and it needs saying plainly:
**neither Google API has an endpoint that reports a balance.** No call
returns how much credit is left. What the wire does say, exactly, is
whether billing is switched off, whether a cap has been hit, and whether
the request was throttled. Anything beyond that is in the Cloud console
and nowhere else, and a tester that claims otherwise is guessing.

NO KEY IS EVER PRINTED. Not in full, not redacted. Each is named by its
prefix, its length and four characters of its hash, which is enough to
tell two keys apart and useless to anybody who reads it. Redaction is
what leaked a key once already: a pattern that recognises secrets is safe
for extraction, where an unknown format fails closed, and unsafe for
redaction, where an unknown format fails open and prints.
"""

import hashlib
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request

APPHOME = os.path.join(os.path.expanduser("~"), ".maha.commute")
UA = "maha.commute-keytest/1 (+https://github.com/markoboskoauroville/MAHA_COMMUTE)"

# Both Google formats. A filter written for AIza alone finds nothing in a
# file full of AQ. keys, and Google has changed this once already, so a
# third format should be assumed to be coming.
KEY_SHAPES = [
    ("google", re.compile(r"AIza[A-Za-z0-9_-]{30,}")),
    ("google", re.compile(r"AQ\.[A-Za-z0-9_.-]{20,}")),
]

# Where each app keeps the key it is actually using. Read so the tester can
# say "the app is not using the key you think it is", which is its own
# whole class of confusion.
APP_KEYFILES = [
    ("shared store", os.path.join(APPHOME, "keys", "google-api.txt")),
    ("day.commute", os.path.expanduser("~/.commute/google-api.txt")),
    ("night.commute", os.path.expanduser("~/.nightcommute/gmaps-api.txt")),
    ("all.commute", os.path.expanduser("~/.all.commute/google-api.txt")),
    ("all.commute gemini", os.path.expanduser("~/.all.commute/gemini-api.txt")),
]

STREETVIEW = ("https://maps.googleapis.com/maps/api/streetview/metadata"
              "?location=45.8131,15.9775&key=%s")
GEOCODE = ("https://maps.googleapis.com/maps/api/geocode/json"
           "?address=Zagreb&key=%s")
GEMINI = "https://generativelanguage.googleapis.com/v1beta/models"

TTY = sys.stdout.isatty()
C = {"ok": "\033[1;32m", "warn": "\033[38;5;214m", "bad": "\033[1;31m",
     "dim": "\033[0;90m", "key": "\033[1;37m", "off": "\033[0m"}
LEVEL_RANK = {"ok": "ok", "warn": "warn", "bad": "bad", "dim": "ok"}
if not TTY:
    C = {k: "" for k in C}


def name_of(key):
    """A key named without being shown. Prefix, length, and four characters
    of a hash: enough to tell two apart, useless to anybody reading it."""
    fp = hashlib.sha256(key.encode()).hexdigest()[:4]
    prefix = key[:4] if key.startswith("AIza") else key[:3]
    return "%s\u2026 %d chars, fp %s" % (prefix, len(key), fp)


def find_keys(text):
    """Keys out of a handwritten note. The file is a working note with
    dates, account names, the word CANCELLED and URLs carrying tracking
    tokens that are the right length and the wrong thing. Shape takes the
    keys and leaves the prose."""
    out = []
    for _provider, rx in KEY_SHAPES:
        for m in rx.finditer(text):
            k = m.group(0).rstrip(".,;:)\"'")
            if k not in out:
                out.append(k)
    return out


def _req(url, headers=None, timeout=25):
    """One place, so no call can forget the User-Agent. A provider behind
    Cloudflare answers a request without one with 403 on every endpoint,
    which looks exactly like a ring of dead keys and is nothing to do with
    the keys."""
    h = {"User-Agent": UA}
    h.update(headers or {})
    req = urllib.request.Request(url, headers=h)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, r.read(), None
    except urllib.error.HTTPError as e:
        return e.code, e.read(), None
    except Exception as e:
        return None, b"", e


def _json(body):
    try:
        return json.loads(body.decode("utf-8", "replace"))
    except Exception:
        return {}


# ---------------------------------------------------------------------------
# the probes
#
# The cheapest legitimate question in each case. Street View METADATA is
# free and is documented as free; the image is not, so the image is never
# asked for. Gemini is asked to list models, which generates nothing.
# ---------------------------------------------------------------------------

def probe_streetview(key):
    status, body, err = _req(STREETVIEW % key)
    if err:
        return ("warn", "no answer", str(err), None)
    d = _json(body)
    s = d.get("status", "")
    msg = d.get("error_message", "")
    if s in ("OK", "ZERO_RESULTS"):
        return ("ok", s, "the key is accepted for Street View", True)
    if s == "REQUEST_DENIED":
        low = msg.lower()
        if "referer" in low or "referrer" in low:
            return ("warn", "browser only",
                    "locked to a web page, so the browser map works and "
                    "anything asked from the terminal does not", False)
        if "not authorized" in low or "api is not enabled" in low or "disabled" in low:
            return ("bad", "api off",
                    "the key is good, Street View Static is off on its project",
                    False)
        if "billing" in low:
            return ("bad", "billing off",
                    "billing is not enabled on the project behind this key",
                    False)
        if "expired" in low:
            return ("bad", "expired", "the key has expired", False)
        return ("bad", "denied", msg or "no reason given", False)
    if s == "OVER_QUERY_LIMIT":
        return ("bad", "over cap",
                "the cap is reached. The key is valid and refused until it "
                "resets or is raised", False)
    if s == "INVALID_REQUEST":
        return ("warn", "invalid request", "the probe is wrong, not the key", None)
    return ("warn", s or "http %s" % status, msg or "unexpected", None)


def probe_geocode(key):
    """A second Google API on the same key. Two APIs answering differently
    is what separates 'this key is dead' from 'this one API is switched
    off', and that is a different afternoon's work to fix."""
    status, body, err = _req(GEOCODE % key)
    if err:
        return ("warn", "no answer", str(err), None)
    d = _json(body)
    s = d.get("status", "")
    msg = d.get("error_message", "")
    if s in ("OK", "ZERO_RESULTS"):
        return ("ok", s, "accepted for Geocoding too", True)
    if s == "REQUEST_DENIED":
        low = msg.lower()
        if "referer" in low or "referrer" in low:
            return ("warn", "browser only", "same restriction here", False)
        if "not authorized" in low or "disabled" in low:
            return ("warn", "api off",
                    "Geocoding is off on this project, which may be deliberate",
                    False)
        if "billing" in low:
            return ("bad", "billing off", "billing is not enabled", False)
        return ("warn", "denied", msg or "no reason given", False)
    if s == "OVER_QUERY_LIMIT":
        return ("bad", "over cap", "the cap has been reached", False)
    return ("warn", s or "http %s" % status, msg or "unexpected", None)


def probe_gemini(key):
    status, body, err = _req(GEMINI, headers={"x-goog-api-key": key})
    if err:
        return ("warn", "no answer", str(err), None)
    d = _json(body)
    if status == 200:
        models = d.get("models", [])
        names = [m.get("name", "").replace("models/", "") for m in models]
        img = [n for n in names if "image" in n]
        detail = "%d models" % len(names)
        if img:
            detail += ", image models present"
        return ("ok", "accepted", detail, True)
    e = d.get("error", {})
    msg = (e.get("message") or "").strip()
    reason = ""
    for det in e.get("details", []) or []:
        if det.get("reason"):
            reason = det["reason"]
            break
    if status == 429 or reason == "RESOURCE_EXHAUSTED":
        # The one that gets lost, and losing it burns working keys.
        return ("warn", "429, throttled",
                "valid and rate limited. This is NOT a dead key and must "
                "never be condemned for it", True)
    if status == 400:
        return ("bad", "invalid key", msg or "rejected", False)
    if status == 403:
        low = msg.lower()
        if "billing" in low:
            return ("bad", "billing off", msg, False)
        if "disabled" in low or "has not been used" in low or reason == "SERVICE_DISABLED":
            return ("bad", "api off",
                    "the Generative Language API is off on this project", False)
        return ("bad", "refused", msg or "403", False)
    if status == 401:
        # Measured 31.8.2026 with a real AQ. key whose last four characters
        # were changed. A malformed key in this format is not read as a bad
        # key but as a bad OAuth token, so the answer is 401 and not 400.
        # The status mapping says 401 is a dead credential, so it is named
        # as one rather than left as a bare number.
        return ("bad", "not accepted", "the credential was refused outright", False)
    if status == 404:
        return ("warn", "404", "the probe URL is wrong, not the key", None)
    return ("warn", "http %s" % status, msg or "unexpected", None)


# ---------------------------------------------------------------------------

WIDTH = 42


def line(level, label, verdict, detail):
    """A phone terminal is about fifty characters and the rule is that
    nothing goes off the screen. Google's own refusals arrive three lines
    long with two URLs in them, so the row is STACKED rather than having
    its columns narrowed: verdict and label on one line, the reason
    underneath, wrapped. Narrowing the columns would not remove the
    clipping, it would only move it to a different word."""
    import textwrap
    # The verdict column is sized to the longest verdict there is, not to a
    # number that looked about right. At nine it clipped "not a maps key" to
    # "not a map", which is a word cut to fit a layout instead of a layout
    # sized to its words.
    print("     %s%-14s%s %s%s%s"
          % (C[level], verdict[:14], C["off"], C["key"], label, C["off"]))
    # A URL in a wrapped message is a single unbreakable word that is
    # longer than the line, so wrapping alone cannot hold the promise.
    # The URLs are dropped: the sentence carries the meaning and the link
    # is not something anybody follows from a phone terminal.
    d = (detail or "").split(" Learn more")[0]
    d = re.sub(r"https?://\S+", "", d)
    d = re.sub(r"\s+", " ", d).strip().rstrip(":").strip()
    for chunk in textwrap.wrap(d, WIDTH, break_long_words=True) or []:
        print("       %s%s%s" % (C["dim"], chunk, C["off"]))


def test_key(key, quiet=False):
    print("\n  %s%s%s" % (C["key"], name_of(key), C["off"]))
    results = {}
    # An AQ. key is a Generative Language credential and Maps has never
    # heard of it. Its refusal there is the correct answer to the wrong
    # question, so it is reported quietly. A tester that paints an expected
    # answer red teaches the person to ignore red.
    gemini_shaped = key.startswith("AQ.")
    for label, fn in (("street view", probe_streetview),
                      ("geocoding", probe_geocode),
                      ("gemini", probe_gemini)):
        level, verdict, detail, good = fn(key)
        if gemini_shaped and label in ("street view", "geocoding") and not good:
            level, verdict = "dim", "not maps"
            detail = "expected: the AQ. format is a Gemini credential"
        results[label] = (level, verdict, good)
        if not quiet:
            line(level, label, verdict, detail)
        time.sleep(0.2)

    maps_ok = results["street view"][2] or results["geocoding"][2]
    gem_ok = results["gemini"][2]
    restricted = any(r[1] == "browser only" for r in results.values())

    if gem_ok and not maps_ok:
        v, lvl = "a Gemini key", "ok"
    elif maps_ok and not gem_ok:
        v, lvl = "a Maps key", "ok"
    elif maps_ok and gem_ok:
        v, lvl = "works for both Maps and Gemini", "ok"
    elif restricted:
        v, lvl = "browser only, locked to a referrer", "warn"
    else:
        v, lvl = "nothing accepted it", "bad"
    print("     %s%-14s%s %s%s%s" % (C[lvl], "verdict", C["off"], C["key"], v, C["off"]))
    return LEVEL_RANK.get(lvl, lvl)


def main(argv):
    keys = []
    seen = set()
    sources = {}

    for label, path in APP_KEYFILES:
        if os.path.exists(path):
            try:
                with open(path, encoding="utf-8", errors="replace") as f:
                    for k in find_keys(f.read()):
                        if k not in seen:
                            seen.add(k)
                            keys.append(k)
                        sources.setdefault(k, []).append(label)
            except Exception:
                pass

    if "--file" in argv:
        p = argv[argv.index("--file") + 1]
        with open(p, encoding="utf-8", errors="replace") as f:
            text = f.read()
        found = find_keys(text)
        print("\n  %s%d keys found by shape in %s%s"
              % (C["dim"], len(found), os.path.basename(p), C["off"]))
        for k in found:
            if k not in seen:
                seen.add(k)
                keys.append(k)
            sources.setdefault(k, []).append("the note")

    if not keys:
        print("\n  no keys on this phone yet. maha-commute key, then p, pastes one.\n")
        return 1

    print("\n  %sKEY TESTER%s  %d keys, none is printed"
          % (C["key"], C["off"], len(keys)))
    print("  %sthe cheapest question each provider has,%s" % (C["dim"], C["off"]))
    print("  %snothing generated, nothing billed%s" % (C["dim"], C["off"]))

    counts = {"ok": 0, "warn": 0, "bad": 0}
    for k in keys:
        lvl = test_key(k, "--quiet" in argv)
        counts[lvl] += 1
        where = sources.get(k, [])
        if where:
            print("     %s%-14s %s%s" % (C["dim"], "held by",
                                        ", ".join(where), C["off"]))

    # Which key each app is really using. An app quietly holding a different
    # key from the one just tested is its own class of confusion, and it is
    # invisible unless somebody compares them.
    print("\n  %swhat each app is actually holding%s" % (C["key"], C["off"]))
    shared = None
    for label, path in APP_KEYFILES:
        if not os.path.exists(path):
            print("     %s%-20s none%s" % (C["dim"], label, C["off"]))
            continue
        with open(path, encoding="utf-8", errors="replace") as f:
            found = find_keys(f.read())
        if not found:
            print("     %s%-20s a file with no key shape in it%s"
                  % (C["warn"], label, C["off"]))
            continue
        fp = hashlib.sha256(found[0].encode()).hexdigest()[:4]
        if label == "shared store":
            shared = fp
            note = ""
        elif shared and fp != shared and "gemini" not in label:
            note = "  differs from the shared store"
        else:
            note = ""
        print("     %-20s fp %s%s" % (label, fp, note))

    print("\n  %d good, %d worth a look, %d refused"
          % (counts["ok"], counts["warn"], counts["bad"]))
    print("  %sno Google API reports a balance. Billing off," % C["dim"])
    print("  a cap reached and throttling are visible above.")
    print("  What is left to spend is only in the console.%s\n" % C["off"])
    return 0 if counts["bad"] == 0 else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
MAHA_KEYTEST_7c1a
}

maha_emit_uninstall() {
  cat <<'MAHA_UNINST_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# uninstall.sh, written by the MAHA COMMUTE installer.
#
#   maha-commute uninstall        the panel, decide item by item
#   maha-commute uninstall --all  everything, still asks twice
#
# WHAT MAKES AN UNINSTALLER HARD IS NOT DELETING. It is knowing what is
# there. These apps were installed by hand, one at a time, over months,
# under names that have since changed, so nothing here assumes: every path
# is looked for on disk and only what is actually found is listed, with its
# size, before a single question is asked.
#
# It also sweeps up what earlier versions left behind. night.commute was
# once called nightram and once nightcommute, v1 of this umbrella installed
# a command called commute, and each of those leaves a file that no current
# installer would ever write and no current uninstaller would think to look
# for. They are listed here by name because forgetting them is how a phone
# ends up with dead commands in the PATH for a year.
#
# NOTHING IS DELETED WITHOUT THE WORD. The full wipe asks for a typed word,
# not a keypress, because a keypress is what a thumb does by accident.

. "$HOME/.maha.commute/env.sh" 2>/dev/null || {
  BIN="${PREFIX:-/data/data/com.termux/files/usr}/bin"
  APPHOME="$HOME/.maha.commute"
  MAHA_APPS="day|day.commute|.commute|v13|8082|the daytime ride|commute_server.py
night|night.commute|.nightcommute|v9|8087|the four night trams|night_server.py
all|all.commute|.all.commute|v39|8084|every station around you|all_commute_server.py"
}

if [ -t 1 ]; then
  AM="\033[38;5;214m"; SAND="\033[38;5;223m"; OK="\033[1;32m"
  BAD="\033[1;31m"; KEY="\033[1;37m"; DIM="\033[0;90m"; OFF="\033[0m"
else
  AM=""; SAND=""; OK=""; BAD=""; KEY=""; DIM=""; OFF=""
fi

ALL=0
[ "${1:-}" = "--all" ] && ALL=1

field() { printf '%s' "$1" | cut -d'|' -f"$2"; }

# Everything that could exist, in the order it should be shown. Kind is what
# it costs to lose: a command is free to reinstall, data is not, and a key
# is the one thing that cannot be rebuilt from this repository at all.
ITEMS=""
add() { ITEMS="$ITEMS$1|$2|$3
"; }

collect() {
  ITEMS=""
  local row id cmd dir
  printf '%s\n' "$MAHA_APPS" | while read -r row; do :; done
  for row in $(printf '%s\n' "$MAHA_APPS" | tr ' ' '\001'); do
    row=$(printf '%s' "$row" | tr '\001' ' ')
    id=$(field "$row" 1); cmd=$(field "$row" 2); dir="$HOME/$(field "$row" 3)"
    [ -x "$BIN/$cmd" ] && add "command" "$BIN/$cmd" "$cmd, the launcher"
    [ -d "$dir" ] && add "data" "$dir" "$cmd data, schedules and settings"
  done
  # the umbrella itself
  [ -x "$BIN/maha-commute" ]        && add "command" "$BIN/maha-commute" "the launcher"
  [ -x "$BIN/maha-commute-update" ] && add "command" "$BIN/maha-commute-update" "the updater"
  [ -x "$BIN/maha.commute" ]        && add "command" "$BIN/maha.commute" "the launcher, short name"
  [ -x "$BIN/maha.commute-update" ] && add "command" "$BIN/maha.commute-update" "the updater, short name"
  [ -d "$APPHOME/payloads" ]        && add "data" "$APPHOME/payloads" "the three cached payloads"
  [ -d "$APPHOME/backup" ]          && add "data" "$APPHOME/backup" "the folder kept before a wipe"
  [ -d "$APPHOME/keys" ]            && add "key"  "$APPHOME/keys" "the shared google key"
  [ -d "$APPHOME" ]                 && add "data" "$APPHOME" "everything else under the umbrella"
  # what earlier versions left behind, and would otherwise stay forever
  [ -x "$BIN/commute" ]      && add "old" "$BIN/commute" "the v1 launcher, replaced by maha-commute"
  [ -x "$BIN/nightram" ]     && add "old" "$BIN/nightram" "an old name for night.commute"
  [ -x "$BIN/nightcommute" ] && add "old" "$BIN/nightcommute" "an older name still"
  [ -d "$HOME/.nightram" ]   && add "old" "$HOME/.nightram" "its folder"
  printf '%s' "$ITEMS"
}

size_of() {
  if [ -d "$1" ]; then du -sh "$1" 2>/dev/null | cut -f1
  elif [ -f "$1" ]; then du -h "$1" 2>/dev/null | cut -f1
  else printf '-'; fi
}

show() {
  local n=0 kind path what colour
  printf "\n  ${AM}+--------------------------------------------+${OFF}\n"
  printf "  ${AM}|${OFF} ${KEY}%-42s${OFF} ${AM}|${OFF}\n" "UNINSTALL, what is on this phone"
  printf "  ${AM}+--------------------------------------------+${OFF}\n"
  printf '%s' "$LIST" | while IFS='|' read -r kind path what; do
    [ -z "$path" ] && continue
    n=$((n+1))
    case "$kind" in
      key)  colour="$BAD" ;;
      data) colour="$SAND" ;;
      old)  colour="$DIM" ;;
      *)    colour="$OK" ;;
    esac
    printf "  ${KEY}%2d${OFF} %b%-6s%b %-28s ${DIM}%5s${OFF}\n" \
      "$n" "$colour" "$kind" "$OFF" "$what" "$(size_of "$path")"
    printf "     ${DIM}%s${OFF}\n" "$path"
  done
  printf "\n"
}

remove_one() {
  local path="$1"
  if [ -e "$path" ]; then
    rm -rf "$path" && printf "  ${OK}gone${OFF} ${DIM}%s${OFF}\n" "$path"
  fi
}

LIST=$(collect)
if [ -z "$LIST" ]; then
  printf "\n  ${DIM}nothing of MAHA COMMUTE is on this phone.${OFF}\n\n"
  exit 0
fi

show
COUNT=$(printf '%s' "$LIST" | grep -c '|')
printf "  ${DIM}%s things, %s in total${OFF}\n" "$COUNT" \
  "$(du -shc $(printf '%s' "$LIST" | cut -d'|' -f2 | tr '\n' ' ') 2>/dev/null | tail -1 | cut -f1)"

if [ "$ALL" != 1 ]; then
  printf "\n  ${KEY}o${OFF} ${DIM}old versions only: the names earlier installs left${OFF}\n"
  printf "  ${DIM}    behind, keeping everything that works today${OFF}\n"
  printf "  ${KEY}u${OFF} ${DIM}the umbrella only, leaving the three apps working${OFF}\n"
  printf "  ${KEY}a${OFF} ${DIM}everything, all of it${OFF}\n"
  printf "  ${KEY}q${OFF} ${DIM}nothing, go back${OFF}\n"
  printf "\n  ${AM}>${OFF} "
  IFS= read -r ANS || ANS="q"
  case "$ANS" in
    u|U)
      printf "\n  ${DIM}taking away the umbrella and leaving the apps alone${OFF}\n\n"
      remove_one "$BIN/maha-commute"
      remove_one "$BIN/maha-commute-update"
      remove_one "$BIN/commute"
      remove_one "$APPHOME"
      printf "\n  ${OK}done.${OFF} ${DIM}day.commute, night.commute and all.commute${OFF}\n"
      printf "  ${DIM}still work exactly as they did before.${OFF}\n\n"
      exit 0 ;;
    o|O)
      # Only what an earlier version left. Nothing here is in use: the v1
      # launcher was replaced by maha-commute, and nightram and
      # nightcommute are names night.commute has not answered to for a
      # long time. The apps and all their data are untouched.
      printf "\n  ${DIM}clearing what earlier versions left behind${OFF}\n\n"
      gone=0
      for old in "$BIN/commute" "$BIN/nightram" "$BIN/nightcommute" \
                 "$HOME/.local/bin/nightram" "$HOME/.local/bin/nightcommute" \
                 "$HOME/.nightram"; do
        [ -e "$old" ] && { remove_one "$old"; gone=$((gone+1)); }
      done
      if [ "$gone" = 0 ]; then
        printf "  ${DIM}nothing old was found. This phone is already clean.${OFF}\n"
      else
        printf "\n  ${OK}%s removed.${OFF} ${DIM}Every working app is untouched.${OFF}\n" "$gone"
      fi
      printf "\n"
      exit 0 ;;
    a|A) : ;;
    *) printf "\n  ${DIM}nothing was changed.${OFF}\n\n"; exit 0 ;;
  esac
fi

# The second question, and it is typed. A keypress is what a thumb does by
# accident; a word is a decision. The word is in the language of the thing
# being lost rather than a bare yes.
printf "\n  ${BAD}This removes all three apps, their schedules, their${OFF}\n"
printf "  ${BAD}settings and the shared key, on this phone.${OFF}\n"
printf "\n  ${DIM}The three original installers still exist and put every${OFF}\n"
printf "  ${DIM}app back. What cannot be put back is the key, unless a${OFF}\n"
printf "  ${DIM}copy of it is somewhere else.${OFF}\n"
if [ -s "$APPHOME/keys/google-api.txt" ]; then
  printf "\n  ${SAND}the shared key is %s characters long and is about to go${OFF}\n" \
    "$(tr -d ' \r\n' < "$APPHOME/keys/google-api.txt" | wc -c | tr -d ' ')"
fi
printf "\n  ${KEY}type the word${OFF} ${SAND}wipe${OFF} ${KEY}to go ahead${OFF}\n"
printf "\n  ${AM}>${OFF} "
IFS= read -r W || W=""
if [ "$W" != "wipe" ]; then
  printf "\n  ${DIM}nothing was changed.${OFF}\n\n"
  exit 0
fi

printf "\n  ${DIM}stopping anything that is running${OFF}\n"
for proc in commute_server.py night_server.py all_commute_server.py; do
  pkill -f "$proc" 2>/dev/null && printf "  ${OK}stopped${OFF} ${DIM}%s${OFF}\n" "$proc"
done
sleep 1

printf "\n"
printf '%s' "$LIST" | cut -d'|' -f2 | while read -r p; do
  [ -n "$p" ] && remove_one "$p"
done

printf "\n  ${OK}MAHA COMMUTE is off this phone.${OFF}\n"
printf "  ${DIM}Nothing in \$PREFIX/bin is left from it:${OFF}\n"
LEFT=0
for c in maha-commute maha-commute-update commute day.commute night.commute all.commute; do
  [ -e "$BIN/$c" ] && { printf "  ${BAD}still there: %s${OFF}\n" "$BIN/$c"; LEFT=1; }
done
[ "$LEFT" = 0 ] && printf "  ${DIM}checked six names, none remains${OFF}\n"
printf "\n"
MAHA_UNINST_7c1a
}

maha_emit_update() {
  cat <<'MAHA_UPDATE_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# update.sh, written by the MAHA COMMUTE installer.
#
#   maha-commute-update              find a newer installer and run it
#   maha-commute-update <file>       use this file
#   maha-commute-update --check      say what is available, change nothing
#
# ONE UPDATER FOR ALL THREE APPS, and it updates them the way they are
# actually delivered.
#
# WHERE IT LOOKS, IN ORDER
#
#   1  a file given on the command line
#   2  github, anonymously, which is the automatic route
#   3  a newer installer already downloaded on the phone
#
# NO CREDENTIAL. MAHA_COMMUTE is public, so the fetch is a plain unsigned
# request. Nothing is stored on the phone, so there is nothing on the phone
# to lose, and an update over a borrowed connection reveals only that
# somebody asked for a public file.
#
# THE FROZEN ADDRESS IS VERSION, NOT THE INSTALLER. VERSION holds a single
# number; the installer it names carries that number at both ends. That is
# how the filename keeps its number at both ends while the updater still has
# one fixed thing to ask for.
#
#   maha-commute-update --check      say what is available, change nothing
#
# WHAT IT ADDS OVER RUNNING THE FILE BY HAND
#
#   it finds the newest one, wherever the phone put it
#   it refuses to run a file that did not arrive whole
#   it installs exactly the apps that are installed now, so an update
#     never quietly adds an app that was deliberately left out, and never
#     drops one that was wanted
#   it says the version it is coming from and going to, before it starts

set -e
. "$HOME/.maha.commute/env.sh"

if [ -t 1 ]; then
  AM="\033[38;5;214m"; SAND="\033[38;5;223m"; OK="\033[1;32m"
  BAD="\033[1;31m"; KEY="\033[1;37m"; DIM="\033[0;90m"; OFF="\033[0m"
else
  AM=""; SAND=""; OK=""; BAD=""; KEY=""; DIM=""; OFF=""
fi

CAND=""
MODE="run"
ONLY=""

# maha-commute-update [--check] [--app ID] [file]. --app updates one app and
# leaves the others, running or not, exactly as they are.
while [ $# -gt 0 ]; do
  case "$1" in
    --check) MODE="check" ;;
    --app)   ONLY="${2:-}"; shift ;;
    -*)      ;;
    *)       if [ -f "$1" ]; then CAND="$1"
             else printf "update: no such file: %s\n" "$1"; exit 2; fi ;;
  esac
  shift
done
if [ -n "$ONLY" ] && ! printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1 | grep -qx "$ONLY"; then
  printf "update: %s is not one of the apps\n" "$ONLY"; exit 2
fi

RAW="https://raw.githubusercontent.com/markoboskoauroville/MAHA_COMMUTE/main"

# What github is offering. A plain unsigned request: no token, no header,
# nothing kept afterwards.
REMOTE_V=""
if [ -n "$CAND" ]; then
  :   # a file was given, so github is not asked
elif command -v curl >/dev/null 2>&1; then
  REMOTE_V=$(curl -fsSL --max-time 20 "$RAW/VERSION" 2>/dev/null | tr -cd '0-9' | head -c 6)
elif command -v wget >/dev/null 2>&1; then
  REMOTE_V=$(wget -qO- --timeout=20 "$RAW/VERSION" 2>/dev/null | tr -cd '0-9' | head -c 6)
fi

HERE="${MAHA_VERSION#v}"
if [ -n "$CAND" ]; then
  :
elif [ -n "$REMOTE_V" ]; then
  if [ "$REMOTE_V" -gt "$HERE" ] 2>/dev/null; then
    printf "\n  ${KEY}v%s is available${OFF} ${DIM}(this phone has v%s)${OFF}\n" "$REMOTE_V" "$HERE"
    if [ "$MODE" = "check" ]; then printf "\n"; exit 0; fi
    NAME="$REMOTE_V-maha_commute_v$REMOTE_V.sh"
    DL="$APPHOME/tmp/$NAME"
    mkdir -p "$APPHOME/tmp"
    printf "  ${DIM}fetching %s${OFF}\n" "$NAME"
    if curl -fsSL --max-time 300 "$RAW/$NAME" -o "$DL" 2>/dev/null ||
       wget -qO "$DL" --timeout=300 "$RAW/$NAME" 2>/dev/null; then
      CAND="$DL"
    else
      printf "  ${BAD}the fetch failed. Nothing was changed.${OFF}\n\n"; exit 1
    fi
  else
    printf "\n  ${OK}v%s is the newest there is.${OFF}\n\n" "$HERE"
    exit 0
  fi
else
  printf "\n  ${SAND}github did not answer.${OFF} ${DIM}Looking on the phone instead.${OFF}\n"
fi

# Where a phone puts a downloaded file, in the order it is likely to be.
if [ -z "$CAND" ]; then
  NEWEST=""
  for d in "$HOME/storage/downloads" "$HOME/downloads" "$HOME/Downloads" \
           "$HOME/storage/shared/Download" "$HOME"; do
    [ -d "$d" ] || continue
    for f in "$d"/*maha_commute_v*.sh; do
      [ -f "$f" ] || continue
      if [ -z "$NEWEST" ] || [ "$f" -nt "$NEWEST" ]; then NEWEST="$f"; fi
    done
  done
  CAND="$NEWEST"
fi

printf "\n  ${AM}%s${OFF}  ${KEY}MAHA COMMUTE${OFF} ${DIM}update${OFF}\n\n" "ॐ"

if [ -z "$CAND" ] || [ ! -f "$CAND" ]; then
  printf "  ${SAND}no installer found to update from.${OFF}\n\n"
  printf "  ${DIM}Download the newest %s-maha_commute_v%s.sh, then run${OFF}\n" "N" "N"
  printf "  ${DIM}maha-commute-update again. It looks in Downloads and in the${OFF}\n"
  printf "  ${DIM}home folder. A path can also be given:${OFF}\n"
  printf "  ${DIM}  maha-commute-update ~/storage/downloads/2-maha_commute_v2.sh${OFF}\n\n"
  printf "  ${DIM}nothing was changed${OFF}\n\n"
  exit 1
fi

printf "  ${DIM}found${OFF} %s\n" "$CAND"

# ---------------------------------------------------------------------
# Four checks before it is allowed to replace anything. A truncated file
# that gets installed is worse than an update that failed, because the
# failure is silent and arrives later.
# ---------------------------------------------------------------------
fails=0
sz=$(wc -c < "$CAND" | tr -d ' ')
if [ "$sz" -ge 400000 ]; then
  printf "  ${OK}ok${OFF}    ${DIM}size, %s bytes${OFF}\n" "$sz"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}size, %s bytes, too small to hold three apps${OFF}\n" "$sz"
  fails=$((fails+1))
fi
if head -1 "$CAND" | grep -q '^#!'; then
  printf "  ${OK}ok${OFF}    ${DIM}it is a script${OFF}\n"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}the first line is not a shebang${OFF}\n"; fails=$((fails+1))
fi
# The exit status is not the check. A file cut in the middle of a heredoc
# makes bash -n warn on stderr and exit zero, so the absence of output is
# what is being tested.
nout=$(bash -n "$CAND" 2>&1 || true)
if [ -z "$nout" ]; then
  printf "  ${OK}ok${OFF}    ${DIM}parses, and said nothing at all${OFF}\n"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}%s${OFF}\n" "$(printf '%s' "$nout" | head -1)"
  fails=$((fails+1))
fi
if tail -1 "$CAND" | grep -q '^# MAHA_COMMUTE_SENTINEL'; then
  printf "  ${OK}ok${OFF}    ${DIM}%s${OFF}\n" "$(tail -1 "$CAND" | cut -c3-)"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}the file ends early${OFF}\n"; fails=$((fails+1))
fi

if [ "$fails" != 0 ]; then
  printf "\n  ${BAD}%s of 4 checks failed. Nothing was changed.${OFF}\n" "$fails"
  printf "  ${DIM}download the file again${OFF}\n\n"
  exit 1
fi

NEW=$(grep -m1 '^MAHA_VERSION=' "$CAND" | cut -d'"' -f2)
printf "\n  ${DIM}this phone has${OFF} ${SAND}%s${OFF}${DIM}, the file is${OFF} ${SAND}%s${OFF}\n" \
  "$MAHA_VERSION" "${NEW:-unknown}"
if [ "$NEW" = "$MAHA_VERSION" ]; then
  printf "  ${DIM}the same version. Running it again changes nothing and is safe.${OFF}\n"
fi

# The apps that are installed now, so the update preserves the choice
# that was made rather than making it again.
PICK=""
n=0
for id in $(printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1); do
  n=$((n+1))
  cmd=$(printf '%s\n' "$MAHA_APPS" | grep "^$id|" | cut -d'|' -f2)
  if [ -n "$ONLY" ] && [ "$id" != "$ONLY" ]; then continue; fi
  [ -x "$BIN/$cmd" ] && PICK="$PICK$n"
done
if [ -n "$ONLY" ]; then
  printf "  ${DIM}updating only${OFF} ${SAND}%s${OFF}${DIM}; the other apps are left as they are${OFF}\n" "$ONLY"
fi
if [ -z "$PICK" ]; then
  printf "  ${DIM}no apps are installed, so the update installs none of them${OFF}\n"
  PICK="n"
else
  printf "  ${DIM}installed now, and kept:${OFF}"
  for id in $(printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1); do
    cmd=$(printf '%s\n' "$MAHA_APPS" | grep "^$id|" | cut -d'|' -f2)
    if [ -n "$ONLY" ] && [ "$id" != "$ONLY" ]; then continue; fi
    [ -x "$BIN/$cmd" ] && printf " ${SAND}%s${OFF}" "$cmd"
  done
  printf "\n"
fi

# --check only describes. It must not offer to install, with a file or without.
if [ "$MODE" = "check" ]; then
  printf "\n  ${DIM}--check: nothing was changed${OFF}\n\n"; exit 0
fi

printf "\n  ${KEY}Enter${OFF} ${DIM}install it${OFF}    ${KEY}n${OFF} ${DIM}stop, change nothing${OFF}\n"
printf "\n  ${AM}>${OFF} "
IFS= read -r ans || ans="n"
case "$ans" in [nN]*) printf "\n  ${DIM}nothing was changed${OFF}\n\n"; exit 0 ;; esac

printf "\n"
exec bash "$CAND" --offline --apps "$PICK"
MAHA_UPDATE_7c1a
}

# ---------------------------------------------------------------
# --verify, which changes nothing
#
# The honest limit of this switch: a file damaged badly enough may
# never reach this code at all. The check that matters runs on a file
# you have not run yet, and that one is tools/verify_installer.sh in
# the repository. This is the convenience version.
# ---------------------------------------------------------------
if [ "$VERIFY_ONLY" = "1" ]; then
  SELF="$0"
  printf "\n  ${KEY}verifying${OFF} ${DIM}%s${OFF}\n\n" "$SELF"
  vfail=0
  sz=$(wc -c < "$SELF" | tr -d ' ')
  if [ "$sz" -ge 400000 ]; then
    printf "  ${OK}size${OFF}      ${DIM}%s bytes${OFF}\n" "$sz"
  else
    printf "  ${BAD}size${OFF}      ${DIM}%s bytes, too small to hold three apps${OFF}\n" "$sz"
    vfail=$((vfail+1))
  fi
  if head -1 "$SELF" | grep -q '^#!'; then
    printf "  ${OK}shebang${OFF}   ${DIM}it is a script${OFF}\n"
  else
    printf "  ${BAD}shebang${OFF}   ${DIM}first line is not a shebang${OFF}\n"; vfail=$((vfail+1))
  fi
  nout=$(bash -n "$SELF" 2>&1 || true)
  if [ -z "$nout" ]; then
    printf "  ${OK}parse${OFF}     ${DIM}bash -n said nothing at all${OFF}\n"
  else
    printf "  ${BAD}parse${OFF}     ${DIM}%s${OFF}\n" "$(printf '%s' "$nout" | head -1)"
    vfail=$((vfail+1))
  fi
  if tail -1 "$SELF" | grep -q '^# MAHA_COMMUTE_SENTINEL'; then
    printf "  ${OK}sentinel${OFF}  ${DIM}the last line is present${OFF}\n"
  else
    printf "  ${BAD}sentinel${OFF}  ${DIM}the file ends early${OFF}\n"; vfail=$((vfail+1))
  fi
  printf "\n  ${DIM}4 checks, %s failed${OFF}\n\n" "$vfail"
  [ "$vfail" = "0" ] || exit 1
  exit 0
fi

# ---------------------------------------------------------------
# the banner
# ---------------------------------------------------------------
clear 2>/dev/null || true
printf "\n"
printf "  ${AM}%s${OFF}  ${KEY}MAHA COMMUTE${OFF}  ${DIM}installer %s${OFF}\n" "ॐ" "$MAHA_VERSION"
printf "  ${DIM}day, night and all of Zagreb, under one word${OFF}\n\n"

# ---------------------------------------------------------------
# is this a phone
# ---------------------------------------------------------------
step "checking Termux"
if [ -z "${PREFIX:-}" ] || [ ! -d "$BIN" ]; then
  fail_ "this installer is for Termux on Android"
  printf "\n  ${DIM}nothing was written.${OFF}\n\n"
  exit 1
fi
done_

# ---------------------------------------------------------------
# what is here already, before anything is asked
# ---------------------------------------------------------------
have() { command -v "$1" >/dev/null 2>&1; }
HAVE_PY=0;   have python  && HAVE_PY=1
have python3 && HAVE_PY=1
HAVE_OPEN=0; have termux-open-url && HAVE_OPEN=1
# termux-open-url comes from termux-tools, which every Termux has, so it says
# nothing about the termux-api PACKAGE (field test v21, F9). termux-location is
# the command only that package brings.
HAVE_TAPI=0; have termux-location && HAVE_TAPI=1
HAVE_FUSER=0; have fuser && HAVE_FUSER=1
HAVE_SHA=0;  have sha256sum && HAVE_SHA=1
HAVE_PGREP=0; have pgrep && HAVE_PGREP=1
HAVE_B64=0;  have base64 && HAVE_B64=1
REQ_MISSING=0
[ "$HAVE_PY" = "0" ] && REQ_MISSING=$((REQ_MISSING+1))

dep_row() {
  if [ "$2" = "1" ]; then
    printf "    ${OK}ok${OFF}       ${SAND}%-14s${OFF} ${DIM}%s${OFF}\n" "$1" "$3"
  elif [ "$4" = "req" ]; then
    printf "    ${BAD}MISSING${OFF}  ${SAND}%-14s${OFF} ${DIM}%s${OFF}\n" "$1" "$3"
  else
    printf "    ${DIM}absent   %-14s %s${OFF}\n" "$1" "$3"
  fi
}
printf "\n  ${KEY}what this phone has${OFF}\n"
dep_row "python"       "$HAVE_PY"    "all three servers"        "req"
dep_row "termux-api"   "$HAVE_TAPI"  "GPS and notifications"    "opt"
dep_row "fuser"        "$HAVE_FUSER" "frees a busy port"        "opt"
dep_row "procps"       "$HAVE_PGREP" "finds and stops servers"  "opt"
dep_row "sha256sum"    "$HAVE_SHA"   "checks the payloads"      "opt"
dep_row "base64"       "$HAVE_B64"   "used by all.commute"      "opt"
printf "\n"

# ---------------------------------------------------------------
# which apps
#
# All three, always. There used to be a picker here and it was the wrong
# question: the answer was always all three, and asking it once per install
# was a keystroke charged for nothing. --apps still exists for a test that
# needs to install a subset, and nobody types it.
# ---------------------------------------------------------------
if [ -n "$PICK" ]; then
  CHOSEN=$(maha_parse_pick "$PICK") || {
    printf "  ${BAD}--apps %s is not something I can read${OFF}\n\n" "$PICK"; exit 2; }
else
  CHOSEN=$(app_ids | tr '\n' ' ')
fi
# ---------------------------------------------------------------
# ---------------------------------------------------------------
# dependencies, decided rather than asked
#
# Present ones are left alone. Missing ones are fetched if anything is
# missing at all and the network answers. There is no question here because
# there was never a real choice in it: nobody wants a half installed app,
# and the offline case is what happens on its own when the network does not
# answer. --offline still forces the old behaviour for a test.
# ---------------------------------------------------------------
NEED=""
[ "$HAVE_PY" = "0" ]    && NEED="$NEED python"
[ "$HAVE_TAPI" = "0" ]  && NEED="$NEED termux-api"
[ "$HAVE_FUSER" = "0" ] && NEED="$NEED psmisc"
[ "$HAVE_PGREP" = "0" ] && NEED="$NEED procps"

if [ "$MODE" = "offline" ]; then
  step "dependencies"; skip_
elif [ -z "$NEED" ]; then
  step "dependencies"; printf " ${OK}all present${OFF}\n"
else
  printf "  ${DIM}missing:${OFF}%s\n" "$NEED"
  for pkgname in $NEED; do
    step "installing $pkgname"
    if pkg install -y "$pkgname" >/dev/null 2>&1; then done_; else fail_ "not fetched"; fi
  done
  command -v python >/dev/null 2>&1 || command -v python3 >/dev/null 2>&1 && HAVE_PY=1
fi
# The package is only half of Termux:API: the commands talk to an APP, which is
# a separate install from F-Droid. Say so, plainly, when pm can tell us it is not.
if have pm && ! pm list packages 2>/dev/null | grep -q 'package:com.termux.api$'; then
  printf "  ${DIM}the Termux:API app (F-Droid) is not installed. GPS through Termux needs it.${OFF}\n"
fi
# ---------------------------------------------------------------
# storage, asked for rather than left to the person
#
# termux-app.md section 8 says termux-setup-storage is run by hand and nothing
# can do it for you. What nothing can do is TAP ALLOW: the command can be run,
# and it raises Android's own popup. Marko, 3.10.2026, for a friend who
# installed on a phone that had never been set up: the installer should do
# that step too. So it asks, waits for the tap, and carries on either way,
# because storage is only for reading a key file from Downloads and an install
# without it is a working install.
#
# It comes before the key search below for a reason: on a new phone the key
# file in Downloads is invisible until this has been allowed.
# ---------------------------------------------------------------
storage_ok() { [ -d "$HOME/storage/downloads" ] && ls "$HOME/storage/downloads" >/dev/null 2>&1; }
STORAGE="n/a"
step "storage"
if storage_ok; then
  STORAGE="allowed"; printf " ${OK}allowed${OFF}\n"
elif ! have termux-setup-storage; then
  skip_
else
  printf " ${DIM}tap Allow on the popup${OFF}"
  # An old ~/storage makes the command ask y or n first. It is answered here,
  # and the input is closed so it can never read the installer's own text.
  { printf 'y\n' | termux-setup-storage; } </dev/null >/dev/null 2>&1 &
  _w=0
  while [ "$_w" -lt "${MAHA_STORAGE_WAIT:-45}" ]; do
    storage_ok && break
    sleep 1; _w=$((_w+1))
  done
  if storage_ok; then STORAGE="allowed"; printf "\r"; step "storage"; printf " ${OK}allowed${OFF}\n"
  else STORAGE="not allowed"; printf "\n  ${DIM}not allowed, and that is fine: it is only for key files${OFF}\n"; fi
fi

# ---------------------------------------------------------------
# the google key
#
# Looked for in this order, and asked for only when every one of them
# comes back empty. The shared store wins, then any app already on the
# phone, then a file dropped in Downloads. The key is never printed.
# ---------------------------------------------------------------
step "google maps key"
mkdir -p "$KEYDIR"; chmod 700 "$KEYDIR" 2>/dev/null || true
FOUND=""
if maha_key_ok "$KEYFILE"; then
  FOUND="the shared store"
else
  for c in "$HOME/.commute/google-api.txt" \
           "$HOME/.nightcommute/gmaps-api.txt" \
           "$HOME/.all.commute/google-api.txt" \
           "./google-api.txt" "./Google-maps-api.txt" \
           "$HOME/storage/downloads/google-api.txt" \
           "$HOME/storage/downloads/Google-maps-api.txt" \
           "$HOME/downloads/google-api.txt"; do
    if maha_key_ok "$c"; then
      grep -v '^[[:space:]]*$' "$c" | head -1 | maha_clean_key > "$KEYFILE"
      chmod 600 "$KEYFILE"
      FOUND="$c"
      break
    fi
  done
fi
if [ -n "$FOUND" ]; then
  printf " ${OK}found${OFF} ${DIM}(%s)${OFF}\n" "$FOUND"
  ASK_KEY=0
else
  skip_
  ASK_KEY=1
fi

if [ "$ASK_KEY" = "1" ]; then
  printf "  ${DIM}no google key here yet. The apps work without one: the maps${OFF}\n"
  printf "  ${DIM}draw, the photographs do not.${OFF} ${SAND}maha-commute key${OFF} ${DIM}adds one.${OFF}\n"
fi

# ---------------------------------------------------------------
# the umbrella itself
#
# Everything under ~/.maha.commute is written before any app is
# installed, so that a failure inside one app still leaves a working
# menu behind and the other two can be added from it.
# ---------------------------------------------------------------
step "the umbrella"
mkdir -p "$APPHOME" "$PAYDIR" "$STAMPDIR" "$APPHOME/tmp"
chmod 700 "$APPHOME/tmp" 2>/dev/null || true
rm -f "$PAYDIR"/*.new 2>/dev/null || true
{
  printf '# written by the MAHA COMMUTE installer %s\n' "$MAHA_VERSION"
  printf 'MAHA_VERSION=%s\n' "$MAHA_VERSION"
  printf 'BIN="%s"\n' "$BIN"
  # THESE FIVE STAY UNEXPANDED, and the reason is the whole of this phone.
  # /root and /data/data/com.termux/files/home are two spellings of ONE
  # directory: proot-distro binds the Termux home onto /root. Inside proot
  # $HOME is /root, in a plain Termux shell it is the long path, and both
  # land on the same files. env.sh is written into that shared directory
  # and is sourced by BOTH shells.
  #
  # So expanding $HOME here writes down whichever shell happened to run the
  # installer. Installed from inside proot, env.sh said APPHOME=/root/...,
  # and /root does not exist outside proot. The menu still found env.sh, by
  # $HOME, and then obeyed it: mkdir -p "$RUNDIR" failed, the redirect to
  # "$RUNDIR/$id.log" failed, the app was never launched at all, and the
  # menu sat forever on "waiting for port 8082" with the quadrant empty.
  # The one visible complaint was a line number in a shell script.
  #
  # Written unexpanded, they resolve in the shell that sources them and are
  # right in both. Everything else the installer writes is already
  # $HOME-relative; env.sh was the single file that was not.
  printf 'APPHOME="$HOME/.maha.commute"\n'
  printf 'PAYDIR="$APPHOME/payloads"\n'
  printf 'KEYDIR="$APPHOME/keys"\n'
  printf 'KEYFILE="$KEYDIR/google-api.txt"\n'
  printf 'STAMPDIR="$APPHOME/installed"\n'
  printf 'MAHA_APPS="%s"\n' "$MAHA_APPS"
} > "$APPHOME/env.sh.new"
mv -f "$APPHOME/env.sh.new" "$APPHOME/env.sh"
done_

step "payloads, all three"
for id in $(app_ids); do
  maha_emit_payload "$id" > "$PAYDIR/$id.payload.sh.new"
  mv -f "$PAYDIR/$id.payload.sh.new" "$PAYDIR/$id.payload.sh"
  chmod 600 "$PAYDIR/$id.payload.sh"
done
{
  for id in $(app_ids); do
    printf '%s|%s\n' "$id" "$(wc -c < "$PAYDIR/$id.payload.sh" | tr -d ' ')"
  done
} > "$PAYDIR/SIZES"
if [ "$HAVE_SHA" = "1" ]; then
  ( cd "$PAYDIR" && sha256sum day.payload.sh night.payload.sh all.payload.sh > SHA256SUMS )
fi
done_

step "the install routine"
maha_emit_install_one | install_command "$APPHOME/install-one.sh"
done_

step "the stream checker"
maha_emit_stream > "$APPHOME/stream.py.new"
mv -f "$APPHOME/stream.py.new" "$APPHOME/stream.py"
done_

step "the key tester"
maha_emit_keytest > "$APPHOME/keytest.py.new"
mv -f "$APPHOME/keytest.py.new" "$APPHOME/keytest.py"
done_

step "the updater"
maha_emit_update | install_command "$APPHOME/update.sh"
done_

step "the uninstaller"
maha_emit_uninstall | install_command "$APPHOME/uninstall.sh"
done_

step "the launcher"
maha_emit_menu | install_command "$BIN/maha-commute"
done_

step "the updater command"
printf '#!%s\nexec bash "%s/update.sh" "$@"\n' "$BIN/bash" "$APPHOME" \
  | install_command "$BIN/maha-commute-update"
done_

# v18: the names Marko types. maha.commute opens the launcher, and
# maha.commute-update fetches the newest suite from GitHub. The hyphen names
# stay, because they are in old notes and in people's fingers.
step "maha.commute and maha.commute-update"
printf '#!%s\nexec "%s/maha-commute" "$@"\n' "$BIN/bash" "$BIN" | install_command "$BIN/maha.commute"
printf '#!%s\nexec bash "%s/update.sh" "$@"\n' "$BIN/bash" "$APPHOME" | install_command "$BIN/maha.commute-update"
done_

# v1 of this umbrella left a command called commute. Leaving it behind
# means two launchers on the PATH, one of them stale, and the stale one is
# the shorter word so it is the one that gets typed. It is replaced by a
# line that points at the new name rather than deleted, because a command
# that vanishes with no explanation reads as a broken install.
if [ -f "$BIN/commute" ] && ! grep -q 'maha-commute' "$BIN/commute" 2>/dev/null; then
  step "the old commute command"
  {
    printf '#!%s\n' "$BIN/bash"
    printf '# left by MAHA COMMUTE v2. The launcher is called maha-commute now.\n'
    printf 'printf "\\n  this is maha-commute now.\\n\\n"\n'
    printf 'exec "%s/maha-commute" "$@"\n' "$BIN"
  } | install_command "$BIN/commute"
  done_
fi

# ---------------------------------------------------------------
# the apps
# ---------------------------------------------------------------
# What actually moved.
#
# An update that reinstalls all three every time is three apps rebuilding
# their caches to no purpose, and it hides the one thing worth reading: which
# app changed. So each app is compared against the checksum of the payload
# that is on the phone, and an app whose payload is identical is not touched
# at all.
payload_sha() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$PAYDIR/$1.payload.sh" | cut -d" " -f1
  else
    wc -c < "$PAYDIR/$1.payload.sh" | tr -d ' '
  fi
}

FAILED=""
INSTALLED=""
UNCHANGED=""
for id in $CHOSEN; do
  want=$(payload_sha "$id")
  have=$(cat "$STAMPDIR/$id.sha" 2>/dev/null || printf 'none')
  if is_installed "$id" && [ "$want" = "$have" ]; then
    UNCHANGED="$UNCHANGED $id"
    continue
  fi
  if bash "$APPHOME/install-one.sh" "$id" "--$MODE"; then
    INSTALLED="$INSTALLED $id"
  else
    FAILED="$FAILED $id"
  fi
done

# The key reaches every app that is here, from the one shared store. It is done
# after the apps, not inside them, so a key found late (or an app reinstalled on
# its own) still gets it (field test v21, F2: all.commute never received it).
bash "$APPHOME/install-one.sh" --sync-key >/dev/null 2>&1 || true

# ---------------------------------------------------------------
# what happened
# ---------------------------------------------------------------
printf "\n"
printf "  ${AM}%s${OFF}  ${KEY}MAHA COMMUTE${OFF}  ${DIM}%s${OFF}\n\n" "ॐ" "$MAHA_VERSION"
for id in $(app_ids); do
  row=$(app_row "$id"); cmd=$(field "$row" 2); port=$(field "$row" 5)
  if is_installed "$id"; then
    printf "    ${OK}on${OFF}   ${SAND}%-15s${OFF} ${DIM}%s, port %s${OFF}\n" \
      "$cmd" "$(stamped_version "$id")" "$port"
  else
    printf "    ${DIM}off  %-15s add it from the menu${OFF}\n" "$cmd"
  fi
done
if [ -n "$INSTALLED" ]; then
  printf "\n    ${OK}updated:${OFF}"
  for id in $INSTALLED; do printf " ${SAND}%s${OFF}" "$(field "$(app_row "$id")" 2)"; done
  printf "\n"
fi
if [ -n "$UNCHANGED" ]; then
  printf "    ${DIM}already current, left alone:%s${OFF}\n" \
    "$(for id in $UNCHANGED; do printf ' %s' "$(field "$(app_row "$id")" 2)"; done)"
fi
if [ -n "$FAILED" ]; then
  printf "\n    ${BAD}did not finish:${OFF}${DIM}%s${OFF}\n" "$FAILED"
fi
printf "\n  type ${KEY}maha.commute${OFF} ${DIM}for the launcher, ${OFF}${KEY}maha.commute-update${OFF} ${DIM}for the newest version${OFF}\n"
printf "  ${DIM}or the app name on its own: day.commute, night.commute, all.commute${OFF}\n"
printf "\n  ${DIM}the three payloads are kept in %s${OFF}\n" "$PAYDIR"
printf "  ${DIM}so any app can be added or removed later with no download${OFF}\n"
if [ "$HAVE_PY" = "0" ]; then
  printf "\n  ${SAND}python is still missing. Run this again with the internet on.${OFF}\n"
fi
if [ "$STORAGE" = "not allowed" ]; then
  printf "\n  ${DIM}to read a key file from Downloads, run termux-setup-storage${OFF}\n"
  printf "  ${DIM}and tap Allow. Nothing else needs it.${OFF}\n"
fi
printf "\n"

